package main

/*
#cgo LDFLAGS: -l:libsqlite3.a -lm -ldl -lpthread
#include <sqlite3.h>
#include <stdlib.h>

static int zk_bind_text(sqlite3_stmt *s, int i, const char *p, int n) {
