import "C"

import (
	"errors"
	"fmt"
	"unsafe"
)

// DB is a minimal SQLite connection wrapper.
type DB struct {
	db *C.sqlite3
}

// Stmt is a prepared statement.
type Stmt struct {
	db *DB
	s  *C.sqlite3_stmt
}

func OpenDB(path string) (*DB, error) {
	cpath := C.CString(path)
	defer C.free(unsafe.Pointer(cpath))
	var db *C.sqlite3
	rc := C.sqlite3_open_v2(cpath, &db, C.SQLITE_OPEN_READWRITE|C.SQLITE_OPEN_CREATE|C.SQLITE_OPEN_FULLMUTEX, nil)
	if rc != C.SQLITE_OK {
		msg := "unable to open database"
		if db != nil {
			msg = C.GoString(C.sqlite3_errmsg(db))
			C.sqlite3_close(db)
		}
		return nil, errors.New(msg)
	}
	C.sqlite3_busy_timeout(db, 5000)
	return &DB{db: db}, nil
}

func (d *DB) Close() {
	if d.db != nil {
		C.sqlite3_close_v2(d.db)
		d.db = nil
	}
}

func (d *DB) errmsg() error {
	return errors.New(C.GoString(C.sqlite3_errmsg(d.db)))
}

func (d *DB) Exec(sql string, args ...interface{}) error {
	st, err := d.Prepare(sql)
	if err != nil {
		return err
	}
	defer st.Close()
	if err := st.Bind(args...); err != nil {
		return err
	}
	for {
		more, err := st.Step()
		if err != nil {
			return err
		}
		if !more {
			return nil
		}
	}
}

func (d *DB) ExecScript(sql string) error {
	csql := C.CString(sql)
	defer C.free(unsafe.Pointer(csql))
	var errmsg *C.char
	rc := C.sqlite3_exec(d.db, csql, nil, nil, &errmsg)
	if rc != C.SQLITE_OK {
		msg := C.GoString(errmsg)
		C.sqlite3_free(unsafe.Pointer(errmsg))
		return errors.New(msg)
	}
	return nil
}

func (d *DB) LastInsertID() int64 {
	return int64(C.sqlite3_last_insert_rowid(d.db))
}

func (d *DB) Prepare(sql string) (*Stmt, error) {
	csql := C.CString(sql)
	defer C.free(unsafe.Pointer(csql))
	var s *C.sqlite3_stmt
	rc := C.sqlite3_prepare_v2(d.db, csql, -1, &s, nil)
	if rc != C.SQLITE_OK {
		return nil, d.errmsg()
	}
	return &Stmt{db: d, s: s}, nil
}

func (s *Stmt) Close() {
	if s.s != nil {
		C.sqlite3_finalize(s.s)
		s.s = nil
	}
}

func (s *Stmt) Bind(args ...interface{}) error {
	C.sqlite3_reset(s.s)
	C.sqlite3_clear_bindings(s.s)
	for i, a := range args {
		idx := C.int(i + 1)
		var rc C.int
		switch v := a.(type) {
		case nil:
			rc = C.sqlite3_bind_null(s.s, idx)
		case int:
			rc = C.sqlite3_bind_int64(s.s, idx, C.sqlite3_int64(v))
		case int64:
			rc = C.sqlite3_bind_int64(s.s, idx, C.sqlite3_int64(v))
		case bool:
			b := 0
			if v {
				b = 1
			}
			rc = C.sqlite3_bind_int64(s.s, idx, C.sqlite3_int64(b))
		case float64:
			rc = C.sqlite3_bind_double(s.s, idx, C.double(v))
		case string:
			cs := C.CString(v)
			rc = C.zk_bind_text(s.s, idx, cs, C.int(len(v)))
			C.free(unsafe.Pointer(cs))
		default:
			return fmt.Errorf("unsupported bind type %T", a)
		}
		if rc != C.SQLITE_OK {
			return s.db.errmsg()
		}
	}
	return nil
}

// Step returns true if a row is available.
func (s *Stmt) Step() (bool, error) {
	rc := C.sqlite3_step(s.s)
	switch rc {
	case C.SQLITE_ROW:
		return true, nil
	case C.SQLITE_DONE:
		return false, nil
	default:
		return false, s.db.errmsg()
	}
}

func (s *Stmt) Int(i int) int64 {
	return int64(C.sqlite3_column_int64(s.s, C.int(i)))
}

func (s *Stmt) Float(i int) float64 {
	return float64(C.sqlite3_column_double(s.s, C.int(i)))
}

func (s *Stmt) IsNull(i int) bool {
	return C.sqlite3_column_type(s.s, C.int(i)) == C.SQLITE_NULL
}

func (s *Stmt) Text(i int) string {
	p := C.sqlite3_column_text(s.s, C.int(i))
	if p == nil {
		return ""
	}
	n := C.sqlite3_column_bytes(s.s, C.int(i))
	return C.GoStringN((*C.char)(unsafe.Pointer(p)), n)
}

// Query runs a query and calls fn for each row.
func (d *DB) Query(sql string, args []interface{}, fn func(s *Stmt) error) error {
	st, err := d.Prepare(sql)
	if err != nil {
		return err
	}
	defer st.Close()
	if err := st.Bind(args...); err != nil {
		return err
	}
	for {
		more, err := st.Step()
		if err != nil {
			return err
		}
		if !more {
			return nil
		}
		if err := fn(st); err != nil {
			return err
		}
	}
}
EOF
