package main

import (
	"fmt"
	"strconv"
	"strings"
	"unicode/utf8"
)

type flagKind int

const (
	kBool flagKind = iota
	kString
	kInt
	kSlice
	kMap
)

type FlagDef struct {
	Name     string
	Short    rune
	Kind     flagKind
	Hidden   bool
	Default  string
	Enum     []string
	Required bool
	Sep      bool // split on ','
}

type CmdDef struct {
	Name       string
	Flags      []*FlagDef
	Subs       []*CmdDef
	Hidden     bool
	ArgName    string // positional argument name
	ArgSlice   bool
	DefaultSub string
	HelpFile   string
}

type Parsed struct {
	Path    []string
	Flags   map[string]interface{}
	Set     map[string]bool
	Args    []string
	Help    bool
	Version bool
	node    *CmdDef
	chain   []*CmdDef
}

func (p *Parsed) Bool(name string) bool {
	v, ok := p.Flags[name]
	if !ok {
		return false
	}
	b, _ := v.(bool)
	return b
}

func (p *Parsed) Str(name string) string {
	v, ok := p.Flags[name]
	if !ok {
		return ""
	}
	s, _ := v.(string)
	return s
}

func (p *Parsed) Int(name string) int64 {
	v, ok := p.Flags[name]
	if !ok {
		return 0
	}
	i, _ := v.(int64)
	return i
}

func (p *Parsed) Slice(name string) []string {
	v, ok := p.Flags[name]
	if !ok {
		return nil
	}
	s, _ := v.([]string)
	return s
}

func (p *Parsed) Map(name string) [][2]string {
	v, ok := p.Flags[name]
	if !ok {
		return nil
	}
	s, _ := v.([][2]string)
	return s
}

func globalFlags() []*FlagDef {
	return []*FlagDef{
		{Name: "help", Short: 'h', Kind: kBool},
		{Name: "notebook-dir", Kind: kString},
		{Name: "working-dir", Short: 'W', Kind: kString},
		{Name: "no-input", Kind: kBool},
		{Name: "debug", Kind: kBool, Hidden: true},
		{Name: "debug-style", Kind: kBool, Hidden: true},
		{Name: "force-input", Kind: kString, Hidden: true},
		{Name: "version", Kind: kBool, Hidden: true},
	}
}

func filteringFlags() []*FlagDef {
	return []*FlagDef{
		{Name: "interactive", Short: 'i', Kind: kBool},
		{Name: "limit", Short: 'n', Kind: kInt},
		{Name: "match", Short: 'm', Kind: kSlice, Sep: true},
		{Name: "match-strategy", Short: 'M', Kind: kString, Default: "fts"},
		{Name: "exclude", Short: 'x', Kind: kSlice, Sep: true},
		{Name: "tag", Short: 't', Kind: kSlice, Sep: true},
		{Name: "mention", Kind: kSlice, Sep: true},
		{Name: "mentioned-by", Kind: kSlice, Sep: true},
		{Name: "link-to", Short: 'l', Kind: kSlice, Sep: true},
		{Name: "no-link-to", Kind: kSlice, Sep: true},
		{Name: "linked-by", Short: 'L', Kind: kSlice, Sep: true},
		{Name: "no-linked-by", Kind: kSlice, Sep: true},
		{Name: "orphan", Kind: kBool},
		{Name: "tagless", Kind: kBool},
		{Name: "missing-backlink", Kind: kBool},
		{Name: "related", Kind: kSlice, Sep: true},
		{Name: "max-distance", Kind: kInt},
		{Name: "recursive", Short: 'r', Kind: kBool},
		{Name: "created", Kind: kString},
