	}
}

func buildApp() *CmdDef {
	listFlags := []*FlagDef{
		{Name: "format", Short: 'f', Kind: kString},
		{Name: "header", Kind: kString},
		{Name: "footer", Kind: kString, Default: "\\n"},
		{Name: "delimiter", Short: 'd', Kind: kString, Default: "\n"},
		{Name: "delimiter0", Short: '0', Kind: kBool},
		{Name: "no-pager", Short: 'P', Kind: kBool},
