		return "long flag"
	}
	if strings.HasPrefix(tok, "-") && len(tok) > 1 {
		return "short flag"
	}
	return ""
}

// nextValue fetches the next token as a value for flag f.
func (p *cliParser) nextValue(f *FlagDef, typ string) (string, error) {
	if p.pos >= len(p.tokens) {
		if f.Kind == kSlice || f.Kind == kMap {
			return "", fmt.Errorf("--%s: unexpected EOL", f.Name)
		}
		return "", fmt.Errorf("--%s: expected %s value but got \"EOL\" (<EOL>)", f.Name, typ)
	}
	tok := p.tokens[p.pos]
	if tok == "--" {
		if f.Kind == kSlice || f.Kind == kMap {
			return "", fmt.Errorf("--%s: unexpected EOL", f.Name)
		}
		return "", fmt.Errorf("--%s: expected %s value but got \"EOL\" (<EOL>)", f.Name, typ)
	}
	if c := classifyToken(tok); c != "" {
		return "", fmt.Errorf("--%s: expected %s value but got %q (%s); perhaps try --%s=%q?", f.Name, typ, tok, c, f.Name, tok)
	}
	p.pos++
	return tok, nil
}

func typeName(k flagKind) string {
	switch k {
	case kInt:
		return "int"
	default:
		return "string"
	}
}

func (p *cliParser) applyValue(f *FlagDef, val string, hasVal bool) error {
	switch f.Kind {
	case kBool:
		if hasVal {
			b, err := strconv.ParseBool(val)
			if err != nil {
				return fmt.Errorf("--%s: expected bool value but got %q", f.Name, val)
			}
			p.res.Flags[f.Name] = b
		} else {
			p.res.Flags[f.Name] = true
		}
	case kString:
		if !hasVal {
			v, err := p.nextValue(f, "string")
			if err != nil {
				return err
			}
			val = v
		}
		p.res.Flags[f.Name] = val
	case kInt:
		if !hasVal {
			v, err := p.nextValue(f, "int")
			if err != nil {
				return err
			}
			val = v
		}
		i, err := strconv.ParseInt(val, 10, 64)
		if err != nil {
			return fmt.Errorf("--%s: expected a valid 64 bit int but got %q", f.Name, val)
		}
		p.res.Flags[f.Name] = i
	case kSlice, kMap:
		if !hasVal {
			v, err := p.nextValue(f, "string")
			if err != nil {
				return err
			}
			val = v
		}
		parts := []string{val}
		if f.Sep || f.Kind == kMap {
			parts = strings.Split(val, ",")
		}
		for idx, part := range parts {
			if idx > 0 || hasVal {
				if c := classifyToken(part); c != "" {
					return fmt.Errorf("--%s: expected string value but got %q (%s); perhaps try --%s=%q?", f.Name, part, c, f.Name, part)
				}
			}
		}
		if f.Kind == kMap {
			cur, _ := p.res.Flags[f.Name].([][2]string)
			for _, part := range parts {
				kv := strings.SplitN(part, "=", 2)
				if len(kv) != 2 {
					return fmt.Errorf("--%s: expected \"<key>=<value>\" but got %q", f.Name, part)
				}
				cur = append(cur, [2]string{kv[0], kv[1]})
			}
			p.res.Flags[f.Name] = cur
		} else {
			cur, _ := p.res.Flags[f.Name].([]string)
			for _, part := range parts {
				if part == "" {
					continue
				}
				cur = append(cur, part)
			}
			p.res.Flags[f.Name] = cur
		}
	}
	p.res.Set[f.Name] = true
	return nil
}

func (p *cliParser) findLong(name string) *FlagDef {
	chain := p.res.chain
	for i := len(chain) - 1; i >= 0; i-- {
		for _, f := range chain[i].Flags {
			if f.Name == name {
				return f
			}
		}
	}
	return nil
}

func (p *cliParser) findShort(r rune) *FlagDef {
	chain := p.res.chain
	for i := len(chain) - 1; i >= 0; i-- {
		for _, f := range chain[i].Flags {
			if f.Short == r {
				return f
			}
		}
	}
	return nil
}

func applyDefaults(res *Parsed, node *CmdDef) {
	for _, f := range node.Flags {
		if _, ok := res.Flags[f.Name]; ok {
			continue
		}
		switch f.Kind {
		case kString:
			res.Flags[f.Name] = f.Default
		case kBool:
			res.Flags[f.Name] = false
		case kInt:
			res.Flags[f.Name] = int64(0)
		}
	}
}

func parseArgs(app *CmdDef, args []string) (*Parsed, error) {
	res := &Parsed{Flags: map[string]interface{}{}, Set: map[string]bool{}, node: app, chain: []*CmdDef{app}}
	p := &cliParser{tokens: args, res: res}
	afterDash := false
	for p.pos < len(p.tokens) {
		tok := p.tokens[p.pos]
		p.pos++
		if !afterDash && tok == "--" {
			afterDash = true
			continue
		}
		if !afterDash && strings.HasPrefix(tok, "--") {
			body := tok[2:]
			name, val, hasVal := body, "", false
			if i := strings.Index(body, "="); i >= 0 {
				name, val, hasVal = body[:i], body[i+1:], true
			}
			f := p.findLong(name)
			if f == nil {
				return nil, p.unknownFlag("--" + name)
			}
			if err := p.applyValue(f, val, hasVal); err != nil {
				return nil, err
			}
			continue
		}
		if !afterDash && strings.HasPrefix(tok, "-") && len(tok) > 1 {
			rest := tok[1:]
			for len(rest) > 0 {
				r, sz := utf8.DecodeRuneInString(rest)
				rest = rest[sz:]
				f := p.findShort(r)
				if f == nil {
					return nil, p.unknownFlag("-" + string(r))
				}
				if f.Kind == kBool {
					if err := p.applyValue(f, "", false); err != nil {
						return nil, err
					}
					continue
				}
				if rest != "" {
					if err := p.applyValue(f, rest, true); err != nil {
						return nil, err
					}
					rest = ""
				} else {
					if err := p.applyValue(f, "", false); err != nil {
						return nil, err
					}
				}
			}
			continue
		}
		// positional
		node := res.node
		if len(node.Subs) > 0 && len(res.Args) == 0 {
			var found *CmdDef
			for _, s := range node.Subs {
				if s.Name == tok {
					found = s
					break
				}
			}
			if found != nil {
				res.node = found
				res.chain = append(res.chain, found)
				res.Path = append(res.Path, found.Name)
				continue
			}
			if node.DefaultSub != "" {
				return nil, fmt.Errorf("unexpected argument %s", tok)
			}
			var cands []string
			for _, s := range node.Subs {
				if !s.Hidden {
					cands = append(cands, s.Name)
				}
			}
			return nil, potentialCandidates(tok, cands, "unexpected argument "+tok)
		}
		if node.ArgName != "" && (node.ArgSlice || len(res.Args) == 0) {
			res.Args = append(res.Args, tok)
			continue
		}
		return nil, fmt.Errorf("unexpected argument %s", tok)
	}
	// default subcommand
	if res.node.DefaultSub != "" {
		for _, s := range res.node.Subs {
			if s.Name == res.node.DefaultSub {
				res.node = s
				res.chain = append(res.chain, s)
				res.Path = append(res.Path, s.Name)
				break
			}
		}
	}
	res.Help = res.Bool("help")
	res.Version = res.Bool("version")
	for _, n := range res.chain {
		applyDefaults(res, n)
	}
	return res, nil
}

// validate checks required flags and enums (after help handling).
func validateParsed(res *Parsed) error {
	var missing []string
	for _, n := range res.chain {
		for _, f := range n.Flags {
			if f.Required && !res.Set[f.Name] {
				missing = append(missing, "--"+f.Name+"=STRING")
			}
		}
	}
	if len(missing) > 0 {
		return fmt.Errorf("missing flags: %s", strings.Join(missing, ", "))
	}
	for _, n := range res.chain {
		for _, f := range n.Flags {
			if len(f.Enum) > 0 && res.Set[f.Name] {
				v := res.Str(f.Name)
				ok := false
				for _, e := range f.Enum {
					if e == v {
						ok = true
					}
				}
				if !ok {
					quoted := []string{}
					for _, e := range f.Enum {
						quoted = append(quoted, strconv.Quote(e))
					}
					return fmt.Errorf("--%s must be one of %s but got %q", f.Name, strings.Join(quoted, ","), v)
				}
			}
		}
	}
	return nil
}
EOF
