			LinkFormat:        "markdown",
			LinkDropExtension: true,
		},
		Filters: map[string]string{},
		Aliases: map[string]string{},
	}
}

func tomlStr(m map[string]interface{}, key string) (string, bool) {
	v, ok := m[key]
	if !ok {
		return "", false
	}
	switch s := v.(type) {
	case string:
		return s, true
	default:
		return fmt.Sprint(s), true
	}
}

func tomlBool(m map[string]interface{}, key string) (bool, bool) {
	v, ok := m[key]
	if !ok {
		return false, false
	}
	b, ok := v.(bool)
	return b, ok
}

func tomlInt(m map[string]interface{}, key string) (int, bool) {
	v, ok := m[key]
	if !ok {
		return 0, false
	}
	switch i := v.(type) {
	case int64:
		return int(i), true
	case int:
		return i, true
	case float64:
		return int(i), true
	}
	return 0, false
}

func tomlStrSlice(m map[string]interface{}, key string) ([]string, bool) {
	v, ok := m[key]
	if !ok {
		return nil, false
	}
	arr, ok := v.([]interface{})
	if !ok {
		if s, ok := v.(string); ok {
			return []string{s}, true
		}
		return nil, false
	}
	out := []string{}
	for _, a := range arr {
		out = append(out, fmt.Sprint(a))
	}
	return out, true
}

func tomlTable(m map[string]interface{}, key string) map[string]interface{} {
	v, ok := m[key]
	if !ok {
		return nil
	}
	t, _ := v.(map[string]interface{})
	return t
}

func applyNoteConfig(dst *NoteConfig, t map[string]interface{}) {
	if t == nil {
		return
	}
	if s, ok := tomlStr(t, "language"); ok {
		dst.Lang = s
	}
	if s, ok := tomlStr(t, "default-title"); ok {
		dst.DefaultTitle = s
	}
	if s, ok := tomlStr(t, "filename"); ok {
		dst.FilenameTpl = s
	}
