		dst.BodyTemplate = s
	}
	if s, ok := tomlStrSlice(t, "ignore"); ok {
		dst.Exclude = append(append([]string{}, dst.Exclude...), s...)
	}
	if s, ok := tomlStrSlice(t, "exclude"); ok {
		dst.Exclude = append(append([]string{}, dst.Exclude...), s...)
	}
	if s, ok := tomlStr(t, "id-charset"); ok {
		dst.IDCharset = s
	}
	if i, ok := tomlInt(t, "id-length"); ok {
		dst.IDLength = i
	}
	if s, ok := tomlStr(t, "id-case"); ok {
		dst.IDCase = s
	}
}

func readExtra(t map[string]interface{}) map[string]string {
	out := map[string]string{}
	for k, v := range t {
		out[k] = fmt.Sprint(v)
	}
	return out
}

func loadConfig(path string) (*Config, error) {
	cfg := defaultConfig()
	data, err := os.ReadFile(path)
	if err != nil {
		if os.IsNotExist(err) {
			return cfg, nil
		}
		return nil, err
	}
	var raw map[string]interface{}
	if _, err := toml.Decode(string(data), &raw); err != nil {
		return nil, fmt.Errorf("failed to read config: %v", err)
	}
	applyNoteConfig(&cfg.Note, tomlTable(raw, "note"))
	if t := tomlTable(raw, "extra"); t != nil {
		cfg.Extra = readExtra(t)
	}
	if f := tomlTable(raw, "format"); f != nil {
		if md := tomlTable(f, "markdown"); md != nil {
			if b, ok := tomlBool(md, "hashtags"); ok {
				cfg.Markdown.Hashtags = b
			}
			if b, ok := tomlBool(md, "colon-tags"); ok {
				cfg.Markdown.ColonTags = b
			}
			if b, ok := tomlBool(md, "multiword-tags"); ok {
				cfg.Markdown.MultiwordTags = b
			}
			if s, ok := tomlStr(md, "link-format"); ok {
				cfg.Markdown.LinkFormat = s
			}
			if b, ok := tomlBool(md, "link-encode-path"); ok {
				bb := b
				cfg.Markdown.LinkEncodePath = &bb
			}
			if b, ok := tomlBool(md, "link-drop-extension"); ok {
				cfg.Markdown.LinkDropExtension = b
			}
		}
	}
	if t := tomlTable(raw, "tool"); t != nil {
		if s, ok := tomlStr(t, "editor"); ok {
			cfg.Tool.Editor = &s
		}
		if s, ok := tomlStr(t, "pager"); ok {
			cfg.Tool.Pager = &s
		}
		if s, ok := tomlStr(t, "fzf-preview"); ok {
			cfg.Tool.FzfPreview = &s
		}
		if s, ok := tomlStr(t, "fzf-options"); ok {
			cfg.Tool.FzfOptions = &s
		}
		if s, ok := tomlStr(t, "shell"); ok {
			cfg.Tool.Shell = &s
		}
	}
	if t := tomlTable(raw, "filter"); t != nil {
		for k, v := range t {
			cfg.Filters[k] = fmt.Sprint(v)
		}
	}
	if t := tomlTable(raw, "alias"); t != nil {
		for k, v := range t {
			cfg.Aliases[k] = fmt.Sprint(v)
		}
	}
	if g := tomlTable(raw, "group"); g != nil {
		for name, v := range g {
			gt, _ := v.(map[string]interface{})
			gc := GroupConfig{Name: name, Note: cfg.Note, Extra: map[string]string{}}
			gc.Note.Exclude = append([]string{}, cfg.Note.Exclude...)
			for k, v := range cfg.Extra {
				gc.Extra[k] = v
			}
			if gt != nil {
				if p, ok := tomlStrSlice(gt, "paths"); ok {
					gc.Paths = p
				} else {
					gc.Paths = []string{name}
				}
				applyNoteConfig(&gc.Note, tomlTable(gt, "note"))
				if e := tomlTable(gt, "extra"); e != nil {
					for k, v := range readExtra(e) {
						gc.Extra[k] = v
					}
				}
			} else {
				gc.Paths = []string{name}
			}
			cfg.Groups[name] = gc
		}
	}
	return cfg, nil
}

// groupNameForPath finds the group whose paths match the given relative dir.
func (c *Config) groupNameForPath(relPath string) (string, bool) {
	names := make([]string, 0, len(c.Groups))
	for n := range c.Groups {
		names = append(names, n)
	}
	sort.Strings(names)
	for _, name := range names {
		g := c.Groups[name]
		for _, p := range g.Paths {
			matched, err := filepath.Match(p, relPath)
			if err == nil && matched {
				return name, true
			}
			if strings.HasPrefix(relPath, p+"/") {
				return name, true
			}
		}
	}
	return "", false
}

func (c *Config) rootGroup() GroupConfig {
	extra := map[string]string{}
	for k, v := range c.Extra {
		extra[k] = v
	}
	n := c.Note
	n.Exclude = append([]string{}, c.Note.Exclude...)
	return GroupConfig{Note: n, Extra: extra}
}
