func isSpaceOrTab(c byte) bool { return c == ' ' || c == '\t' }

func (p *blockParser) peek(i int) byte {
	if i < len(p.line) {
		return p.line[i]
	}
	return 0
}

func (p *blockParser) findNextNonspace() {
	i := p.offset
	cols := p.column
	for i < len(p.line) {
		c := p.line[i]
		if c == ' ' {
			i++
			cols++
		} else if c == '\t' {
			i++
			cols += 4 - (cols % 4)
		} else {
			break
		}
	}
	p.blank = i >= len(p.line) || p.line[i] == '\n' || p.line[i] == '\r'
	p.nextNonspace = i
	p.nextNonspaceColumn = cols
	p.indent = p.nextNonspaceColumn - p.column
	p.indented = p.indent >= 4
}

func (p *blockParser) advanceNextNonspace() {
	p.offset = p.nextNonspace
	p.column = p.nextNonspaceColumn
	p.partiallyConsumedTab = false
}

func (p *blockParser) advanceOffset(count int, columns bool) {
	for count > 0 && p.offset < len(p.line) {
		c := p.line[p.offset]
		if c == '\t' {
			charsToTab := 4 - (p.column % 4)
			if columns {
				p.partiallyConsumedTab = charsToTab > count
				charsToAdvance := charsToTab
				if charsToTab > count {
					charsToAdvance = count
				}
				p.column += charsToAdvance
				if !p.partiallyConsumedTab {
					p.offset++
				}
				count -= charsToAdvance
			} else {
				p.partiallyConsumedTab = false
				p.column += charsToTab
				p.offset++
				count--
			}
		} else {
			p.partiallyConsumedTab = false
			p.offset++
			p.column++
			count--
		}
	}
}

func canContain(parent, child int) bool {
	switch parent {
	case bDocument, bBlockQuote, bItem:
		return child != bItem
	case bList:
		return child == bItem
	}
	return false
}

func acceptsLines(k int) bool {
	return k == bParagraph || k == bCode || k == bHTML || k == bMeta
}

func (p *blockParser) addChild(kind int) *mdNode {
	for !canContain(p.tip.kind, kind) {
		p.finalize(p.tip)
	}
	n := &mdNode{kind: kind, parent: p.tip, open: true}
	p.tip.children = append(p.tip.children, n)
	p.tip = n
	return n
}

func (p *blockParser) addLine() {
	start := p.lineStart + p.offset
	if p.partiallyConsumedTab {
		// approximate: skip the tab
		p.offset++
		start = p.lineStart + p.offset
	}
	stop := p.lineStart + len(p.line)
	p.tip.lines = append(p.tip.lines, seg{start, stop})
}

var reThematic = regexp.MustCompile(`^(?:(?:\*[ \t]*){3,}|(?:_[ \t]*){3,}|(?:-[ \t]*){3,})[ \t]*$`)
var reATX = regexp.MustCompile(`^#{1,6}(?:[ \t]+|$)`)
var reFence = regexp.MustCompile("^`{3,}|^~{3,}")
var reClosingFence = regexp.MustCompile("^(?:`{3,}|~{3,})[ \t]*$")
var reSetext = regexp.MustCompile(`^(?:=+|-+)[ \t]*$`)
