cd /workspace && cat > mdinline.go <<'EOF'
package main

import (
	"regexp"
	"strings"
	"unicode"
	"unicode/utf8"
)

const (
	iText = iota
	iSoftBreak
	iCode
	iEmph
	iLink
	iImage
	iAutoLink
	iRawHTML
	iWiki
	iTag
)

type inl struct {
	kind      int
	text      string
	children  []*inl
	dest      string
	title     string
	rels      []string
	tags      []string
	autoEmail bool
	// delimiter info (for emphasis processing)
	delim     *delimiter
}

type delimiter struct {
	node     *inl
	char     byte
	count    int
	origCount int
	canOpen  bool
	canClose bool
	prev     *delimiter
	next     *delimiter
	active   bool
}

type bracket struct {
	nodeIdx   int // index in nodes of the '[' text node
	image     bool
	active    bool
	pos       int // position in s after '['
	prevDelim *delimiter
	bracketAfter bool
}

type inlineParser struct {
	s        string
	pos      int
	nodes    []*inl
	delims   *delimiter // top of stack
	brackets []*bracket
	refs     map[string]linkRef
	opts     *mdOptions
}

type mdOptions struct {
	hashtags  bool
	colonTags bool
	multiword bool
}

func (p *inlineParser) addText(t string) {
	if t == "" {
		return
	}
	p.nodes = append(p.nodes, &inl{kind: iText, text: t})
}

func (p *inlineParser) precedingRune() rune {
	if p.pos == 0 {
		return '\n'
	}
	r, _ := utf8.DecodeLastRuneInString(p.s[:p.pos])
	return r
}

// peekLine returns the remainder of the current line including '\n'.
func (p *inlineParser) peekLine() string {
	rest := p.s[p.pos:]
	if i := strings.IndexByte(rest, '\n'); i >= 0 {
		return rest[:i+1]
	}
	return rest
}

func parseInlines(s string, refs map[string]linkRef, opts *mdOptions) []*inl {
	p := &inlineParser{s: s, refs: refs, opts: opts}
	lineHead := true
	for p.pos < len(p.s) {
		c := p.s[p.pos]
		if lineHead {
			lineHead = false
			if p.tryLinkify(false) {
				continue
			}
		}
		switch c {
		case '\n':
			// soft break; strip trailing spaces of previous text
			p.nodes = append(p.nodes, &inl{kind: iSoftBreak})
			p.pos++
			lineHead = true
			// skip leading spaces on next line
			for p.pos < len(p.s) && (p.s[p.pos] == ' ' || p.s[p.pos] == '\t') {
				p.pos++
			}
			continue
		case ' ', '\t', '(', '~':
			if p.tryLinkify(true) {
				continue
			}
			p.addText(string(c))
			p.pos++
			continue
		case '\\':
			if p.pos+1 < len(p.s) && isASCIIPunct(p.s[p.pos+1]) {
				p.addText(p.s[p.pos : p.pos+2])
				p.pos += 2
				continue
			}
			p.addText("\\")
			p.pos++
			continue
		case '`':
			if p.parseCodeSpan() {
				continue
			}
		case '<':
			if p.parseAutolink() || p.parseRawHTML() {
				continue
			}
			p.addText("<")
			p.pos++
			continue
		case '[':
			if p.parseWikiLink(false) {
				continue
			}
			p.addText("[")
			p.brackets = append(p.brackets, &bracket{nodeIdx: len(p.nodes) - 1, active: true, pos: p.pos + 1, prevDelim: p.delims})
			p.pos++
			continue
		case '!':
			if p.pos+1 < len(p.s) && p.s[p.pos+1] == '[' {
				p.addText("![")
				p.brackets = append(p.brackets, &bracket{nodeIdx: len(p.nodes) - 1, image: true, active: true, pos: p.pos + 2, prevDelim: p.delims})
				p.pos += 2
				continue
			}
		case ']':
			p.parseCloseBracket()
			continue
		case '*', '_':
			p.parseDelimRun(c)
			continue
		case '#':
			if p.parseWikiLink(true) {
				continue
			}
			if p.opts.hashtags && p.parseHashtag() {
				continue
			}
		case ':':
			if p.opts.colonTags && p.parseColonTag() {
				continue
			}
		}
		// plain text run
		start := p.pos
		p.pos++
		for p.pos < len(p.s) && !isInlineSpecial(p.s[p.pos]) {
			p.pos++
		}
		p.addText(p.s[start:p.pos])
	}
	p.processEmphasis(nil)
	return p.nodes
}

func isInlineSpecial(c byte) bool {
	switch c {
	case '\n', ' ', '\t', '(', '~', '\\', '`', '<', '[', '!', ']', '*', '_', '#', ':':
		return true
	}
	return false
}

// ---- code spans

func (p *inlineParser) parseCodeSpan() bool {
	start := p.pos
	n := 0
	for p.pos+n < len(p.s) && p.s[p.pos+n] == '`' {
		n++
	}
	i := p.pos + n
	for i < len(p.s) {
		if p.s[i] == '`' {
			m := 0
			for i+m < len(p.s) && p.s[i+m] == '`' {
				m++
			}
			if m == n {
				content := p.s[start+n : i]
				content = strings.ReplaceAll(content, "\n", " ")
				if len(content) >= 2 && content[0] == ' ' && content[len(content)-1] == ' ' && strings.Trim(content, " ") != "" {
					content = content[1 : len(content)-1]
				}
				p.nodes = append(p.nodes, &inl{kind: iCode, text: content})
				p.pos = i + m
				return true
			}
			i += m
			continue
		}
		i++
	}
	// no match: literal backticks
	p.addText(p.s[start : start+n])
	p.pos = start + n
	return true
}

// ---- autolinks & raw html

var reAutolinkURI = regexp.MustCompile(`^<[A-Za-z][A-Za-z0-9.+-]{1,31}:[^<>\x00-\x20]*>`)
var reAutolinkEmail = regexp.MustCompile("^<([a-zA-Z0-9.!#$%&'*+/=?^_`{|}~-]+@[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?(?:\\.[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)*)>")

func (p *inlineParser) parseAutolink() bool {
	rest := p.s[p.pos:]
	if m := reAutolinkEmail.FindString(rest); m != "" {
		p.nodes = append(p.nodes, &inl{kind: iAutoLink, dest: m[1 : len(m)-1], autoEmail: true})
		p.pos += len(m)
		return true
	}
	if m := reAutolinkURI.FindString(rest); m != "" {
		p.nodes = append(p.nodes, &inl{kind: iAutoLink, dest: m[1 : len(m)-1], title: m[1 : len(m)-1]})
		p.pos += len(m)
		return true
	}
	return false
}

const htmlAttrName = `[a-zA-Z_:][a-zA-Z0-9:._-]*`
const htmlAttrValue = `(?:[^"'=<>` + "`" + `\x00-\x20]+|'[^']*'|"[^"]*")`
const htmlAttr = `(?:\s+` + htmlAttrName + `(?:\s*=\s*` + htmlAttrValue + `)?)`
const htmlOpenTag = `<[A-Za-z][A-Za-z0-9-]*` + htmlAttr + `*\s*/?>`
const htmlCloseTag = `</[A-Za-z][A-Za-z0-9-]*\s*>`

var reRawHTML = regexp.MustCompile(`^(?:` + htmlOpenTag + `|` + htmlCloseTag + `|<!-->|<!--->|<!--[\s\S]*?-->|<[?][\s\S]*?[?]>|<![A-Za-z][^>]*>|<!\[CDATA\[[\s\S]*?\]\]>)`)

func (p *inlineParser) parseRawHTML() bool {
	m := reRawHTML.FindString(p.s[p.pos:])
	if m == "" {
		return false
	}
	p.nodes = append(p.nodes, &inl{kind: iRawHTML, text: m})
	p.pos += len(m)
	return true
}

// ---- linkify (GFM autolink extension, goldmark flavour)

var reLinkifyURL = regexp.MustCompile(`^(?:http|https|ftp)://[-a-zA-Z0-9@:%._\+~#=]{1,256}\.[a-zA-Z0-9]+(?::\d+)?(?:(?:/|[#?])[-a-zA-Z0-9@:%_\+.~#$!?&/=\(\);,'">\^{}\[\]` + "`" + `]*)?`)
var reLinkifyWWW = regexp.MustCompile(`^www\.[-a-zA-Z0-9@:%._\+~#=]{1,256}\.[a-zA-Z0-9]+(?::\d+)?(?:(?:/|[#?])[-a-zA-Z0-9@:%_\+.~#$!?&/=\(\);,'">\^{}\[\]` + "`" + `]*)?`)
var reEmailDomain = regexp.MustCompile(`^[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?(?:\.[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)*`)

func isEmailLocalChar(c byte) bool {
	if (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') {
		return true
	}
	return strings.IndexByte(".!#$%&'*+/=?^_`{|}~-", c) >= 0
}

func findEmailIndex(b string) int {
	i := 0
	for ; i < len(b); i++ {
		if !isEmailLocalChar(b[i]) {
			break
		}
	}
	if i == 0 || i >= len(b) || b[i] != '@' {
		return -1
	}
	i++
	if i >= len(b) {
		return -1
	}
	m := reEmailDomain.FindStringIndex(b[i:])
	if m == nil {
		return -1
	}
	return i + m[1]
}

func (p *inlineParser) inLinkLabel() bool {
	for _, b := range p.brackets {
		if b.active && !b.image {
			return true
		}
	}
	return false
}

func (p *inlineParser) tryLinkify(consumeFirst bool) bool {
	if p.inLinkLabel() {
		return false
	}
	line := p.peekLine()
	consumes := 0
	if consumeFirst {
		if len(line) == 0 {
			return false
		}
		line = line[1:]
		consumes = 1
	}
	var m []int
	protocol := ""
	email := false
	if strings.HasPrefix(line, "http://") || strings.HasPrefix(line, "https://") || strings.HasPrefix(line, "ftp://") {
		m = reLinkifyURL.FindStringIndex(line)
	}
	if m == nil && strings.HasPrefix(line, "www.") {
		m = reLinkifyWWW.FindStringIndex(line)
		protocol = "http"
	}
	if m != nil {
		lastChar := line[m[1]-1]
		if lastChar == '.' {
			m[1]--
		} else if lastChar == ')' {
			closing := 0
			for i := m[1] - 1; i >= m[0]; i-- {
				if line[i] == ')' {
					closing++
				} else if line[i] == '(' {
					closing--
				}
			}
			if closing > 0 {
				m[1] -= closing
			}
		} else if lastChar == ';' {
			i := m[1] - 2
			for ; i >= m[0]; i-- {
				if isAlnumByte(line[i]) {
					continue
				}
				break
			}
			if i != m[1]-2 && i >= 0 {
				if line[i] == '&' {
					m[1] -= m[1] - i
				}
			}
		}
	}
	if m == nil {
		if len(line) > 0 && isASCIIPunct(line[0]) {
			return false
		}
		stop := findEmailIndex(line)
		if stop < 0 {
			return false
		}
		at := strings.IndexByte(line, '@')
		if at < 0 || !strings.Contains(line[at:stop-1], ".") {
			// goldmark checks the '.' between @ and stop-1
			if !strings.Contains(line[at:stop], ".") {
				return false
			}
		}
		m = []int{0, stop}
		if line[m[1]-1] == '.' {
			m[1]--
		}
		if m[1] < len(line) {
			nc := line[m[1]]
			if nc == '-' || nc == '_' {
				return false
			}
		}
		email = true
	}
	// trim trailing punctuation
	i := m[1] - 1
	for ; i > 0; i-- {
		switch line[i] {
		case '?', '!', '.', ',', ':', '*', '_', '~':
			continue
		}
		break
	}
	m[1] = i + 1
	if consumes != 0 {
		p.addText(p.s[p.pos : p.pos+1])
	}
	url := line[:m[1]]
	n := &inl{kind: iAutoLink, autoEmail: email, title: url}
	if protocol != "" {
		n.dest = protocol + "://" + url
	} else {
		n.dest = url
	}
	p.nodes = append(p.nodes, n)
	p.pos += consumes + m[1]
	return true
}

func isAlnumByte(c byte) bool {
	return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9')
}

// ---- wiki links

func (p *inlineParser) parseWikiLink(hash bool) bool {
	rest := p.s[p.pos:]
	opener := 0
	closer := ""
	rel := ""
	if hash {
		if !strings.HasPrefix(rest, "#[[") {
			return false
		}
		opener = 3
		closer = "]]"
		rel = "up"
	} else if strings.HasPrefix(rest, "[[[") {
		opener = 3
		closer = "]]]"
		rel = "down"
	} else if strings.HasPrefix(rest, "[[") {
		opener = 2
		closer = "]]"
	} else {
		return false
	}
	var href, label strings.Builder
	parsingLabel := false
	escaping := false
	end := -1
	i := opener
	for i < len(rest) {
		c := rest[i]
		if escaping {
			escaping = false
			r, sz := utf8.DecodeRuneInString(rest[i:])
			if parsingLabel {
				label.WriteRune(r)
			} else {
				href.WriteRune(r)
			}
			i += sz
			continue
		}
		if c == '\\' {
			escaping = true
			i++
			continue
		}
		if c == '\n' {
			break
		}
		if strings.HasPrefix(rest[i:], closer) {
			end = i + len(closer)
			break
		}
		if c == '|' {
			parsingLabel = true
			i++
			continue
		}
		r, sz := utf8.DecodeRuneInString(rest[i:])
		if parsingLabel {
			label.WriteRune(r)
		} else {
			href.WriteRune(r)
		}
		i += sz
	}
	if end < 0 {
		if rel == "down" {
			return false
		}
		return false
	}
	h := strings.TrimSpace(href.String())
	if h == "" {
		return false
	}
	l := strings.TrimSpace(label.String())
	title := l
	if title == "" {
		title = h
	}
	n := &inl{kind: iWiki, dest: h, title: title}
	if rel != "" {
		n.rels = []string{rel}
	}
	p.nodes = append(p.nodes, n)
	p.pos += end
	return true
}

// ---- tags

func isTagChar(r rune) bool {
	if unicode.IsLetter(r) || unicode.IsNumber(r) {
		return true
	}
	switch r {
	case '_', '-', '/', ':', '\'', '@', '$', '%', '&', '+', '=', '~':
		return true
	}
	return false
}

func allDigits(s string) bool {
	if s == "" {
		return false
	}
	for _, r := range s {
		if !unicode.IsDigit(r) && !unicode.IsNumber(r) {
			return false
		}
	}
	return true
}

func (p *inlineParser) parseHashtag() bool {
	prev := p.precedingRune()
	if isTagChar(prev) || prev == '#' {
		return false
	}
	line := p.peekLine()
	if len(line) < 2 {
		return false
	}
	body := line[1:]
	var tag strings.Builder
	var mw strings.Builder
	regularActive := true
	multiActive := false
	escaping := false
	endIndex := -1
	mwEnd := -1
	mwFound := false
	prevRune := '#'
	lastI := -1
	regularDone := false
	regularEnd := -1
	for i, r := range body {
		lastI = i
		if p.opts.multiword {
			if escaping {
				escaping = false
				if regularActive {
					tag.WriteRune(r)
				}
				mw.WriteRune(r)
				prevRune = r
				continue
			}
			if r == '\\' {
				escaping = true
				prevRune = r
				continue
			}
			if r == '#' {
				if unicode.IsSpace(prevRune) || prevRune == '#' && i == 0 {
					break
				}
				if multiActive {
					mwFound = true
					mwEnd = i
				}
				break
			}
			if r == ' ' || r == '\t' {
				if regularActive {
					regularActive = false
					regularEnd = i
				}
				multiActive = true
				mw.WriteRune(r)
				prevRune = r
				continue
			}
			if r == '\n' || r == '\r' {
				break
			}
			if !isTagChar(r) {
				if !multiActive {
					if regularActive {
						regularActive = false
						regularEnd = i
					}
					break
				}
				prevRune = r
				continue
			}
			if regularActive {
				tag.WriteRune(r)
			}
			mw.WriteRune(r)
			prevRune = r
			continue
		}
		// regular hashtags only
		if escaping {
			escaping = false
			tag.WriteRune(r)
			continue
		}
		if r == '\\' {
			escaping = true
			continue
		}
		if !isTagChar(r) {
			endIndex = i
			regularDone = true
			break
		}
		tag.WriteRune(r)
	}
	_ = regularDone
	if p.opts.multiword && mwFound {
		name := strings.TrimSpace(mw.String())
		if name != "" {
			p.nodes = append(p.nodes, &inl{kind: iTag, tags: []string{name}})
			p.pos += 1 + mwEnd
			return true
		}
	}
	if p.opts.multiword {
		if regularEnd >= 0 {
			endIndex = regularEnd
		} else if regularActive {
			// regular tag extended up to where scanning stopped
			endIndex = -1
		}
	}
	name := strings.TrimSpace(tag.String())
	if name == "" || allDigits(name) {
		return false
	}
	var adv int
	if endIndex >= 0 {
		adv = endIndex + 1
	} else {
		adv = lastI + 1
	}
	p.nodes = append(p.nodes, &inl{kind: iTag, tags: []string{name}})
	p.pos += adv
	return true
}

func (p *inlineParser) parseColonTag() bool {
	prev := p.precedingRune()
	if isTagChar(prev) {
		return false
	}
	line := p.peekLine()
	if len(line) < 2 {
		return false
	}
	body := line[1:]
	var tags []string
	var cur strings.Builder
	escaping := false
	endIndex := 0
	for i, r := range body {
		endIndex = i
		if escaping {
			escaping = false
			cur.WriteRune(r)
			continue
		}
		if r == '\\' {
			escaping = true
			continue
		}
		if r == ':' {
			t := strings.TrimSpace(cur.String())
			if t == "" {
				break
			}
			tags = append(tags, t)
			cur.Reset()
			continue
		}
		if !isTagChar(r) || r == ':' {
			break
		}
		cur.WriteRune(r)
	}
	if len(tags) == 0 {
		return false
	}
	p.nodes = append(p.nodes, &inl{kind: iTag, tags: tags})
	if endIndex < 1 {
		endIndex = 1
	}
	p.pos += endIndex
	return true
}

// ---- emphasis

func isPunctRune(r rune) bool {
	if r < 128 {
		return isASCIIPunct(byte(r))
	}
	return unicode.IsPunct(r) || unicode.IsSymbol(r)
}

func (p *inlineParser) parseDelimRun(c byte) {
	start := p.pos
	n := 0
	for p.pos+n < len(p.s) && p.s[p.pos+n] == c {
		n++
	}
	before := p.precedingRune()
	after := '\n'
	if start+n < len(p.s) {
		after, _ = utf8.DecodeRuneInString(p.s[start+n:])
	}
	afterWS := unicode.IsSpace(after)
	afterPunct := isPunctRune(after)
	beforeWS := unicode.IsSpace(before)
	beforePunct := isPunctRune(before)
	leftFlanking := !afterWS && (!afterPunct || beforeWS || beforePunct)
	rightFlanking := !beforeWS && (!beforePunct || afterWS || afterPunct)
	var canOpen, canClose bool
	if c == '_' {
		canOpen = leftFlanking && (!rightFlanking || beforePunct)
		canClose = rightFlanking && (!leftFlanking || afterPunct)
	} else {
		canOpen = leftFlanking
		canClose = rightFlanking
	}
	node := &inl{kind: iText, text: p.s[start : start+n]}
	p.nodes = append(p.nodes, node)
	p.pos += n
	if canOpen || canClose {
		d := &delimiter{node: node, char: c, count: n, origCount: n, canOpen: canOpen, canClose: canClose, prev: p.delims, active: true}
		if p.delims != nil {
			p.delims.next = d
		}
		p.delims = d
		node.delim = d
	}
}

func (p *inlineParser) removeDelim(d *delimiter) {
	if d.prev != nil {
		d.prev.next = d.next
	}
	if d.next != nil {
		d.next.prev = d.prev
	} else {
		p.delims = d.prev
	}
}

func (p *inlineParser) indexOf(n *inl) int {
	for i, x := range p.nodes {
		if x == n {
			return i
		}
	}
	return -1
}

func (p *inlineParser) processEmphasis(stackBottom *delimiter) {
	openersBottom := map[[3]int]*delimiter{}
	closer := p.delims
	for closer != nil && closer.prev != stackBottom {
		closer = closer.prev
	}
	for closer != nil {
		if !closer.canClose {
			closer = closer.next
			continue
		}
		key := [3]int{int(closer.char), closer.origCount % 3, 0}
		if closer.canOpen {
			key[2] = 1
		}
		opener := closer.prev
		found := false
		for opener != nil && opener != stackBottom && opener != openersBottom[key] {
			oddMatch := (closer.canOpen || opener.canClose) && closer.origCount%3 != 0 && (opener.origCount+closer.origCount)%3 == 0
			if opener.char == closer.char && opener.canOpen && !oddMatch {
				found = true
				break
			}
			opener = opener.prev
		}
		oldCloser := closer
		if found {
			use := 1
			if closer.count >= 2 && opener.count >= 2 {
				use = 2
			}
			opener.count -= use
			closer.count -= use
			opener.node.text = opener.node.text[:len(opener.node.text)-use]
			closer.node.text = closer.node.text[:len(closer.node.text)-use]
			oi := p.indexOf(opener.node)
			ci := p.indexOf(closer.node)
			if oi >= 0 && ci >= 0 && oi < ci {
				emph := &inl{kind: iEmph, children: append([]*inl{}, p.nodes[oi+1:ci]...)}
				rest := append([]*inl{}, p.nodes[ci:]...)
				p.nodes = append(append(p.nodes[:oi+1], emph), rest...)
			}
			// remove delimiters between
			d := closer.prev
			for d != nil && d != opener {
				pd := d.prev
				p.removeDelim(d)
				d = pd
			}
			if opener.count == 0 {
				p.removeDelim(opener)
				p.removeNode(opener.node)
			}
			if closer.count == 0 {
				next := closer.next
				p.removeDelim(closer)
				p.removeNode(closer.node)
				closer = next
			}
		} else {
			openersBottom[key] = oldCloser.prev
			if !oldCloser.canOpen {
				p.removeDelim(oldCloser)
			}
			closer = oldCloser.next
		}
	}
	for p.delims != nil && p.delims != stackBottom {
		p.removeDelim(p.delims)
	}
}

func (p *inlineParser) removeNode(n *inl) {
	i := p.indexOf(n)
	if i >= 0 {
		p.nodes = append(p.nodes[:i], p.nodes[i+1:]...)
	}
}

// ---- links

func (p *inlineParser) parseCloseBracket() {
	p.pos++ // skip ']'
	if len(p.brackets) == 0 {
		p.addText("]")
		return
	}
	opener := p.brackets[len(p.brackets)-1]
	if !opener.active {
		p.brackets = p.brackets[:len(p.brackets)-1]
		p.addText("]")
		return
	}
	labelEnd := p.pos - 1
	matched := false
	var dest, title string
	save := p.pos
	// inline link
	if p.pos < len(p.s) && p.s[p.pos] == '(' {
		i := p.pos + 1
		i = skipSpacesNL(p.s, i)
		d, j, ok := parseLinkDest([]byte(p.s), i)
		if ok {
			dest = d
			k := j
			if k > i || true {
				k2 := skipSpacesNL(p.s, j)
				if k2 > j {
					t, k3, ok := parseLinkTitle([]byte(p.s), k2)
					if ok {
						title = t
						k2 = k3
					}
				}
				k2 = skipSpacesNL(p.s, k2)
				if k2 < len(p.s) && p.s[k2] == ')' {
					p.pos = k2 + 1
					matched = true
				}
			}
		}
		if !matched {
			p.pos = save
		}
	}
	if !matched {
		// reference link
		label := ""
		beforeLabel := p.pos
		n := p.parseLinkLabel()
		if n > 2 {
			label = p.s[beforeLabel+1 : beforeLabel+n-1]
		} else if !opener.bracketAfter {
			label = p.s[opener.pos:labelEnd]
		}
		if n == 0 {
			p.pos = save
		}
		if label != "" || n == 2 {
			if n == 2 {
				label = p.s[opener.pos:labelEnd]
			}
			if ref, ok := p.refs[normalizeLabel(label)]; ok && strings.TrimSpace(label) != "" {
				dest = ref.dest
				title = ref.title
				matched = true
			}
		}
		if !matched {
			p.pos = save
		}
	}
	if matched {
		kind := iLink
		if opener.image {
			kind = iImage
		}
		oi := opener.nodeIdx
		// process emphasis inside the link
		p.processEmphasis(opener.prevDelim)
		oi = p.indexOfBracketNode(opener)
		children := append([]*inl{}, p.nodes[oi+1:]...)
		link := &inl{kind: kind, children: children, dest: unescapeString(dest), title: unescapeString(title)}
		p.nodes = append(p.nodes[:oi], link)
		p.brackets = p.brackets[:len(p.brackets)-1]
		if !opener.image {
			for _, b := range p.brackets {
				if !b.image {
					b.active = false
				}
			}
		}
		return
	}
	p.brackets = p.brackets[:len(p.brackets)-1]
	p.addText("]")
}

func (p *inlineParser) indexOfBracketNode(b *bracket) int {
	// the bracket node is the text node "[" or "![" at nodeIdx; it may have shifted
	if b.nodeIdx < len(p.nodes) {
		n := p.nodes[b.nodeIdx]
		if n.kind == iText && (n.text == "[" || n.text == "![") {
			return b.nodeIdx
		}
	}
	for i := len(p.nodes) - 1; i >= 0; i-- {
		n := p.nodes[i]
		if n.kind == iText && (n.text == "[" || n.text == "![") {
			return i
		}
	}
	return b.nodeIdx
}

// parseLinkLabel parses [label] at p.pos; returns length consumed (0 if none)
func (p *inlineParser) parseLinkLabel() int {
	if p.pos >= len(p.s) || p.s[p.pos] != '[' {
		return 0
	}
	i := p.pos + 1
	for i < len(p.s) {
		c := p.s[i]
		if c == '\\' && i+1 < len(p.s) {
			i += 2
			continue
		}
		if c == '[' {
			return 0
		}
		if c == ']' {
			if i-p.pos > 1000 {
				return 0
			}
			n := i - p.pos + 1
			p.pos = i + 1
			return n
		}
		i++
	}
	return 0
}

func skipSpacesNL(s string, i int) int {
	for i < len(s) && (s[i] == ' ' || s[i] == '\t' || s[i] == '\n' || s[i] == '\r') {
		i++
	}
	return i
}

// inlineText returns goldmark-like Text() of nodes.
func inlineText(nodes []*inl) string {
	var b strings.Builder
	for _, n := range nodes {
		switch n.kind {
		case iText:
			b.WriteString(n.text)
		case iCode:
			b.WriteString(n.text)
		case iEmph, iLink, iImage:
			b.WriteString(inlineText(n.children))
		case iWiki:
			b.WriteString(n.title)
		}
	}
	return b.String()
}
