func decodeEntity(s string) (string, int) {
	end := strings.IndexByte(s, ';')
	if end < 2 || end > 32 {
		return "", 0
	}
	cand := s[:end+1]
	dec := html.UnescapeString(cand)
	if dec == cand {
		return "", 0
	}
	return dec, end + 1
