package main

import (
	"errors"
	"fmt"
	"math"
	"regexp"
	"strconv"
	"strings"

	"gopkg.in/yaml.v3"
)

// OrderedMap keeps key order.
type OrderedMap struct {
	Keys   []string
	Values map[string]interface{}
}

var yamlStyleFloat = regexp.MustCompile(`^[-+]?(\.[0-9]+|[0-9]+(\.[0-9]*)?)([eE][-+]?[0-9]+)?$`)

func resolveYAMLPlain(s string) interface{} {
	switch s {
	case "y", "Y", "yes", "Yes", "YES", "true", "True", "TRUE", "on", "On", "ON":
		return true
	case "n", "N", "no", "No", "NO", "false", "False", "FALSE", "off", "Off", "OFF":
		return false
	case "", "~", "null", "Null", "NULL":
		return nil
	case ".nan", ".NaN", ".NAN":
		return math.NaN()
	case ".inf", ".Inf", ".INF", "+.inf", "+.Inf", "+.INF":
		return math.Inf(1)
	case "-.inf", "-.Inf", "-.INF":
		return math.Inf(-1)
	}
	c := s[0]
	if c == '.' {
		if f, err := strconv.ParseFloat(s, 64); err == nil {
			return f
		}
		return s
	}
	if (c >= '0' && c <= '9') || c == '+' || c == '-' {
		if isYAMLTimestamp(s) {
			return s
		}
		plain := strings.ReplaceAll(s, "_", "")
		if i, err := strconv.ParseInt(plain, 0, 64); err == nil {
			return i
		}
		if u, err := strconv.ParseUint(plain, 0, 64); err == nil {
			return u
		}
		if yamlStyleFloat.MatchString(plain) {
			if f, err := strconv.ParseFloat(plain, 64); err == nil {
				return f
			}
		}
		if strings.HasPrefix(plain, "0b") {
			if i, err := strconv.ParseInt(plain[2:], 2, 64); err == nil {
				return i
			}
			if u, err := strconv.ParseUint(plain[2:], 2, 64); err == nil {
				return u
			}
		} else if strings.HasPrefix(plain, "-0b") {
			if i, err := strconv.ParseInt("-"+plain[3:], 2, 64); err == nil {
				return i
			}
		}
	}
	return s
}

func isYAMLTimestamp(s string) bool {
	i := 0
	for ; i < len(s); i++ {
		if c := s[i]; c < '0' || c > '9' {
			break
		}
	}
	return i == 4 && i < len(s) && s[i] == '-' && parseYAMLTimestampOK(s)
}

func parseYAMLTimestampOK(s string) bool {
	for _, f := range []string{"2006-1-2T15:4:5.999999999Z07:00", "2006-1-2t15:4:5.999999999Z07:00", "2006-1-2 15:4:5.999999999", "2006-1-2"} {
		if _, err := parseTimeLayout(f, s); err == nil {
			return true
		}
	}
	return false
}

func yamlNodeValue(n *yaml.Node) interface{} {
	switch n.Kind {
	case yaml.DocumentNode:
		if len(n.Content) == 0 {
			return nil
		}
		return yamlNodeValue(n.Content[0])
	case yaml.AliasNode:
		if n.Alias != nil {
			return yamlNodeValue(n.Alias)
		}
		return nil
	case yaml.ScalarNode:
		switch n.Tag {
		case "!!str", "!!binary":
			if n.Style == 0 {
				// explicit or resolved string
				if n.Tag == "!!str" && n.Style&(yaml.TaggedStyle) == 0 {
					return resolveYAMLPlain(n.Value)
				}
			}
			if n.Style&(yaml.DoubleQuotedStyle|yaml.SingleQuotedStyle|yaml.LiteralStyle|yaml.FoldedStyle) != 0 {
				return n.Value
			}
			if n.Style&yaml.TaggedStyle != 0 {
				return n.Value
			}
			return resolveYAMLPlain(n.Value)
		case "!!null":
			return nil
		case "!!bool", "!!int", "!!float", "!!timestamp":
			if n.Style&yaml.TaggedStyle != 0 {
				v := resolveYAMLPlain(n.Value)
				return v
			}
			return resolveYAMLPlain(n.Value)
		default:
			if n.Style&(yaml.DoubleQuotedStyle|yaml.SingleQuotedStyle|yaml.LiteralStyle|yaml.FoldedStyle) != 0 {
				return n.Value
			}
			return resolveYAMLPlain(n.Value)
		}
	case yaml.SequenceNode:
		out := make([]interface{}, 0, len(n.Content))
		for _, c := range n.Content {
			out = append(out, yamlNodeValue(c))
		}
		return out
	case yaml.MappingNode:
		m := &OrderedMap{Values: map[string]interface{}{}}
		yamlFillMap(m, n, false)
		return m
	}
	return nil
}

func yamlKeyString(k *yaml.Node) string {
	v := yamlNodeValue(k)
	switch t := v.(type) {
	case nil:
		return ""
	case string:
		return t
	case *OrderedMap:
		return fmt.Sprint(t.Values)
	default:
		return fmt.Sprint(t)
	}
}

func yamlFillMap(m *OrderedMap, n *yaml.Node, lower bool) {
	for i := 0; i+1 < len(n.Content); i += 2 {
		k := n.Content[i]
		v := n.Content[i+1]
		if k.Kind == yaml.ScalarNode && k.Value == "<<" && k.Style == 0 {
			// merge
			var merges []*yaml.Node
			src := v
			if src.Kind == yaml.AliasNode {
				src = src.Alias
			}
			if src != nil && src.Kind == yaml.SequenceNode {
				for _, c := range src.Content {
					if c.Kind == yaml.AliasNode {
						c = c.Alias
					}
					merges = append(merges, c)
				}
			} else if src != nil {
				merges = append(merges, src)
			}
			for _, mn := range merges {
				if mn != nil && mn.Kind == yaml.MappingNode {
					yamlFillMap(m, mn, lower)
				}
			}
			continue
		}
		key := yamlKeyString(k)
		if lower {
			key = strings.ToLower(key)
		}
		if _, exists := m.Values[key]; !exists {
			m.Keys = append(m.Keys, key)
		}
		m.Values[key] = yamlNodeValue(v)
	}
}

// parseFrontmatterYAML parses YAML with yaml.v2 MapSlice semantics.
func parseFrontmatterYAML(content []byte) (*OrderedMap, error) {
	var doc yaml.Node
	err := yaml.Unmarshal(content, &doc)
	if err != nil {
		msg := err.Error()
		return nil, errors.New(msg)
	}
	m := &OrderedMap{Values: map[string]interface{}{}}
	if doc.Kind == 0 || len(doc.Content) == 0 {
		return m, nil
	}
	root := doc.Content[0]
	if root.Kind == yaml.AliasNode && root.Alias != nil {
		root = root.Alias
	}
	switch root.Kind {
	case yaml.MappingNode:
		yamlFillMap(m, root, true)
		return m, nil
	case yaml.ScalarNode:
		v := yamlNodeValue(root)
		if v == nil {
			return m, nil
		}
		return nil, fmt.Errorf("yaml: unmarshal errors:\n  line %d: cannot unmarshal %s `%s` into yaml.MapSlice", root.Line, shortTag(root), root.Value)
	case yaml.SequenceNode:
		lines := []string{}
		for _, c := range root.Content {
			if c.Kind == yaml.ScalarNode {
				lines = append(lines, fmt.Sprintf("  line %d: cannot unmarshal %s `%s` into yaml.MapItem", c.Line, shortTag(c), c.Value))
			}
		}
		if len(lines) == 0 {
			return m, nil
		}
		return nil, fmt.Errorf("yaml: unmarshal errors:\n%s", strings.Join(lines, "\n"))
	}
	return m, nil
}

func shortTag(n *yaml.Node) string {
	v := yamlNodeValue(n)
	switch v.(type) {
	case bool:
		return "!!bool"
	case int64, uint64:
		return "!!int"
	case float64:
		return "!!float"
	case nil:
		return "!!null"
	}
	if isYAMLTimestamp(n.Value) && n.Style == 0 {
		return "!!timestamp"
	}
	return "!!str"
}

// toJSONValue converts yaml values into JSON-friendly values.
func toJSONValue(v interface{}) interface{} {
	switch t := v.(type) {
	case *OrderedMap:
		out := map[string]interface{}{}
		for _, k := range t.Keys {
			out[k] = toJSONValue(t.Values[k])
		}
		return out
	case []interface{}:
		out := make([]interface{}, len(t))
		for i, x := range t {
			out[i] = toJSONValue(x)
		}
		return out
	default:
		return v
	}
}
EOF
go vet ./... 2>&1 | head"}

