	switch t := v.(type) {
	case *OrderedMap:
		out := map[string]interface{}{}
		for _, k := range t.Keys {
			out[k] = toJSONValue(t.Values[k])
		}
		return out
	case []interface{}:
		out := make([]interface{}, len(t))
		for i, x := range t {
			out[i] = toJSONValue(x)
		}
		return out
	default:
		return v
	}
}
