func walkInlines(nodes []*inl, fn func(*inl) bool) {
	for _, n := range nodes {
		if fn(n) {
			walkInlines(n.children, fn)
		}
	}
}

func blockInlineText(src []byte, n *mdNode) string {
	var b strings.Builder
	for i, l := range n.lines {
		if i > 0 {
			b.WriteByte('\n')
		}
		line := string(src[l.start:l.stop])
		if i < len(n.lines)-1 {
			line = strings.TrimRight(line, "\n")
			line = strings.TrimSuffix(line, "\r")
		}
		if i > 0 {
			line = strings.TrimLeft(line, " \t")
		}
		b.WriteString(line)
	}
	return b.String()
}

func parseNote(content string, opts *mdOptions) (*ParsedNote, error) {
	src := []byte(content)
	var metaErr error
	var metaMap *OrderedMap
	metaParsed := false
	doc, refs := parseBlocks(src, func(b []byte) bool {
		m, err := parseFrontmatterYAML(b)
		metaParsed = true
		if err != nil {
			metaErr = err
			return false
		}
		metaMap = m
		return true
	})

	// inline parsing
	walkBlocks(doc, func(n *mdNode) {
		if n.kind == bParagraph || n.kind == bHeading || (n.kind == bMeta && n.textBlock) {
			text := blockInlineText(src, n)
			n.inlines = parseInlines(text, refs, opts)
		}
	})

	pn := &ParsedNote{Metadata: &OrderedMap{Values: map[string]interface{}{}}}

	// frontmatter
	fmEnd := -1
	if loc := frontmatterRegex.FindIndex(src); loc != nil {
		fmEnd = loc[1]
		if metaParsed {
			if metaErr != nil {
				return nil, metaErr
			}
			if metaMap != nil {
				pn.Metadata = metaMap
			}
		}
	}

	// title
	bodyStart := 0
	titleFound := false
	if fmEnd >= 0 {
		if t, ok := pn.Metadata.Values["title"].(string); ok {
			pn.Title = t
			bodyStart = fmEnd
			titleFound = true
		}
	}
	if !titleFound {
		var best *mdNode
		walkBlocks(doc, func(n *mdNode) {
			if n.kind == bHeading && len(n.lines) > 0 {
				if best == nil || n.level < best.level {
					best = n
				}
			}
		})
		if best != nil {
			pn.Title = inlineText(best.inlines)
			bodyStart = best.lines[len(best.lines)-1].stop
		}
	}
	pn.Body = strings.TrimSpace(content[bodyStart:])
	pn.Lead = parseLead(pn.Body)
	pn.WordCount = len(strings.Fields(content))

	// links
	walkBlocks(doc, func(n *mdNode) {
		if n.inlines == nil || len(n.lines) == 0 {
			return
		}
		start := n.lines[0].start
		end := n.lines[len(n.lines)-1].stop
		snippet := string(src[start:end])
		walkInlines(n.inlines, func(x *inl) bool {
			switch x.kind {
			case iLink:
				if x.dest == "" {
					return true
				}
				pn.Links = append(pn.Links, ParsedLink{
					Title: inlineText(x.children), Href: x.dest, Type: "markdown",
					Rels: strings.Fields(x.title), Snippet: snippet, SnippetStart: start, SnippetEnd: end,
				})
				return true
			case iImage:
				return false
			case iAutoLink:
				if x.autoEmail {
					return false
				}
				pn.Links = append(pn.Links, ParsedLink{
					Title: x.title, Href: x.dest, Type: "implicit", Snippet: snippet, SnippetStart: start, SnippetEnd: end,
				})
				return false
			case iWiki:
				pn.Links = append(pn.Links, ParsedLink{
					Title: x.title, Href: x.dest, Type: "wiki-link", Rels: x.rels, Snippet: snippet, SnippetStart: start, SnippetEnd: end,
				})
				return false
			}
			return true
		})
	})

	// tags
	seen := map[string]bool{}
	addTag := func(t string) {
		if t == "" || seen[t] {
			return
		}
		seen[t] = true
		pn.Tags = append(pn.Tags, t)
	}
	for _, key := range []string{"tags", "keywords"} {
		v, ok := pn.Metadata.Values[key]
		if !ok {
			continue
		}
		for _, t := range frontmatterTags(v) {
			addTag(t)
		}
	}
	walkBlocks(doc, func(n *mdNode) {
		if n.inlines == nil {
			return
		}
		walkInlines(n.inlines, func(x *inl) bool {
			if x.kind == iTag {
				for _, t := range x.tags {
					addTag(t)
				}
			}
			return true
		})
	})
	return pn, nil
}

func frontmatterTags(v interface{}) []string {
	switch t := v.(type) {
	case string:
		return strings.Fields(t)
	case []interface{}:
		var out []string
		for _, x := range t {
			switch s := x.(type) {
			case string:
				out = append(out, strings.TrimSpace(s))
			case nil:
			default:
				out = append(out, stringify(s))
			}
		}
		return out
	case nil:
		return nil
	default:
		return []string{stringify(t)}
	}
}

func parseLead(body string) string {
	lead := body
	if i := strings.Index(body, "\n\n"); i >= 0 {
		lead = body[:i]
	}
	return strings.TrimSpace(lead)
}
