package main

import (
	"encoding/json"
	"strings"
	"time"
)

const dbTimeFormat = "2006-01-02 15:04:05.999999999-07:00"

var schemaStatements = []string{
	"CREATE TABLE notes (\n\t\t\t\t\t\tid INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,\n\t\t\t\t\t\tpath TEXT NOT NULL,\n\t\t\t\t\t\tsortable_path TEXT NOT NULL,\n\t\t\t\t\t\ttitle TEXT DEFAULT('') NOT NULL,\n\t\t\t\t\t\tlead TEXT DEFAULT('') NOT NULL,\n\t\t\t\t\t\tbody TEXT DEFAULT('') NOT NULL,\n\t\t\t\t\t\traw_content TEXT DEFAULT('') NOT NULL,\n\t\t\t\t\t\tword_count INTEGER DEFAULT(0) NOT NULL,\n\t\t\t\t\t\tchecksum TEXT NOT NULL,\n\t\t\t\t\t\tcreated DATETIME DEFAULT(CURRENT_TIMESTAMP) NOT NULL,\n\t\t\t\t\t\tmodified DATETIME DEFAULT(CURRENT_TIMESTAMP) NOT NULL, metadata TEXT DEFAULT('{}') NOT NULL, filename TEXT DEFAULT('') NOT NULL,\n\t\t\t\t\t\tUNIQUE(path)\n\t\t\t\t\t)",
	"CREATE INDEX index_notes_checksum ON notes (checksum)",
	"CREATE INDEX index_notes_path ON notes (path)",
	"CREATE TABLE links (\n\t\t\t\t\t\tid INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,\n\t\t\t\t\t\tsource_id INTEGER NOT NULL REFERENCES notes(id)\n\t\t\t\t\t\t\tON DELETE CASCADE,\n\t\t\t\t\t\ttarget_id INTEGER REFERENCES notes(id)\n\t\t\t\t\t\t\tON DELETE SET NULL,\n\t\t\t\t\t\ttitle TEXT DEFAULT('') NOT NULL,\n\t\t\t\t\t\thref TEXT NOT NULL,\n\t\t\t\t\t\texternal INT DEFAULT(0) NOT NULL,\n\t\t\t\t\t\trels TEXT DEFAULT('') NOT NULL,\n\t\t\t\t\t\tsnippet TEXT DEFAULT('') NOT NULL\n\t\t\t\t\t, snippet_start INTEGER DEFAULT(0) NOT NULL, snippet_end INTEGER DEFAULT(0) NOT NULL, type TEXT DEFAULT('') NOT NULL)",
	"CREATE INDEX index_links_source_id_target_id ON links (source_id, target_id)",
	"CREATE VIRTUAL TABLE notes_fts USING fts5(\n\t\t\t\t\t\tpath, title, body,\n\t\t\t\t\t\tcontent = notes,\n\t\t\t\t\t\tcontent_rowid = id,\n\t\t\t\t\t\ttokenize = \"porter unicode61 remove_diacritics 1 tokenchars '''&/'\"\n\t\t\t\t\t)",
	"CREATE TRIGGER trigger_notes_ai AFTER INSERT ON notes BEGIN\n\t\t\t\t\t\tINSERT INTO notes_fts(rowid, path, title, body) VALUES (new.id, new.path, new.title, new.body);\n\t\t\t\t\tEND",
	"CREATE TRIGGER trigger_notes_ad AFTER DELETE ON notes BEGIN\n\t\t\t\t\t\tINSERT INTO notes_fts(notes_fts, rowid, path, title, body) VALUES('delete', old.id, old.path, old.title, old.body);\n\t\t\t\t\tEND",
	"CREATE TRIGGER trigger_notes_au AFTER UPDATE ON notes BEGIN\n\t\t\t\t\t\tINSERT INTO notes_fts(notes_fts, rowid, path, title, body) VALUES('delete', old.id, old.path, old.title, old.body);\n\t\t\t\t\t\tINSERT INTO notes_fts(rowid, path, title, body) VALUES (new.id, new.path, new.title, new.body);\n\t\t\t\t\tEND",
	"CREATE TABLE collections (\n\t\t\t\t\t\tid INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,\n\t\t\t\t\t\tkind TEXT NO NULL,\n\t\t\t\t\t\tname TEXT NOT NULL,\n\t\t\t\t\t\tUNIQUE(kind, name)\n\t\t\t\t\t)",
	"CREATE INDEX index_collections ON collections (kind, name)",
	"CREATE TABLE notes_collections (\n\t\t\t\t\t\tid INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,\n\t\t\t\t\t\tnote_id INTEGER NOT NULL REFERENCES notes(id)\n\t\t\t\t\t\t\tON DELETE CASCADE,\n\t\t\t\t\t\tcollection_id INTEGER NOT NULL REFERENCES collections(id)\n\t\t\t\t\t\t\tON DELETE CASCADE\n\t\t\t\t\t)",
	"CREATE INDEX index_notes_collections ON notes_collections (note_id, collection_id)",
	"CREATE VIEW notes_with_metadata AS\n\t\t\t\t\t SELECT n.*, GROUP_CONCAT(c.name, '\x01') AS tags\n\t\t\t\t\t   FROM notes n\n\t\t\t\t\t   LEFT JOIN notes_collections nc ON nc.note_id = n.id\n\t\t\t\t\t   LEFT JOIN collections c ON nc.collection_id = c.id AND c.kind = 'tag'\n\t\t\t\t\t  GROUP BY n.id",
	"CREATE TABLE metadata (\n\t\t\t\t\t\tkey TEXT PRIMARY KEY NOT NULL,\n\t\t\t\t\t\tvalue TEXT NO NULL\n\t\t\t\t\t)",
	"CREATE VIEW resolved_links AS\n\t\t\t\t\t SELECT l.*, s.path AS source_path, s.title AS source_title, t.path AS target_path, t.title AS target_title\n\t\t\t\t\t   FROM links l\n\t\t\t\t\t   LEFT JOIN notes s ON l.source_id = s.id\n\t\t\t\t\t   LEFT JOIN notes t ON l.target_id = t.id",
	"CREATE INDEX index_notes_filename ON notes (filename)",
}

type Note struct {
	ID        int64
	Path      string
	Title     string
	Lead      string
	Body      string
	Raw       string
	WordCount int
	Checksum  string
	Created   time.Time
	Modified  time.Time
	Metadata  map[string]interface{}
	MetaJSON  string
	Tags      []string
	Filename  string
	// search results
	Snippets []string
}

type Link struct {
	ID           int64
	SourceID     int64
	TargetID     int64 // 0 if none
	Title        string
	Href         string
	External     bool
	Rels         []string
	Snippet      string
	SnippetStart int
	SnippetEnd   int
	Type         string
	SourcePath   string
	TargetPath   string
}

type Index struct {
	db *DB
}

func openIndex(path string) (*Index, error) {
	db, err := OpenDB(path)
	if err != nil {
		return nil, err
	}
	if err := db.ExecScript("PRAGMA foreign_keys = ON"); err != nil {
		return nil, err
	}
	ver := int64(0)
	db.Query("PRAGMA user_version", nil, func(s *Stmt) error {
		ver = s.Int(0)
		return nil
	})
	if ver == 0 {
		if err := db.ExecScript("BEGIN"); err != nil {
			return nil, err
		}
		for _, st := range schemaStatements {
			if err := db.ExecScript(st); err != nil {
				db.ExecScript("ROLLBACK")
				return nil, err
			}
		}
		db.Exec("INSERT INTO metadata (key, value) VALUES ('zk.reindexing_required', 'false')")
		db.ExecScript("PRAGMA user_version = 8")
		if err := db.ExecScript("COMMIT"); err != nil {
			return nil, err
		}
	}
	return &Index{db: db}, nil
}

func (ix *Index) Close() {
	ix.db.Close()
}

func formatDBTime(t time.Time) string {
	return t.Format(dbTimeFormat)
}

func parseDBTime(s string) time.Time {
	s = strings.TrimSuffix(s, "Z")
	for _, f := range []string{
		"2006-01-02 15:04:05.999999999-07:00",
		"2006-01-02T15:04:05.999999999-07:00",
		"2006-01-02 15:04:05.999999999",
		"2006-01-02T15:04:05.999999999",
		"2006-01-02 15:04:05",
		"2006-01-02T15:04:05",
