{"command":"cd /workspace && cat > tmpl_parse.go <<'EOF'
package main

import (
	"fmt"
	"strconv"
	"strings"
)

// A Handlebars-like template engine mimicking aymerick/raymond behaviour.

type tNodeKind int

const (
	tnText tNodeKind = iota
	tnMustache
	tnBlock
	tnComment
	tnPartial
)

type tExprKind int

const (
	teExpr tExprKind = iota
	tePath
	teString
	teNumber
	teBool
	teSub
)

type tParam struct {
	kind   tExprKind
	path   *tPath
	str    string
	num    float64
	numStr string
	isInt  bool
	b      bool
	sub    *tExpr
	pos    int
}

type tPath struct {
	original string
	parts    []string
	data     bool // @-prefixed
	depth    int  // ../ count
	this     bool // explicit this / ./
	pos      int
}

type tHash struct {
	key   string
	value *tParam
}

type tExpr struct {
	head   *tParam // path or literal
	params []*tParam
	hash   []tHash
	pos    int // position of opening {{
}

type tNode struct {
	kind      tNodeKind
	text      string
	expr      *tExpr
	unescaped bool
	program   []*tNode
	inverse   []*tNode
	blockParams []string
	inverted  bool // {{^x}}
	pos       int
}

type tmplParseError struct {
	msg string
}

func (e *tmplParseError) Error() string { return e.msg }

type tParser struct {
	src  string
	pos  int
}

func parseTemplate(src string) (nodes []*tNode, err error) {
	defer func() {
		if r := recover(); r != nil {
			if pe, ok := r.(*tmplParseError); ok {
				err = pe
				return
			}
			panic(r)
		}
	}()
	p := &tParser{src: src}
	nodes, endTok := p.parseProgram(nil)
	if endTok != "" {
		p.fail(p.lineAt(p.pos), "Syntax error\nToken: OpenEndBlock{\"{{/\"}")
	}
	return nodes, nil
}

func (p *tParser) lineAt(pos int) int {
	return strings.Count(p.src[:minInt(pos, len(p.src))], "\n") + 1
}

func (p *tParser) fail(line int, msg string) {
	panic(&tmplParseError{msg: fmt.Sprintf("Parse error on line %d:\n%s", line, msg)})
}

// stripLeft/right for whitespace control
func trimRightWS(nodes []*tNode) {
	if len(nodes) == 0 {
		return
	}
	n := nodes[len(nodes)-1]
	if n.kind == tnText {
		n.text = strings.TrimRight(n.text, " \t\r\n")
	}
}

type blockEnd struct {
	kind string // "close", "else", "elseif"
	name string
	namePos int
	tildeRight bool
	elseExpr *tExpr
	elseStart int
}

// parseProgram parses until a close/else tag at this level.
func (p *tParser) parseProgram(stop *blockEnd) ([]*tNode, string) {
	var nodes []*tNode
	stripNextLeft := false
	for p.pos < len(p.src) {
		idx := strings.Index(p.src[p.pos:], "{{")
		// handle escaped \{{
		var text string
		if idx < 0 {
			text = p.src[p.pos:]
			p.pos = len(p.src)
		} else {
			start := p.pos + idx
			if start > 0 && p.src[start-1] == '\\' && !(start > 1 && p.src[start-2] == '\\') {
				// escaped mustache: emit text up to backslash, then literal until next {{
				text = p.src[p.pos : start-1]
				rest := p.src[start:]
				nxt := strings.Index(rest[2:], "{{")
				if nxt < 0 {
					text += rest
					p.pos = len(p.src)
				} else {
					text += rest[:nxt+2]
					p.pos = start + nxt + 2
				}
				if stripNextLeft {
					text = strings.TrimLeft(text, " \t\r\n")
					stripNextLeft = false
				}
				nodes = appendText(nodes, text)
				continue
			}
			text = p.src[p.pos:start]
			p.pos = start
		}
		if stripNextLeft {
			text = strings.TrimLeft(text, " \t\r\n")
			stripNextLeft = false
		}
		if text != "" {
			nodes = appendText(nodes, text)
		}
		if p.pos >= len(p.src) {
			break
		}
		// parse tag
		tagStart := p.pos
		p.pos += 2
		triple := false
		if p.pos < len(p.src) && p.src[p.pos] == '{' {
			triple = true
			p.pos++
		}
		tildeLeft := false
		if p.pos < len(p.src) && p.src[p.pos] == '~' {
			tildeLeft = true
			p.pos++
		}
		if tildeLeft {
			trimRightWS(nodes)
		}
		if p.pos < len(p.src) && p.src[p.pos] == '!' {
			// comment
			var end int
			if strings.HasPrefix(p.src[p.pos:], "!--") {
				e := strings.Index(p.src[p.pos:], "--}}")
				if e < 0 {
					p.fail(p.lineAt(tagStart), "Lexer error\nToken: Error{\"Unclosed comment\"}")
				}
				end = p.pos + e + 4
				if e > 0 && p.src[p.pos+e-1] == '~' {
					stripNextLeft = true
				}
			} else {
				e := strings.Index(p.src[p.pos:], "}}")
				if e < 0 {
					p.fail(p.lineAt(tagStart), "Lexer error\nToken: Error{\"Unclosed comment\"}")
				}
				end = p.pos + e + 2
				if e > 0 && p.src[p.pos+e-1] == '~' {
					stripNextLeft = true
				}
			}
			p.pos = end
			continue
		}
		if triple {
			expr, tr := p.parseExpr(tagStart, "}}}")
			if tr {
				stripNextLeft = true
			}
			nodes = append(nodes, &tNode{kind: tnMustache, expr: expr, unescaped: true, pos: tagStart})
			continue
		}
		c := byte(0)
		if p.pos < len(p.src) {
			c = p.src[p.pos]
		}
		switch c {
		case '&':
			p.pos++
			expr, tr := p.parseExpr(tagStart, "}}")
			if tr {
				stripNextLeft = true
			}
			nodes = append(nodes, &tNode{kind: tnMustache, expr: expr, unescaped: true, pos: tagStart})
		case '>':
			p.pos++
			expr, tr := p.parseExpr(tagStart, "}}")
			if tr {
				stripNextLeft = true
			}
			nodes = append(nodes, &tNode{kind: tnPartial, expr: expr, pos: tagStart})
		case '#', '^':
			inverted := c == '^'
			p.pos++
			// {{^}} alone is else
			p.skipWS()
			if inverted && strings.HasPrefix(p.src[p.pos:], "}}") {
				p.pos += 2
				return nodes, "else"
			}
			if c == '#' && p.pos < len(p.src) && p.src[p.pos] == '*' {
				p.pos++
			}
			expr, bparams, tr := p.parseBlockOpen(tagStart)
			if tr {
				stripNextLeft = true
			}
			node := &tNode{kind: tnBlock, expr: expr, inverted: inverted, blockParams: bparams, pos: tagStart}
			name := expr.head.path
			end := &blockEnd{}
			prog, kind := p.parseBlockBody(end)
			if kind == "" {
				p.fail(p.lineAt(p.pos), "Expecting OpenEndBlock, got: 'EOF'")
			}
			if inverted {
				node.inverse = prog
			} else {
				node.program = prog
			}
			cur := node
			for kind == "else" || kind == "elseif" {
				if kind == "elseif" {
					// chained else if: create nested block in inverse
					sub := &tNode{kind: tnBlock, expr: end.elseExpr, pos: end.elseStart}
					end2 := &blockEnd{}
					prog2, kind2 := p.parseBlockBody(end2)
					sub.program = prog2
					cur.inverse = []*tNode{sub}
					cur = sub
					kind = kind2
					end = end2
					continue
				}
				end2 := &blockEnd{}
				prog2, kind2 := p.parseBlockBody(end2)
				if inverted {
					cur.program = prog2
				} else {
					cur.inverse = prog2
				}
				kind = kind2
				end = end2
				if kind == "else" || kind == "elseif" {
					p.fail(p.lineAt(p.pos), "Syntax error")
				}
			}
			if kind == "" {
				p.fail(p.lineAt(p.pos), "Expecting OpenEndBlock, got: 'EOF'")
			}
			openName := ""
			if name != nil {
				openName = name.original
			}
			if end.name != openName {
				p.fail(p.lineAt(tagStart), fmt.Sprintf("%s doesn't match %s\nNode: Path{Original:'%s', Pos:%d}", openName, end.name, end.name, end.namePos))
			}
			if end.tildeRight {
				stripNextLeft = true
			}
			nodes = append(nodes, node)
		case '/':
			p.pos++
			p.skipWS()
			namePos := p.pos
			path := p.parsePathToken()
			p.skipWS()
			tr := false
			if p.pos < len(p.src) && p.src[p.pos] == '~' {
				tr = true
				p.pos++
			}
			if !strings.HasPrefix(p.src[p.pos:], "}}") {
				p.fail(p.lineAt(tagStart), "Lexer error")
			}
			p.pos += 2
			if stop == nil {
				p.fail(p.lineAt(tagStart), "Syntax error\nToken: OpenEndBlock{\"{{/\"}")
			}
			stop.kind = "close"
			stop.name = path
			stop.namePos = namePos
			stop.tildeRight = tr
			return nodes, "close"
		default:
			// else?
			save := p.pos
			p.skipWS()
			if strings.HasPrefix(p.src[p.pos:], "else") {
				after := p.pos + 4
				rest := p.src[after:]
				trimmed := strings.TrimLeft(rest, " \t\r\n")
				if strings.HasPrefix(trimmed, "}}") || strings.HasPrefix(trimmed, "~}}") {
					if stop == nil {
						p.fail(p.lineAt(tagStart), "Syntax error")
					}
					p.pos = after + (len(rest) - len(trimmed))
					if p.src[p.pos] == '~' {
						stripNextLeft = true
						p.pos++
					}
					p.pos += 2
					stop.kind = "else"
					return nodes, "else"
				}
				if len(rest) > 0 && (rest[0] == ' ' || rest[0] == '\t') {
					if stop == nil {
						p.fail(p.lineAt(tagStart), "Syntax error")
					}
					p.pos = after
					expr, _, tr := p.parseBlockOpen(tagStart)
					if tr {
						stripNextLeft = true
					}
					stop.kind = "elseif"
					stop.elseExpr = expr
					stop.elseStart = tagStart
					return nodes, "elseif"
				}
			}
			p.pos = save
			expr, tr := p.parseExpr(tagStart, "}}")
			if tr {
				stripNextLeft = true
			}
			nodes = append(nodes, &tNode{kind: tnMustache, expr: expr, pos: tagStart})
		}
	}
	return nodes, ""
}

func appendText(nodes []*tNode, text string) []*tNode {
	if len(nodes) > 0 && nodes[len(nodes)-1].kind == tnText {
		nodes[len(nodes)-1].text += text
		return nodes
	}
	return append(nodes, &tNode{kind: tnText, text: text})
}

func (p *tParser) parseBlockBody(end *blockEnd) ([]*tNode, string) {
	nodes, kind := p.parseProgram(end)
	return nodes, kind
}

func (p *tParser) skipWS() {
	for p.pos < len(p.src) && (p.src[p.pos] == ' ' || p.src[p.pos] == '\t' || p.src[p.pos] == '\n' || p.src[p.pos] == '\r') {
		p.pos++
	}
}

func isIDChar(c byte) bool {
	// Handlebars ID: anything except whitespace and special chars
	switch c {
	case ' ', '\t', '\n', '\r', '!', '"', '#', '%', '&', '\'', '(', ')', '*', '+', ',', '.', '/', ';', '<', '=', '>', '@', '[', '\\', ']', '^', '`', '{', '|', '}', '~':
		return false
	}
	return true
}

func (p *tParser) parsePathToken() string {
	start := p.pos
	for p.pos < len(p.src) {
		c := p.src[p.pos]
		if isIDChar(c) || c == '.' || c == '/' || c == '@' || c == '-' {
			p.pos++
			continue
		}
		if c == '[' {
			e := strings.IndexByte(p.src[p.pos:], ']')
			if e < 0 {
				break
			}
			p.pos += e + 1
			continue
		}
		break
	}
	return p.src[start:p.pos]
}

func (p *tParser) peekCloseAt(close string) bool {
	return strings.HasPrefix(p.src[p.pos:], close) || strings.HasPrefix(p.src[p.pos:], "~"+close)
}

func (p *tParser) lexError(tagStart int, msg string) {
	p.fail(p.lineAt(tagStart), fmt.Sprintf("Lexer error\nToken: Error{%q}", msg))
}

// parseExpr parses an expression until close. returns tildeRight.
func (p *tParser) parseExpr(tagStart int, close string) (*tExpr, bool) {
	p.skipWS()
	expr := &tExpr{pos: tagStart}
	if p.peekCloseAt(close) {
		tok := "Close{\"}}\"}"
		p.fail(p.lineAt(tagStart), "Expecting ID, got: '"+tok+"'")
	}
	head := p.parseParam(tagStart, close, true)
	expr.head = head
	for {
		p.skipWS()
		if p.pos >= len(p.src) {
			p.lexError(tagStart, "Unclosed expression")
		}
		if strings.HasPrefix(p.src[p.pos:], "~"+close) {
			p.pos += 1 + len(close)
			return expr, true
		}
		if strings.HasPrefix(p.src[p.pos:], close) {
			p.pos += len(close)
			return expr, false
		}
		if p.src[p.pos] == '}' {
			p.lexError(tagStart, "Unexpected character in expression: '}'")
		}
		// hash?
		if k, ok := p.peekHashKey(); ok {
			p.pos += len(k)
			p.skipWS()
			p.pos++ // '='
			p.skipWS()
			v := p.parseParam(tagStart, close, false)
			expr.hash = append(expr.hash, tHash{key: k, value: v})
			continue
		}
		param := p.parseParam(tagStart, close, false)
		expr.params = append(expr.params, param)
	}
}

func (p *tParser) parseBlockOpen(tagStart int) (*tExpr, []string, bool) {
	p.skipWS()
	expr := &tExpr{pos: tagStart}
	if p.peekCloseAt("}}") {
		p.fail(p.lineAt(tagStart), "Expecting ID, got: 'Close{\"}}\"}'")
	}
	expr.head = p.parseParam(tagStart, "}}", true)
	var bparams []string
	for {
		p.skipWS()
		if p.pos >= len(p.src) {
			p.lexError(tagStart, "Unclosed expression")
		}
		if strings.HasPrefix(p.src[p.pos:], "~}}") {
			p.pos += 3
			return expr, bparams, true
		}
		if strings.HasPrefix(p.src[p.pos:], "}}") {
			p.pos += 2
			return expr, bparams, false
		}
		if strings.HasPrefix(p.src[p.pos:], "as |") || strings.HasPrefix(p.src[p.pos:], "as|") {
			i := strings.IndexByte(p.src[p.pos:], '|')
			p.pos += i + 1
			e := strings.IndexByte(p.src[p.pos:], '|')
			if e < 0 {
				p.lexError(tagStart, "Unclosed expression")
			}
			bparams = strings.Fields(p.src[p.pos : p.pos+e])
			p.pos += e + 1
			continue
		}
		if k, ok := p.peekHashKey(); ok {
			p.pos += len(k)
			p.skipWS()
			p.pos++
			p.skipWS()
			v := p.parseParam(tagStart, "}}", false)
			expr.hash = append(expr.hash, tHash{key: k, value: v})
			continue
		}
		expr.params = append(expr.params, p.parseParam(tagStart, "}}", false))
	}
}

func (p *tParser) peekHashKey() (string, bool) {
	i := p.pos
	for i < len(p.src) && (isIDChar(p.src[i]) || p.src[i] == '-') {
		i++
	}
	if i == p.pos {
		return "", false
	}
	j := i
	for j < len(p.src) && (p.src[j] == ' ' || p.src[j] == '\t') {
		j++
	}
	if j < len(p.src) && p.src[j] == '=' {
		return p.src[p.pos:i], true
	}
	return "", false
}

func (p *tParser) parseParam(tagStart int, close string, isHead bool) *tParam {
	if p.pos >= len(p.src) {
		p.lexError(tagStart, "Unclosed expression")
	}
	c := p.src[p.pos]
	switch {
	case c == '"' || c == '\'':
		q := c
		start := p.pos + 1
		i := start
		var b strings.Builder
		for i < len(p.src) && p.src[i] != q {
			if p.src[i] == '\\' && i+1 < len(p.src) && p.src[i+1] == q {
				b.WriteByte(q)
				i += 2
				continue
			}
			b.WriteByte(p.src[i])
			i++
		}
		if i >= len(p.src) {
			p.lexError(tagStart, "Unterminated string")
		}
		p.pos = i + 1
		return &tParam{kind: teString, str: b.String(), pos: start}
	case c == '(':
		start := p.pos
		p.pos++
		sub := &tExpr{pos: start}
		p.skipWS()
		sub.head = p.parseParam(tagStart, close, true)
		for {
			p.skipWS()
			if p.pos >= len(p.src) {
				p.lexError(tagStart, "Unclosed expression")
			}
			if p.src[p.pos] == ')' {
				p.pos++
				break
			}
			if k, ok := p.peekHashKey(); ok {
				p.pos += len(k)
				p.skipWS()
				p.pos++
				p.skipWS()
				v := p.parseParam(tagStart, close, false)
				sub.hash = append(sub.hash, tHash{key: k, value: v})
				continue
			}
			sub.params = append(sub.params, p.parseParam(tagStart, close, false))
		}
		return &tParam{kind: teSub, sub: sub, pos: start}
	case (c >= '0' && c <= '9') || (c == '-' && p.pos+1 < len(p.src) && p.src[p.pos+1] >= '0' && p.src[p.pos+1] <= '9'):
		start := p.pos
		i := p.pos + 1
		for i < len(p.src) && ((p.src[i] >= '0' && p.src[i] <= '9') || p.src[i] == '.') {
			i++
		}
		// must be followed by whitespace, close or ')'
		if i < len(p.src) && isIDChar(p.src[i]) && p.src[i] != '}' {
			// treat as path
			break
		}
		numStr := p.src[start:i]
		p.pos = i
		f, _ := strconv.ParseFloat(numStr, 64)
		isInt := !strings.Contains(numStr, ".")
		if isHead {
			// literal head
		}
		return &tParam{kind: teNumber, num: f, numStr: numStr, isInt: isInt, pos: start}
	}
	start := p.pos
	tok := p.parsePathToken()
	if tok == "" {
		if p.pos < len(p.src) && p.src[p.pos] == '}' {
			p.lexError(tagStart, "Unexpected character in expression: '}'")
		}
		ch := p.src[p.pos]
		p.lexError(tagStart, fmt.Sprintf("Unexpected character in expression: '%c'", ch))
	}
	if tok == "true" || tok == "false" {
		return &tParam{kind: teBool, b: tok == "true", pos: start}
	}
	path := parsePathString(tok)
	if path == nil {
		p.fail(p.lineAt(tagStart), "Expecting ID, got: 'Number{\""+lastSeg(tok)+"\"}'")
	}
	path.pos = start
	return &tParam{kind: tePath, path: path, pos: start}
}

func lastSeg(tok string) string {
	i := strings.LastIndexAny(tok, "./")
	return tok[i+1:]
}

func parsePathString(tok string) *tPath {
	p := &tPath{original: tok}
	s := tok
	if strings.HasPrefix(s, "@") {
		p.data = true
		s = s[1:]
	}
	for strings.HasPrefix(s, "../") {
		p.depth++
		s = s[3:]
	}
	if s == ".." {
		p.depth++
		s = ""
	}
	if strings.HasPrefix(s, "./") {
		p.this = true
		s = s[2:]
	}
	if s == "this" || s == "." || s == "" {
		p.this = true
		return p
	}
	if strings.HasPrefix(s, "this.") || strings.HasPrefix(s, "this/") {
		p.this = true
		s = s[5:]
	}
	// split on . and / respecting [..]
	var parts []string
	cur := ""
	i := 0
	for i < len(s) {
		c := s[i]
		if c == '[' {
			e := strings.IndexByte(s[i:], ']')
			if e < 0 {
				cur += s[i:]
				break
			}
			cur += s[i+1 : i+e]
			i += e + 1
			continue
		}
		if c == '.' || c == '/' {
			parts = append(parts, cur)
			cur = ""
			i++
			continue
		}
		cur += string(c)
		i++
	}
	parts = append(parts, cur)
	for idx, part := range parts {
		if idx > 0 && part != "" && part[0] >= '0' && part[0] <= '9' && !strings.Contains(tok, "["+part+"]") {
			return nil
		}
	}
	p.parts = parts
	return p
}
