		return nil, false
	case htStringSlice:
		if v == nil {
			return []string(nil), true
		}
		if s, ok := v.([]string); ok {
			return s, true
		}
		return nil, false
	case htTime:
		if tm, ok := v.(time.Time); ok {
			return tm, true
		}
		return nil, false
	}
	return v, true
}

func tTruthy(v interface{}) bool {
	switch t := v.(type) {
	case nil:
		return false
	case string:
		return t != ""
	case bool:
		return t
	case int:
		return t != 0
	case int64:
		return t != 0
	case uint64:
		return t != 0
	case float64:
		return t != 0
	case []interface{}:
		return len(t) > 0
	case []string:
		return len(t) > 0
	case map[string]interface{}:
		return len(t) > 0
	case map[string]string:
		return len(t) > 0
	case *OrderedMap:
		return len(t.Keys) > 0
	case time.Time:
		return true
	}
	return true
}

func tStr(v interface{}) string {
	switch t := v.(type) {
	case nil:
		return ""
	case string:
		return t
	case bool:
		if t {
			return "true"
		}
		return "false"
	case int:
		return strconv.Itoa(t)
	case int64:
		return strconv.FormatInt(t, 10)
	case uint64:
		return strconv.FormatUint(t, 10)
	case float64:
		return strconv.FormatFloat(t, 'f', -1, 64)
	case []string:
		return strings.Join(t, "")
	case []interface{}:
		var b strings.Builder
		for _, x := range t {
			b.WriteString(tStr(x))
		}
		return b.String()
	case *OrderedMap:
		return fmt.Sprintf("%s", toJSONValue(t))
	case *helperOpts:
		return ""
	}
	return fmt.Sprintf("%s", v)
}

func sortedKeys(v interface{}) []string {
	var keys []string
	switch t := v.(type) {
	case map[string]interface{}:
		for k := range t {
			keys = append(keys, k)
		}
	case map[string]string:
		for k := range t {
			keys = append(keys, k)
		}
	case *OrderedMap:
		keys = append(keys, t.Keys...)
	}
	sort.Strings(keys)
	return keys
}

func (e *tEval) evalBlock(n *tNode) string {
