			b.WriteString(e.renderProgram(n.program, item, map[string]interface{}{"index": i, "first": i == 0, "last": i == len(t)-1}, nil))
		}
		return b.String()
	}
	return e.renderProgram(n.program, v, nil, nil)
}

func baseHelpers() map[string]*helperDef {
	h := map[string]*helperDef{}
	h["if"] = &helperDef{params: []hType{htAny, htOpts}, fn: func(a []interface{}, o *helperOpts) interface{} {
		if tTruthy(a[0]) {
			return o.Fn()
		}
		return o.Inverse()
	}}
	h["unless"] = &helperDef{params: []hType{htAny, htOpts}, fn: func(a []interface{}, o *helperOpts) interface{} {
		if !tTruthy(a[0]) {
			return o.Fn()
		}
		return o.Inverse()
	}}
	h["with"] = &helperDef{params: []hType{htAny, htOpts}, fn: func(a []interface{}, o *helperOpts) interface{} {
		if !tTruthy(a[0]) {
			return o.Inverse()
		}
		var bp map[string]interface{}
		if o.block != nil && len(o.block.blockParams) > 0 {
			bp = map[string]interface{}{o.block.blockParams[0]: a[0]}
		}
		return o.FnWith(a[0], nil, bp)
	}}
	h["each"] = &helperDef{params: []hType{htAny, htOpts}, fn: func(a []interface{}, o *helperOpts) interface{} {
		v := a[0]
		if !tTruthy(v) {
			return o.Inverse()
		}
		var b strings.Builder
		bpNames := []string{}
		if o.block != nil {
			bpNames = o.block.blockParams
		}
		mk := func(item interface{}, key interface{}) map[string]interface{} {
			if len(bpNames) == 0 {
				return nil
			}
			m := map[string]interface{}{bpNames[0]: item}
			if len(bpNames) > 1 {
				m[bpNames[1]] = key
			}
			return m
		}
		switch t := v.(type) {
		case []interface{}:
			for i, item := range t {
				b.WriteString(o.FnWith(item, map[string]interface{}{"index": i, "first": i == 0, "last": i == len(t)-1}, mk(item, i)))
			}
		case []string:
			for i, item := range t {
				b.WriteString(o.FnWith(item, map[string]interface{}{"index": i, "first": i == 0, "last": i == len(t)-1}, mk(item, i)))
			}
		case map[string]interface{}, map[string]string, *OrderedMap:
			keys := sortedKeys(t)
			for i, k := range keys {
				item := lookupField(t, k)
				b.WriteString(o.FnWith(item, map[string]interface{}{"key": k, "index": i, "first": i == 0, "last": i == len(keys)-1}, mk(item, k)))
			}
		default:
			return o.FnWith(v, nil, nil)
		}
		return b.String()
	}}
	h["lookup"] = &helperDef{params: []hType{htAny, htString, htOpts}, fn: func(a []interface{}, o *helperOpts) interface{} {
		return lookupField(a[0], a[1].(string))
	}}
	h["log"] = &helperDef{params: []hType{htString}, fn: func(a []interface{}, o *helperOpts) interface{} {
		log.Print(a[0].(string))
		return ""
	}}
	h["equal"] = &helperDef{params: []hType{htAny, htAny, htOpts}, fn: func(a []interface{}, o *helperOpts) interface{} {
		if tStr(a[0]) == tStr(a[1]) {
