cd /workspace && cat > tmpl_eval.go <<'EOF'
package main

import (
	"fmt"
	"log"
	"reflect"
	"sort"
	"strconv"
	"strings"
	"time"
)

type tmplEvalError struct{ msg string }

func (e *tmplEvalError) Error() string { return e.msg }

type tFrame struct {
	ctx    interface{}
	data   map[string]interface{}
	bparams map[string]interface{}
}

type tEval struct {
	root     interface{}
	frames   []*tFrame
	out      *strings.Builder
	curNode  string
	blocks   []*tNode
	helpers  map[string]*helperDef
	inBlockExpr bool
}

type helperOpts struct {
	ev      *tEval
	block   *tNode
	ctx     interface{}
	hash    map[string]interface{}
	isBlock bool
}

func (o *helperOpts) Fn() string {
	if o.block == nil || o.block.program == nil {
		return ""
	}
	return o.ev.renderProgram(o.block.program, o.ctx, nil, nil)
}

func (o *helperOpts) FnWith(ctx interface{}, data map[string]interface{}, bp map[string]interface{}) string {
	if o.block == nil {
		return ""
	}
	return o.ev.renderProgram(o.block.program, ctx, data, bp)
}

func (o *helperOpts) Inverse() string {
	if o.block == nil || o.block.inverse == nil {
		return ""
	}
	return o.ev.renderProgram(o.block.inverse, o.ctx, nil, nil)
}

// helper parameter types
type hType int

const (
	htString hType = iota
	htInt
	htBool
	htAny
	htStringSlice
	htTime
	htOpts // options or any: last param that can receive options
)

type helperDef struct {
	params []hType
	fn     func(args []interface{}, opts *helperOpts) interface{}
}

func (e *tEval) errorf(format string, args ...interface{}) {
	msg := fmt.Sprintf(format, args...)
	panic(&tmplEvalError{msg: "Evaluation error: " + msg + "\nCurrent node:\n\t" + e.curNode})
}

func renderTemplate(nodes []*tNode, ctx interface{}, helpers map[string]*helperDef) (res string, err error) {
	ev := &tEval{root: ctx, helpers: helpers}
	defer func() {
		if r := recover(); r != nil {
			if te, ok := r.(*tmplEvalError); ok {
				err = te
				return
			}
			panic(r)
		}
	}()
	return ev.renderProgram(nodes, ctx, nil, nil), nil
}

func (e *tEval) renderProgram(nodes []*tNode, ctx interface{}, data map[string]interface{}, bp map[string]interface{}) string {
	fr := &tFrame{ctx: ctx, data: data, bparams: bp}
	e.frames = append(e.frames, fr)
	defer func() { e.frames = e.frames[:len(e.frames)-1] }()
	var b strings.Builder
	for _, n := range nodes {
		switch n.kind {
		case tnText:
			b.WriteString(n.text)
		case tnMustache:
			v := e.evalExpr(n.expr, nil, false)
			b.WriteString(tStr(v))
		case tnPartial:
			name := ""
			if n.expr.head.path != nil {
				name = n.expr.head.path.original
			}
			e.curNode = fmt.Sprintf("Partial{Name:Path{Original:'%s', Pos:%d}, Pos:%d}", name, n.expr.head.pos, n.pos)
			e.errorf("Partial not found: %s", name)
		case tnBlock:
			b.WriteString(e.evalBlock(n))
		}
	}
	return b.String()
}

func (e *tEval) curFrame() *tFrame {
	return e.frames[len(e.frames)-1]
}

func nodeDesc(p *tParam) string {
	switch p.kind {
	case tePath:
		return fmt.Sprintf("Path{Original:'%s', Pos:%d}", p.path.original, p.pos)
	case teString:
		return fmt.Sprintf("String{Value:'%s', Pos:%d}", p.str, p.pos)
	case teNumber:
		return fmt.Sprintf("Number{Value:%s, Pos:%d}", p.numStr, p.pos)
	case teBool:
		return fmt.Sprintf("Boolean{Value:%t, Pos:%d}", p.b, p.pos)
	case teSub:
		return fmt.Sprintf("Sexp{Path:%s, Pos:%d}", nodeDesc(p.sub.head), p.pos)
	}
	return ""
}

func exprDesc(x *tExpr) string {
	return fmt.Sprintf("Expr{Path:%s, Pos:%d}", nodeDesc(x.head), x.pos)
}

func (e *tEval) evalParam(p *tParam) interface{} {
	e.curNode = nodeDesc(p)
	switch p.kind {
	case teString:
		return p.str
	case teNumber:
		if p.isInt {
			i, _ := strconv.ParseInt(p.numStr, 10, 64)
			return int(i)
		}
		return p.num
	case teBool:
		return p.b
	case tePath:
		// a path that names a helper is called with no params
		if len(p.path.parts) == 1 && !p.path.data && !p.path.this && p.path.depth == 0 {
			if h, ok := e.helpers[p.path.parts[0]]; ok {
				return e.callHelper(p.path.parts[0], h, nil, nil, &tExpr{head: p, pos: p.pos}, nil, false)
			}
		}
		return e.resolvePath(p.path)
	case teSub:
		return e.evalExpr(p.sub, nil, true)
	}
	return nil
}

func (e *tEval) resolvePath(path *tPath) interface{} {
	fi := len(e.frames) - 1 - path.depth
	if fi < 0 {
		fi = 0
	}
	if path.data {
		if len(path.parts) > 0 && path.parts[0] == "root" {
			return lookupParts(e.root, path.parts[1:])
		}
		for i := len(e.frames) - 1; i >= 0; i-- {
			fr := e.frames[i]
			if fr.data != nil {
				if v, ok := fr.data[path.parts[0]]; ok {
					return lookupParts(v, path.parts[1:])
				}
			}
		}
		return nil
	}
	if path.this && len(path.parts) == 0 {
		return e.frames[fi].ctx
	}
	if !path.this && path.depth == 0 && len(path.parts) > 0 {
		for i := len(e.frames) - 1; i >= 0; i-- {
			fr := e.frames[i]
			if fr.bparams != nil {
				if v, ok := fr.bparams[path.parts[0]]; ok {
					return lookupParts(v, path.parts[1:])
				}
			}
		}
	}
	return lookupParts(e.frames[fi].ctx, path.parts)
}

func lookupParts(v interface{}, parts []string) interface{} {
	for _, part := range parts {
		v = lookupField(v, part)
		if v == nil {
			return nil
		}
	}
	return v
}

func lookupField(v interface{}, name string) interface{} {
	switch t := v.(type) {
	case map[string]interface{}:
		return t[name]
	case map[string]string:
		if s, ok := t[name]; ok {
			return s
		}
		return nil
	case *OrderedMap:
		return t.Values[name]
	case []interface{}:
		i, err := strconv.Atoi(name)
		if err != nil || i < 0 || i >= len(t) {
			return nil
		}
		return t[i]
	case []string:
		i, err := strconv.Atoi(name)
		if err != nil || i < 0 || i >= len(t) {
			return nil
		}
		return t[i]
	}
	return nil
}

func (e *tEval) evalExpr(x *tExpr, block *tNode, isSub bool) interface{} {
	e.curNode = exprDesc(x)
	if x.head.kind == tePath {
		p := x.head.path
		if len(p.parts) == 1 && !p.data && !p.this && p.depth == 0 {
			name := p.parts[0]
			if h, ok := e.helpers[name]; ok {
				e.curNode = nodeDesc(x.head)
				e.curNode = exprDesc(x)
				params := make([]interface{}, len(x.params))
				for i, pp := range x.params {
					params[i] = e.evalParam(pp)
				}
				hash := map[string]interface{}{}
				for _, hh := range x.hash {
					hash[hh.key] = e.evalParam(hh.value)
				}
				return e.callHelper(name, h, params, hash, x, block, isSub)
			}
		}
		// evaluate params anyway (side effects / errors)
		for _, pp := range x.params {
			e.evalParam(pp)
		}
		e.curNode = exprDesc(x)
		return e.resolvePath(p)
	}
	if len(x.params) == 0 {
		// literal mustache: raymond treats it as a helper lookup by name; not found -> empty
		return nil
	}
	return nil
}

func (e *tEval) callHelper(name string, h *helperDef, params []interface{}, hash map[string]interface{}, x *tExpr, block *tNode, isSub bool) interface{} {
	numIn := len(h.params)
	addOpts := false
	if numIn == len(params)+1 && h.params[numIn-1] == htOpts {
		addOpts = true
	}
	if !addOpts && len(params) != numIn {
		e.errorf("Helper '%s' called with wrong number of arguments, needed %d but got %d", name, numIn, len(params))
	}
	args := make([]interface{}, 0, numIn)
	for i, p := range params {
		t := h.params[i]
		conv, ok := convertArg(p, t)
		if !ok {
			if p == nil {
				return ""
			}
			e.errorf("Helper %s called with argument %d with type %s but it should be %s", name, i, goTypeName(p), hTypeName(t))
		}
		args = append(args, conv)
	}
	opts := &helperOpts{ev: e, block: block, ctx: e.curFrame().ctx, hash: hash, isBlock: block != nil}
	if addOpts {
		args = append(args, opts)
	}
	return h.fn(args, opts)
}

func hTypeName(t hType) string {
	switch t {
	case htString:
		return "string"
	case htInt:
		return "int"
	case htBool:
		return "bool"
	case htStringSlice:
		return "[]string"
	case htTime:
		return "time.Time"
	}
	return "interface {}"
}

func goTypeName(v interface{}) string {
	if v == nil {
		return "<nil>"
	}
	switch v.(type) {
	case []interface{}:
		return "[]interface {}"
	case map[string]interface{}:
		return "map[string]interface {}"
	case *OrderedMap:
		return "map[string]interface {}"
	}
	return reflect.TypeOf(v).String()
}

func convertArg(v interface{}, t hType) (interface{}, bool) {
	switch t {
	case htAny, htOpts:
		return v, true
	case htString:
		if v == nil {
			return "", true
		}
		if s, ok := v.(string); ok {
			return s, true
		}
		return tStr(v), true
	case htBool:
		return tTruthy(v), true
	case htInt:
		switch n := v.(type) {
		case int:
			return n, true
		case int64:
			return int(n), true
		}
		return nil, false
	case htStringSlice:
		if v == nil {
			return []string(nil), true
		}
		if s, ok := v.([]string); ok {
			return s, true
		}
		return nil, false
	case htTime:
		if tm, ok := v.(time.Time); ok {
			return tm, true
		}
		return nil, false
	}
	return v, true
}

func tTruthy(v interface{}) bool {
	switch t := v.(type) {
	case nil:
		return false
	case string:
		return t != ""
	case bool:
		return t
	case int:
		return t != 0
	case int64:
		return t != 0
	case uint64:
		return t != 0
	case float64:
		return t != 0
	case []interface{}:
		return len(t) > 0
	case []string:
		return len(t) > 0
	case map[string]interface{}:
		return len(t) > 0
	case map[string]string:
		return len(t) > 0
	case *OrderedMap:
		return len(t.Keys) > 0
	case time.Time:
		return true
	}
	return true
}

func tStr(v interface{}) string {
	switch t := v.(type) {
	case nil:
		return ""
	case string:
		return t
	case bool:
		if t {
			return "true"
		}
		return "false"
	case int:
		return strconv.Itoa(t)
	case int64:
		return strconv.FormatInt(t, 10)
	case uint64:
		return strconv.FormatUint(t, 10)
	case float64:
		return strconv.FormatFloat(t, 'f', -1, 64)
	case []string:
		return strings.Join(t, "")
	case []interface{}:
		var b strings.Builder
		for _, x := range t {
			b.WriteString(tStr(x))
		}
		return b.String()
	case *OrderedMap:
		return fmt.Sprintf("%s", toJSONValue(t))
	case *helperOpts:
		return ""
	}
	return fmt.Sprintf("%s", v)
}

func sortedKeys(v interface{}) []string {
	var keys []string
	switch t := v.(type) {
	case map[string]interface{}:
		for k := range t {
			keys = append(keys, k)
		}
	case map[string]string:
		for k := range t {
			keys = append(keys, k)
		}
	case *OrderedMap:
		keys = append(keys, t.Keys...)
	}
	sort.Strings(keys)
	return keys
}

func (e *tEval) evalBlock(n *tNode) string {
	e.blocks = append(e.blocks, n)
	defer func() { e.blocks = e.blocks[:len(e.blocks)-1] }()
	x := n.expr
	if x.head.kind == tePath {
		p := x.head.path
		if len(p.parts) == 1 && !p.data && !p.this && p.depth == 0 {
			if h, ok := e.helpers[p.parts[0]]; ok {
				params := make([]interface{}, len(x.params))
				for i, pp := range x.params {
					params[i] = e.evalParam(pp)
				}
				hash := map[string]interface{}{}
				for _, hh := range x.hash {
					hash[hh.key] = e.evalParam(hh.value)
				}
				e.curNode = exprDesc(x)
				if len(params) > 0 {
					e.curNode = nodeDesc(x.params[len(x.params)-1])
				}
				res := e.callHelper(p.parts[0], h, params, hash, x, n, false)
				return tStr(res)
			}
		}
	}
	v := e.evalParam(x.head)
	ctx := e.curFrame().ctx
	if n.inverted {
		if !tTruthy(v) {
			return e.renderProgram(n.inverse, ctx, nil, nil)
		}
		return e.renderProgram(n.program, ctx, nil, nil)
	}
	if !tTruthy(v) {
		return e.renderProgram(n.inverse, ctx, nil, nil)
	}
	switch t := v.(type) {
	case []interface{}:
		var b strings.Builder
		for i, item := range t {
			b.WriteString(e.renderProgram(n.program, item, map[string]interface{}{"index": i, "first": i == 0, "last": i == len(t)-1}, nil))
		}
		return b.String()
	case []string:
		var b strings.Builder
		for i, item := range t {
			b.WriteString(e.renderProgram(n.program, item, map[string]interface{}{"index": i, "first": i == 0, "last": i == len(t)-1}, nil))
		}
		return b.String()
	}
	return e.renderProgram(n.program, v, nil, nil)
}

func baseHelpers() map[string]*helperDef {
	h := map[string]*helperDef{}
	h["if"] = &helperDef{params: []hType{htAny, htOpts}, fn: func(a []interface{}, o *helperOpts) interface{} {
		if tTruthy(a[0]) {
			return o.Fn()
		}
		return o.Inverse()
	}}
	h["unless"] = &helperDef{params: []hType{htAny, htOpts}, fn: func(a []interface{}, o *helperOpts) interface{} {
		if !tTruthy(a[0]) {
			return o.Fn()
		}
		return o.Inverse()
	}}
	h["with"] = &helperDef{params: []hType{htAny, htOpts}, fn: func(a []interface{}, o *helperOpts) interface{} {
		if !tTruthy(a[0]) {
			return o.Inverse()
		}
		var bp map[string]interface{}
		if o.block != nil && len(o.block.blockParams) > 0 {
			bp = map[string]interface{}{o.block.blockParams[0]: a[0]}
		}
		return o.FnWith(a[0], nil, bp)
	}}
	h["each"] = &helperDef{params: []hType{htAny, htOpts}, fn: func(a []interface{}, o *helperOpts) interface{} {
		v := a[0]
		if !tTruthy(v) {
			return o.Inverse()
		}
		var b strings.Builder
		bpNames := []string{}
		if o.block != nil {
			bpNames = o.block.blockParams
		}
		mk := func(item interface{}, key interface{}) map[string]interface{} {
			if len(bpNames) == 0 {
				return nil
			}
			m := map[string]interface{}{bpNames[0]: item}
			if len(bpNames) > 1 {
				m[bpNames[1]] = key
			}
			return m
		}
		switch t := v.(type) {
		case []interface{}:
			for i, item := range t {
				b.WriteString(o.FnWith(item, map[string]interface{}{"index": i, "first": i == 0, "last": i == len(t)-1}, mk(item, i)))
			}
		case []string:
			for i, item := range t {
				b.WriteString(o.FnWith(item, map[string]interface{}{"index": i, "first": i == 0, "last": i == len(t)-1}, mk(item, i)))
			}
		case map[string]interface{}, map[string]string, *OrderedMap:
			keys := sortedKeys(t)
			for i, k := range keys {
				item := lookupField(t, k)
				b.WriteString(o.FnWith(item, map[string]interface{}{"key": k, "index": i, "first": i == 0, "last": i == len(keys)-1}, mk(item, k)))
			}
		default:
			return o.FnWith(v, nil, nil)
		}
		return b.String()
	}}
	h["lookup"] = &helperDef{params: []hType{htAny, htString, htOpts}, fn: func(a []interface{}, o *helperOpts) interface{} {
		return lookupField(a[0], a[1].(string))
	}}
	h["log"] = &helperDef{params: []hType{htString}, fn: func(a []interface{}, o *helperOpts) interface{} {
		log.Print(a[0].(string))
		return ""
	}}
	h["equal"] = &helperDef{params: []hType{htAny, htAny, htOpts}, fn: func(a []interface{}, o *helperOpts) interface{} {
		if tStr(a[0]) == tStr(a[1]) {
			if o.block == nil && len(o.ev.blocks) > 0 {
				top := o.ev.blocks[len(o.ev.blocks)-1]
				return o.ev.renderProgram(top.program, o.ctx, nil, nil)
			}
			return o.Fn()
		}
		return ""
	}}
	return h
}
