//go:embed slugtable.txt
var slugTableData string

var slugTable map[rune]string
var slugOnce sync.Once

func loadSlugTable() {
	slugTable = make(map[rune]string, 50000)
	for _, line := range strings.Split(slugTableData, "\n") {
		if line == "" {
			continue
		}
		sp := strings.IndexByte(line, ' ')
		if sp < 0 {
			continue
		}
		r, err := strconv.ParseInt(line[:sp], 16, 32)
		if err != nil {
			continue
		}
		slugTable[rune(r)] = line[sp+1:]
	}
}

