		case r == '&':
			b.WriteString("and")
		case r == '@':
			b.WriteString("at")
		case r == '\'' || r == '"':
		case r < 0x80:
			c := byte(r)
			if (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '-' || c == '_' {
				b.WriteByte(c)
			} else if c >= 'A' && c <= 'Z' {
				b.WriteByte(c + 32)
			} else {
				b.WriteByte('-')
			}
		default:
			b.WriteString(slugTable[r])
		}
	}
	out := reMultiDash.ReplaceAllString(b.String(), "-")
	return strings.Trim(out, "-_")
}
