package main

import (
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

type Notebook struct {
	Path    string
	Config  *Config
	index   *Index
	indexed bool
}

type App struct {
	WorkDir      string
	NotebookDir  string
	notebook     *Notebook
	notebookErr  error
	NoInput      bool
	stdoutTTY    bool
	stdinTTY     bool
	styler       *Styler
}

func warnf(format string, args ...interface{}) {
	fmt.Fprintf(os.Stderr, "zk: warning: "+format+"\n", args...)
}

func lstatWarn(p string) bool {
	if _, err := os.Lstat(p); err != nil {
		var pe *os.PathError
		if errors.As(err, &pe) {
			warnf("lstat %s: %v", p, pe.Err)
		} else {
			warnf("%v", err)
		}
		return false
	}
	return true
}

func findNotebookRoot(dir string) (string, bool) {
	d := dir
	for {
		info, err := os.Stat(filepath.Join(d, ".zk"))
		if err == nil && info.IsDir() {
			return d, true
		}
		parent := filepath.Dir(d)
		if parent == d {
			return "", false
		}
		d = parent
	}
}

func absPath(p, base string) string {
	if p == "" {
		return base
	}
	if strings.HasPrefix(p, "~/") || p == "~" {
		if home, err := os.UserHomeDir(); err == nil {
			p = filepath.Join(home, strings.TrimPrefix(p, "~"))
		}
	}
	if !filepath.IsAbs(p) {
		p = filepath.Join(base, p)
	}
	return filepath.Clean(p)
}

type searchCandidate struct {
	nb string
	wd string
}

// resolveNotebook performs notebook discovery.
func (a *App) resolveNotebook(notebookFlag string, wdFlag bool) {
	cwd := a.WorkDir
	var cands []searchCandidate
	if notebookFlag != "" {
		cands = []searchCandidate{{nb: notebookFlag, wd: cwd}}
	} else {
		cands = []searchCandidate{{nb: cwd, wd: cwd}}
		if env := os.Getenv("ZK_NOTEBOOK_DIR"); env != "" {
			envAbs := absPath(env, cwd)
			wd := envAbs
			if wdFlag {
				wd = cwd
			}
			cands = append(cands, searchCandidate{nb: envAbs, wd: wd})
		}
	}
	var lastDir string
	for _, c := range cands {
		lastDir = c.nb
		nbOK := lstatWarn(c.nb)
		wdOK := true
		if c.wd != c.nb || !nbOK {
			wdOK = lstatWarn(c.wd)
		} else {
			wdOK = nbOK
		}
		if !nbOK {
			lstatWarn(c.nb)
			continue
		}
		root, ok := findNotebookRoot(c.nb)
		if !ok {
			continue
		}
		if !wdOK {
			lstatWarn(c.wd)
		}
		cfg, err := loadConfig(filepath.Join(root, ".zk", "config.toml"))
		if err != nil {
			a.notebookErr = err
			return
		}
		a.notebook = &Notebook{Path: root, Config: cfg}
		return
	}
	a.notebookErr = fmt.Errorf("failed to open notebook: no notebook found in %s or a parent directory", lastDir)
}

func (a *App) requireNotebook() (*Notebook, error) {
	if a.notebook == nil {
		if a.notebookErr != nil {
			return nil, a.notebookErr
		}
		return nil, fmt.Errorf("failed to open notebook: no notebook found")
	}
	return a.notebook, nil
}

func (nb *Notebook) Index() (*Index, error) {
	if nb.index == nil {
		ix, err := openIndex(filepath.Join(nb.Path, ".zk", "notebook.db"))
		if err != nil {
			return nil, err
		}
		nb.index = ix
	}
	return nb.index, nil
}

// RelPath returns the path relative to the notebook root.
func (nb *Notebook) RelPath(abs string) (string, error) {
	rel, err := filepath.Rel(nb.Path, abs)
	if err != nil {
		return "", err
	}
	if rel == ".." || strings.HasPrefix(rel, "../") {
		return "", fmt.Errorf("%s: path is outside the notebook at %s", abs, nb.Path)
	}
	if rel == "." {
		rel = ""
	}
	return rel, nil
}

