func renderInitConfig(wiki, hashtags, colon, multiword bool) string {
	s := defaultConfigTemplate
	lf := "#link-format = \"wiki\""
	if wiki {
		lf = "link-format = \"wiki\""
	}
	b := func(v bool) string {
		if v {
			return "true"
		}
		return "false"
	}
	s = strings.Replace(s, "{{LINK_FORMAT}}", lf, 1)
	s = strings.Replace(s, "{{HASHTAGS}}", b(hashtags), 1)
	s = strings.Replace(s, "{{COLONTAGS}}", b(colon), 1)
	s = strings.Replace(s, "{{MULTIWORD}}", b(multiword), 1)
	return s
}
