			wdOK = lstatWarn(c.wd)
		} else {
			wdOK = nbOK
		}
		if !nbOK {
			lstatWarn(c.nb)
			continue
		}
		root, ok := findNotebookRoot(c.nb)
		if !ok {
			continue
		}
		if !wdOK {
			lstatWarn(c.wd)
		}
		cfg, err := loadConfig(filepath.Join(root, ".zk", "config.toml"))
		if err != nil {
			a.notebookErr = err
			return
		}
		a.notebook = &Notebook{Path: root, Config: cfg}
		return
	}
	a.notebookErr = fmt.Errorf("failed to open notebook: no notebook found in %s or a parent directory", lastDir)
}

func (a *App) requireNotebook() (*Notebook, error) {
	if a.notebook == nil {
		if a.notebookErr != nil {
			return nil, a.notebookErr
		}
		return nil, fmt.Errorf("failed to open notebook: no notebook found")
	}
	return a.notebook, nil
}

func (nb *Notebook) Index() (*Index, error) {
	if nb.index == nil {
		ix, err := openIndex(filepath.Join(nb.Path, ".zk", "notebook.db"))
		if err != nil {
			return nil, err
		}
		nb.index = ix
	}
	return nb.index, nil
}

// RelPath returns the path relative to the notebook root.
func (nb *Notebook) RelPath(abs string) (string, error) {
	rel, err := filepath.Rel(nb.Path, abs)
	if err != nil {
		return "", err
	}
	if rel == ".." || strings.HasPrefix(rel, "../") {
		return "", fmt.Errorf("%s: path is outside the notebook at %s", abs, nb.Path)
	}
	if rel == "." {
		rel = ""
	}
	return rel, nil
}

