}

func (nb *Notebook) groupConfigForDir(relDir string) GroupConfig {
	if name, ok := nb.Config.groupNameForPath(relDir); ok {
		return nb.Config.Groups[name]
	}
	return nb.Config.rootGroup()
}

func (nb *Notebook) walkNotes() ([]noteFile, []ignoredFile) {
	var files []noteFile
	var ignored []ignoredFile
	var walk func(absDir, relDir string)
	walk = func(absDir, relDir string) {
		entries, err := os.ReadDir(absDir)
		if err != nil {
			return
		}
		for _, e := range entries {
			name := e.Name()
			if strings.HasPrefix(name, ".") {
				continue
			}
			abs := filepath.Join(absDir, name)
			rel := name
			if relDir != "" {
				rel = relDir + "/" + name
			}
			info, err := os.Stat(abs)
			if err != nil {
				continue
			}
			if info.IsDir() {
				walk(abs, rel)
				continue
			}
			g := nb.groupConfigForDir(relDir)
			ext := g.Note.Extension
			if filepath.Ext(name) != "."+ext {
				ignored = append(ignored, ignoredFile{rel, fmt.Sprintf("expected extension %q", ext)})
				continue
			}
			excludedBy := ""
			for _, glob := range g.Note.Exclude {
				if m, err := filepath.Match(glob, rel); err == nil && m {
					excludedBy = glob
					break
				}
			}
			if excludedBy != "" {
				ignored = append(ignored, ignoredFile{rel, fmt.Sprintf("matched exclude glob %q", excludedBy)})
				continue
			}
			files = append(files, noteFile{rel: rel, abs: abs, mtime: info.ModTime()})
		}
	}
	walk(nb.Path, "")
	sort.SliceStable(files, func(i, j int) bool { return sortablePath(files[i].rel) < sortablePath(files[j].rel) })
	sort.SliceStable(ignored, func(i, j int) bool { return ignored[i].rel < ignored[j].rel })
	return files, ignored
}

type indexStats struct {
	sources  int
	added    int
	modified int
	removed  int
	duration time.Duration
}

func pluralNote(n int) string {
	if n > 1 {
		return "notes"
	}
	return "note"
}

func (nb *Notebook) mdOptions() *mdOptions {
	md := nb.Config.Markdown
	return &mdOptions{hashtags: md.Hashtags, colonTags: md.ColonTags, multiword: md.MultiwordTags && md.Hashtags}
}

// Sync indexes the notebook.
func (nb *Notebook) Sync(force bool, verbose io.Writer) (*indexStats, error) {
	start := time.Now()
	ix, err := nb.Index()
	if err != nil {
		return nil, err
	}
	files, ignored := nb.walkNotes()
	indexed, err := ix.indexedPaths()
	if err != nil {
		return nil, err
	}
	stats := &indexStats{sources: len(files)}
	if err := ix.db.ExecScript("BEGIN"); err != nil {
		return nil, err
	}
	i, j := 0, 0
	for i < len(files) || j < len(indexed) {
		var f *noteFile
		var e *indexedEntry
		if i < len(files) && j < len(indexed) {
			a, b := sortablePath(files[i].rel), sortablePath(indexed[j].Path)
			if a == b {
				f, e = &files[i], &indexed[j]
				i++
				j++
			} else if a < b {
				f = &files[i]
				i++
			} else {
				e = &indexed[j]
				j++
			}
		} else if i < len(files) {
			f = &files[i]
			i++
		} else {
			e = &indexed[j]
			j++
		}
		switch {
		case f != nil && e == nil:
			if verbose != nil {
				fmt.Fprintf(verbose, "- added %s\n", f.rel)
			}
			if err := nb.addNote(ix, f); err == nil {
				stats.added++
			}
		case f == nil && e != nil:
			if verbose != nil {
				fmt.Fprintf(verbose, "- removed %s\n", e.Path)
			}
			ix.db.Exec("DELETE FROM notes WHERE id = ?", e.ID)
			stats.removed++
		default:
			modified := formatDBTime(f.mtime) != e.Modified
			if !modified {
				// compare parsed times
				if parseDBTime(e.Modified).Equal(f.mtime) {
					modified = false
				} else {
					modified = true
				}
			}
			if force || modified {
				if verbose != nil {
					fmt.Fprintf(verbose, "- modified %s\n", f.rel)
				}
				if err := nb.updateNote(ix, e.ID, f); err == nil {
					stats.modified++
				}
			} else if verbose != nil {
				fmt.Fprintf(verbose, "- unchanged %s\n", f.rel)
			}
		}
	}
	if err := ix.db.ExecScript("COMMIT"); err != nil {
		return nil, err
	}
	if verbose != nil {
		for _, ig := range ignored {
			fmt.Fprintf(verbose, "- ignored %s: %s\n", ig.rel, ig.reason)
		}
	}
	stats.duration = time.Since(start)
	return stats, nil
}

type noteData struct {
	parsed   *ParsedNote
	raw      string
	checksum string
	metaJSON string
	created  time.Time
	hasDate  bool
	filename string
}

func (nb *Notebook) readNote(f *noteFile) (*noteData, error) {
	b, err := os.ReadFile(f.abs)
	if err != nil {
		warnf("%s: %v", f.abs, err)
		return nil, err
	}
	content := string(b)
	parsed, err := parseNote(content, nb.mdOptions())
	if err != nil {
		warnf("%s: %v", f.abs, err)
		return nil, err
	}
	sum := sha256.Sum256(b)
	nd := &noteData{parsed: parsed, raw: content, checksum: hex.EncodeToString(sum[:]), filename: filepath.Base(f.rel)}
	mj, err := metadataJSON(parsed.Metadata)
	if err != nil {
		warnf("cannot serialize note metadata to JSON: %s: %v", f.rel, err)
		mj = "{}"
	}
	nd.metaJSON = mj
	if v, ok := parsed.Metadata.Values["date"]; ok {
		if t, ok := parseFrontmatterDate(v); ok {
			nd.created = t
			nd.hasDate = true
		}
	}
	return nd, nil
}

func (nb *Notebook) addNote(ix *Index, f *noteFile) error {
	nd, err := nb.readNote(f)
	if err != nil {
		return err
	}
	created := time.Now()
	if nd.hasDate {
		created = nd.created
	}
	p := nd.parsed
	err = ix.db.Exec(`INSERT INTO notes (path, sortable_path, title, lead, body, raw_content, word_count, checksum, created, modified, metadata, filename) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
		f.rel, sortablePath(f.rel), p.Title, p.Lead, p.Body, nd.raw, p.WordCount, nd.checksum, formatDBTime(created), formatDBTime(f.mtime), nd.metaJSON, nd.filename)
	if err != nil {
		return err
	}
	id := ix.db.LastInsertID()
	nb.associateTags(ix, id, p.Tags)
	nb.addLinks(ix, id, f, p.Links)
	nb.stealLinks(ix, id, f.rel)
	return nil
}

func (nb *Notebook) updateNote(ix *Index, id int64, f *noteFile) error {
	nd, err := nb.readNote(f)
	if err != nil {
		return err
	}
	p := nd.parsed
	err = ix.db.Exec(`UPDATE notes SET title = ?, lead = ?, body = ?, raw_content = ?, word_count = ?, checksum = ?, modified = ?, metadata = ?, filename = ? WHERE id = ?`,
		p.Title, p.Lead, p.Body, nd.raw, p.WordCount, nd.checksum, formatDBTime(f.mtime), nd.metaJSON, nd.filename, id)
	if err != nil {
		return err
	}
	ix.db.Exec("DELETE FROM notes_collections WHERE note_id = ?", id)
	nb.associateTags(ix, id, p.Tags)
	ix.db.Exec("DELETE FROM links WHERE source_id = ?", id)
	nb.addLinks(ix, id, f, p.Links)
	return nil
}

func (nb *Notebook) associateTags(ix *Index, id int64, tags []string) {
	for _, t := range tags {
		var cid int64 = -1
		ix.db.Query("SELECT id FROM collections WHERE kind = 'tag' AND name = ?", []interface{}{t}, func(s *Stmt) error {
			cid = s.Int(0)
			return nil
		})
		if cid < 0 {
			if err := ix.db.Exec("INSERT INTO collections (kind, name) VALUES ('tag', ?)", t); err != nil {
				continue
			}
			cid = ix.db.LastInsertID()
		}
		ix.db.Exec("INSERT INTO notes_collections (note_id, collection_id) VALUES (?, ?)", id, cid)
	}
}

func isExternalURL(href string) bool {
	u, err := url.Parse(href)
	if err != nil {
		return false
	}
	return u.Scheme != "" && u.Host != ""
}

func lowerASCII(s string) string {
	b := []byte(s)
	for i, c := range b {
		if c >= 'A' && c <= 'Z' {
			b[i] = c + 32
		}
	}
	return string(b)
}

func hrefPathPart(href string) string {
	if i := strings.IndexByte(href, '#'); i >= 0 {
		href = href[:i]
	}
	return href
}

func cleanHref(h string) string {
	if h == "" {
		return ""
	}
	c := path.Clean(h)
	if c == "." {
		return ""
	}
	return c
}

func hrefMatchesExact(h, p string) bool {
	h = lowerASCII(h)
	p = lowerASCII(p)
	if strings.HasPrefix(p, h) && !strings.Contains(p[len(h):], "/") {
		return true
	}
	return strings.HasPrefix(p, h+"/")
}

func hrefMatchesPartial(h, p string) bool {
	return strings.Contains(lowerASCII(p), lowerASCII(h))
}

type pathEntry struct {
	id   int64
	path string
}

func (ix *Index) allPaths() []pathEntry {
	var out []pathEntry
	ix.db.Query("SELECT id, path FROM notes ORDER BY id", nil, func(s *Stmt) error {
		out = append(out, pathEntry{s.Int(0), s.Text(1)})
		return nil
	})
	return out
}

func bestMatch(paths []pathEntry, h string, partial bool) int64 {
	var best *pathEntry
	for i := range paths {
		pe := &paths[i]
		ok := false
		if partial {
			ok = hrefMatchesPartial(h, pe.path)
		} else {
			ok = hrefMatchesExact(h, pe.path)
		}
		if !ok {
			continue
		}
		if best == nil || len(pe.path) < len(best.path) {
			best = pe
		}
	}
	if best == nil {
		return 0
	}
	return best.id
}

func resolveHref(paths []pathEntry, href string, allowPartial bool, selfID int64) int64 {
	if strings.HasPrefix(href, "#") {
		return selfID
	}
	h := cleanHref(hrefPathPart(href))
	if h == "" {
		return 0
	}
	if id := bestMatch(paths, h, false); id != 0 {
		return id
	}
	if allowPartial {
		return bestMatch(paths, h, true)
	}
	return 0
}

func (nb *Notebook) addLinks(ix *Index, id int64, f *noteFile, links []ParsedLink) {
	paths := ix.allPaths()
	for _, l := range links {
		href := l.Href
		external := isExternalURL(href)
		if !external && l.Type != "wiki-link" && !strings.HasPrefix(href, "#") {
			if u, err := url.PathUnescape(href); err == nil {
				href = u
			}
			abs := filepath.Join(filepath.Dir(f.abs), href)
			rel, err := nb.RelPath(abs)
			if err != nil {
				warnf("%v", err)
				continue
			}
			href = rel
		}
		var target interface{}
		if !external {
			if tid := resolveHref(paths, href, l.Type == "wiki-link", id); tid != 0 {
				target = tid
			}
		}
		ix.db.Exec(`INSERT INTO links (source_id, target_id, title, href, external, rels, snippet, snippet_start, snippet_end, type) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
			id, target, l.Title, href, external, joinRels(l.Rels), l.Snippet, l.SnippetStart, l.SnippetEnd, l.Type)
	}
}

// stealLinks re-targets existing links matching the newly added note.
func (nb *Notebook) stealLinks(ix *Index, id int64, notePath string) {
	type lk struct {
		id     int64
		href   string
		typ    string
		target string
		hasT   bool
	}
	var links []lk
	ix.db.Query(`SELECT l.id, l.href, l.type, t.path FROM links l LEFT JOIN notes t ON t.id = l.target_id WHERE l.external = 0`, nil, func(s *Stmt) error {
		links = append(links, lk{id: s.Int(0), href: s.Text(1), typ: s.Text(2), target: s.Text(3), hasT: !s.IsNull(3)})
		return nil
	})
	for _, l := range links {
		if strings.HasPrefix(l.href, "#") {
			continue
		}
		h := cleanHref(hrefPathPart(l.href))
		if h == "" {
			continue
		}
		match := hrefMatchesExact(h, notePath)
		if !match && l.typ == "wiki-link" {
			match = hrefMatchesPartial(h, notePath)
		}
		if !match {
			continue
		}
		if l.hasT && len(notePath) > len(l.target) {
			continue
		}
		ix.db.Exec("UPDATE links SET target_id = ? WHERE id = ?", id, l.id)
	}
}

func parseFrontmatterDate(v interface{}) (time.Time, bool) {
	s, ok := v.(string)
	if !ok {
		return time.Time{}, false
	}
	s = strings.TrimSpace(s)
	layouts := []string{
		time.RFC3339Nano,
		"2006-01-02T15:04:05.999999999Z0700",
		"2006-01-02T15:04:05.999999999",
		"2006-01-02T15:04",
		"2006-01-02 15:04:05.999999999",
		"2006-01-02 15:04",
		"2006-1-2",
	}
	for _, l := range layouts {
		if t, err := time.ParseInLocation(l, s, time.UTC); err == nil {
			return t, true
		}
	}
	return time.Time{}, false
}
