// globMatch implements SQLite GLOB semantics.
func globMatch(pattern, s string) bool {
	pr := []rune(pattern)
	sr := []rune(s)
	var match func(pi, si int) bool
	match = func(pi, si int) bool {
		for pi < len(pr) {
			c := pr[pi]
			switch c {
			case '*':
				for pi < len(pr) && pr[pi] == '*' {
					pi++
				}
				if pi == len(pr) {
					return true
				}
				for k := si; k <= len(sr); k++ {
					if match(pi, k) {
						return true
					}
				}
				return false
			case '?':
				if si >= len(sr) {
					return false
				}
				pi++
				si++
			case '[':
				if si >= len(sr) {
					return false
				}
				end := pi + 1
				invert := false
				if end < len(pr) && pr[end] == '^' {
					invert = true
					end++
				}
				matched := false
				first := true
				for end < len(pr) && (pr[end] != ']' || first) {
					first = false
					lo := pr[end]
					hi := lo
					if end+2 < len(pr) && pr[end+1] == '-' && pr[end+2] != ']' {
						hi = pr[end+2]
						end += 2
					}
					if sr[si] >= lo && sr[si] <= hi {
						matched = true
					}
					end++
				}
				if end >= len(pr) {
					return false
				}
				if matched == invert {
					return false
				}
				pi = end + 1
				si++
			default:
				if si >= len(sr) || sr[si] != c {
					return false
				}
				pi++
				si++
			}
		}
		return si == len(sr)
	}
	return match(0, 0)
}

