	Ascending bool
}

type LinkFilter struct {
	Hrefs       []string
	Negate      bool
	Recursive   bool
	MaxDistance int
}

type FindOpts struct {
	Match         []string
	MatchStrategy string
	IncludeHrefs  []string
	ExcludeHrefs  []string
	Tags          []string
	Mention       []string
	MentionedBy   []string
	LinkTo        *LinkFilter
	LinkedBy      *LinkFilter
	Related       []string
	Orphan        bool
	Tagless       bool
	MissingBacklink bool
	CreatedStart  *time.Time
	CreatedEnd    *time.Time
	ModifiedStart *time.Time
	ModifiedEnd   *time.Time
	Sorters       []Sorter
	Limit         int
}

type noteResult struct {
	note     *Note
	rank     float64
	distance int
	snippets []string
	hasSnip  bool
}

func (ix *Index) loadNotes() ([]*Note, error) {
	var notes []*Note
	byID := map[int64]*Note{}
	err := ix.db.Query(`SELECT id, path, title, lead, body, raw_content, word_count, checksum, created, modified, metadata, filename FROM notes ORDER BY id`, nil, func(s *Stmt) error {
		n := &Note{
			ID: s.Int(0), Path: s.Text(1), Title: s.Text(2), Lead: s.Text(3), Body: s.Text(4), Raw: s.Text(5),
			WordCount: int(s.Int(6)), Checksum: s.Text(7), Created: parseDBTime(s.Text(8)), Modified: parseDBTime(s.Text(9)),
			MetaJSON: s.Text(10), Filename: s.Text(11),
		}
		n.Tags = []string{}
		notes = append(notes, n)
		byID[n.ID] = n
		return nil
	})
	if err != nil {
		return nil, err
	}
	ix.db.Query(`SELECT nc.note_id, c.name FROM notes_collections nc JOIN collections c ON c.id = nc.collection_id AND c.kind = 'tag' ORDER BY nc.id`, nil, func(s *Stmt) error {
		if n, ok := byID[s.Int(0)]; ok {
			n.Tags = append(n.Tags, s.Text(1))
		}
		return nil
	})
	for _, n := range notes {
		var m map[string]interface{}
		if err := json.Unmarshal([]byte(n.MetaJSON), &m); err != nil || m == nil {
			m = map[string]interface{}{}
		}
		n.Metadata = m
	}
	return notes, nil
}

func (ix *Index) loadLinks() []*Link {
	var out []*Link
	ix.db.Query(`SELECT l.id, l.source_id, IFNULL(l.target_id, 0), l.title, l.href, l.external, l.rels, l.snippet, l.snippet_start, l.snippet_end, l.type, IFNULL(s.path, ''), IFNULL(t.path, '') FROM links l LEFT JOIN notes s ON s.id = l.source_id LEFT JOIN notes t ON t.id = l.target_id ORDER BY l.id`, nil, func(s *Stmt) error {
		out = append(out, &Link{
			ID: s.Int(0), SourceID: s.Int(1), TargetID: s.Int(2), Title: s.Text(3), Href: s.Text(4), External: s.Int(5) != 0,
			Rels: splitRels(s.Text(6)), Snippet: s.Text(7), SnippetStart: int(s.Int(8)), SnippetEnd: int(s.Int(9)), Type: s.Text(10),
			SourcePath: s.Text(11), TargetPath: s.Text(12),
		})
		return nil
	})
	return out
}

// pathMatches implements the path prefix matching used for path filters.
func pathMatches(prefix, p string) bool {
	return hrefMatchesExact(prefix, p)
}

func idsForHrefs(notes []*Note, hrefs []string) []int64 {
	var ids []int64
	for _, n := range notes {
		for _, h := range hrefs {
			if pathMatches(h, n.Path) {
				ids = append(ids, n.ID)
				break
			}
		}
	}
	return ids
}

// globMatch implements SQLite GLOB semantics.
func globMatch(pattern, s string) bool {
	pr := []rune(pattern)
	sr := []rune(s)
	var match func(pi, si int) bool
	match = func(pi, si int) bool {
		for pi < len(pr) {
			c := pr[pi]
			switch c {
			case '*':
				for pi < len(pr) && pr[pi] == '*' {
					pi++
				}
				if pi == len(pr) {
					return true
				}
				for k := si; k <= len(sr); k++ {
					if match(pi, k) {
						return true
					}
				}
				return false
			case '?':
				if si >= len(sr) {
					return false
				}
				pi++
				si++
			case '[':
				if si >= len(sr) {
					return false
				}
				end := pi + 1
				invert := false
				if end < len(pr) && pr[end] == '^' {
					invert = true
					end++
				}
				matched := false
				first := true
				for end < len(pr) && (pr[end] != ']' || first) {
					first = false
					lo := pr[end]
					hi := lo
					if end+2 < len(pr) && pr[end+1] == '-' && pr[end+2] != ']' {
						hi = pr[end+2]
						end += 2
					}
					if sr[si] >= lo && sr[si] <= hi {
						matched = true
					}
					end++
				}
				if end >= len(pr) {
					return false
				}
				if matched == invert {
					return false
				}
				pi = end + 1
				si++
			default:
				if si >= len(sr) || sr[si] != c {
					return false
				}
				pi++
				si++
			}
		}
		return si == len(sr)
	}
	return match(0, 0)
}

var tagSeparatorRegex = regexp.MustCompile(`(\ OR\ )|\|`)

func escapeFTSPhrase(s string) string {
	return `"` + strings.ReplaceAll(s, `"`, `""`) + `"`
}

func mentionQuery(n *Note) string {
	var terms []string
	if n.Title != "" {
		terms = append(terms, escapeFTSPhrase(n.Title))
	}
	if al, ok := n.Metadata["aliases"]; ok {
		switch a := al.(type) {
		case []interface{}:
			for _, x := range a {
				if s, ok := x.(string); ok && s != "" {
					terms = append(terms, escapeFTSPhrase(s))
				}
			}
		case string:
			if a != "" {
				terms = append(terms, escapeFTSPhrase(a))
			}
		}
	}
	return strings.Join(terms, " OR ")
}

type ftsHit struct {
	rank    float64
	snippet string
}

func (ix *Index) ftsSearch(query string, restrict []int64) (map[int64]ftsHit, error) {
	hits := map[int64]ftsHit{}
	sql := `SELECT rowid, bm25(notes_fts, 1000.0, 500.0, 1.0), snippet(notes_fts, 2, '<zk:match>', '</zk:match>', '…', 20) FROM notes_fts WHERE notes_fts MATCH ?`
	err := ix.db.Query(sql, []interface{}{query}, func(s *Stmt) error {
		hits[s.Int(0)] = ftsHit{rank: s.Float(1), snippet: s.Text(2)}
		return nil
	})
	return hits, err
}

type distEntry struct {
	dist     int
	snippets []string
}

// transitive computes reachable notes from sources following links forward (or backward).
func transitive(links []*Link, sources map[int64]bool, forward bool, maxDistance int) map[int64]*distEntry {
	adj := map[int64][]*Link{}
	for _, l := range links {
		if l.TargetID == 0 {
			continue
		}
		if forward {
			adj[l.SourceID] = append(adj[l.SourceID], l)
		} else {
			adj[l.TargetID] = append(adj[l.TargetID], l)
		}
	}
	res := map[int64]*distEntry{}
	type state struct {
		node int64
		path map[int64]bool
		dist int
	}
	var frontier []state
	var srcIDs []int64
	for id := range sources {
		srcIDs = append(srcIDs, id)
	}
	sort.Slice(srcIDs, func(i, j int) bool { return srcIDs[i] < srcIDs[j] })
	for _, id := range srcIDs {
		frontier = append(frontier, state{node: id, path: map[int64]bool{id: true}, dist: 0})
	}
	for len(frontier) > 0 {
		var next []state
		for _, st := range frontier {
			if maxDistance > 0 && st.dist >= maxDistance {
				continue
			}
			for _, l := range adj[st.node] {
				other := l.TargetID
				if !forward {
					other = l.SourceID
				}
				if st.path[other] {
					continue
				}
				d := st.dist + 1
				e, ok := res[other]
				if !ok {
					e = &distEntry{dist: d}
					res[other] = e
				}
				if d < e.dist {
					e.dist = d
				}
				e.snippets = append(e.snippets, l.Snippet)
				np := map[int64]bool{}
				for k := range st.path {
					np[k] = true
				}
				np[other] = true
				next = append(next, state{node: other, path: np, dist: d})
			}
		}
		frontier = next
		if len(frontier) > 100000 {
			break
		}
	}
	return res
}

func highlightLinkSnippet(l *Link) string {
	if l.Title == "" {
		return l.Snippet
	}
	return strings.ReplaceAll(l.Snippet, l.Title, "<zk:match>"+l.Title+"</zk:match>")
}

func (nb *Notebook) Find(opts *FindOpts) ([]*noteResult, error) {
	ix, err := nb.Index()
	if err != nil {
		return nil, err
	}
	notes, err := ix.loadNotes()
	if err != nil {
		return nil, err
	}
	links := ix.loadLinks()
	byID := map[int64]*Note{}
	for _, n := range notes {
		byID[n.ID] = n
	}
	results := []*noteResult{}
	for _, n := range notes {
		results = append(results, &noteResult{note: n})
	}
	filter := func(keep func(r *noteResult) bool) {
		out := results[:0]
		for _, r := range results {
			if keep(r) {
				out = append(out, r)
			}
		}
		results = out
	}

	findIDs := func(hrefs []string) ([]int64, error) {
		ids := idsForHrefs(notes, hrefs)
		if len(ids) == 0 {
			return nil, fmt.Errorf("could not find notes at: %s", strings.Join(hrefs, ", "))
		}
		return ids, nil
	}

	if len(opts.IncludeHrefs) > 0 {
		filter(func(r *noteResult) bool {
			for _, h := range opts.IncludeHrefs {
				if pathMatches(h, r.note.Path) {
					return true
				}
			}
			return false
		})
	}
	if len(opts.ExcludeHrefs) > 0 {
		filter(func(r *noteResult) bool {
			for _, h := range opts.ExcludeHrefs {
				if pathMatches(h, r.note.Path) {
					return false
				}
			}
			return true
		})
	}

	// tags
	for _, tagsArg := range opts.Tags {
		parts := tagSeparatorRegex.Split(tagsArg, -1)
		negate := false
		var globs []string
		for _, t := range parts {
			t = strings.TrimSpace(t)
			if strings.HasPrefix(t, "-") {
				negate = true
				t = strings.TrimPrefix(t, "-")
			} else if strings.HasPrefix(t, "NOT") {
				negate = true
				t = strings.TrimPrefix(t, "NOT")
			}
			t = strings.TrimSpace(t)
			if t == "" {
				continue
			}
			globs = append(globs, t)
		}
		if len(globs) == 0 {
			continue
		}
		if negate && len(globs) > 1 {
			return nil, fmt.Errorf("cannot negate a tag in a OR group: %s", tagsArg)
		}
		filter(func(r *noteResult) bool {
			has := false
			for _, tag := range r.note.Tags {
				for _, g := range globs {
					if globMatch(g, tag) {
						has = true
					}
				}
			}
			if negate {
				return !has
			}
			return has
		})
	}

	// match
	if len(opts.Match) > 0 {
		switch opts.MatchStrategy {
		case "fts", "":
			var parts []string
			for _, m := range opts.Match {
				parts = append(parts, "("+convertFTSQuery(m)+")")
			}
			q := strings.Join(parts, " AND ")
			if len(opts.Match) == 1 {
				q = convertFTSQuery(opts.Match[0])
			}
			hits, err := ix.ftsSearch(q, nil)
			if err != nil {
				hits = map[int64]ftsHit{}
			}
			filter(func(r *noteResult) bool {
				h, ok := hits[r.note.ID]
				if !ok {
					return false
				}
				r.rank = h.rank
				r.snippets = []string{h.snippet}
				r.hasSnip = true
				return true
			})
		case "re":
			var res []*regexp.Regexp
			bad := false
			for _, m := range opts.Match {
				re, err := regexp.Compile(m)
				if err != nil {
					bad = true
					break
				}
				res = append(res, re)
			}
			filter(func(r *noteResult) bool {
				if bad {
					return false
				}
				for _, re := range res {
					if !re.MatchString(r.note.Raw) {
						return false
					}
				}
				return true
			})
		case "exact":
			filter(func(r *noteResult) bool {
				raw := lowerASCII(r.note.Raw)
				for _, m := range opts.Match {
					if !strings.Contains(raw, lowerASCII(m)) {
						return false
					}
				}
				return true
			})
		default:
			return nil, fmt.Errorf("%s: unknown match strategy\ntry fts (full-text search), re (regular expression) or exact", opts.MatchStrategy)
		}
	}

	// mention
	if len(opts.Mention) > 0 {
		ids, err := findIDs(opts.Mention)
		if err != nil {
			return nil, err
		}
		idset := map[int64]bool{}
		var terms []string
		for _, id := range ids {
			idset[id] = true
			if q := mentionQuery(byID[id]); q != "" {
				terms = append(terms, q)
			}
		}
		hits := map[int64]ftsHit{}
		if len(terms) > 0 {
			hits, _ = ix.ftsSearch(strings.Join(terms, " OR "), nil)
		}
		filter(func(r *noteResult) bool {
			if idset[r.note.ID] {
				return false
			}
			h, ok := hits[r.note.ID]
			if !ok {
				return false
			}
			r.snippets = []string{h.snippet}
			r.hasSnip = true
			return true
		})
	}
	if len(opts.MentionedBy) > 0 {
		ids, err := findIDs(opts.MentionedBy)
		if err != nil {
			return nil, err
		}
		idset := map[int64]bool{}
		for _, id := range ids {
			idset[id] = true
		}
		filter(func(r *noteResult) bool {
			if idset[r.note.ID] {
				return false
			}
			q := mentionQuery(r.note)
			if q == "" {
				return false
			}
			hits, err := ix.ftsSearch(q, nil)
			if err != nil {
				return false
			}
			var snips []string
			found := false
			for _, id := range ids {
				if h, ok := hits[id]; ok {
					found = true
					snips = append(snips, h.snippet)
				}
			}
			if !found {
				return false
			}
			r.snippets = snips
			r.hasSnip = true
			return true
		})
	}

	// link filters
	applyLinkFilter := func(f *LinkFilter, forward bool) error {
		ids, err := findIDs(f.Hrefs)
		if err != nil {
			return err
		}
		idset := map[int64]bool{}
		for _, id := range ids {
			idset[id] = true
		}
		if f.Negate {
			bad := map[int64]bool{}
			if f.Recursive {
				for id := range transitive(links, idset, !forward, f.MaxDistance) {
					bad[id] = true
				}
			} else {
				for _, l := range links {
					if l.TargetID == 0 {
						continue
					}
					if forward && idset[l.TargetID] {
						bad[l.SourceID] = true
					}
					if !forward && idset[l.SourceID] {
						bad[l.TargetID] = true
					}
				}
			}
			filter(func(r *noteResult) bool { return !bad[r.note.ID] })
			return nil
		}
		if f.Recursive {
			reach := transitive(links, idset, !forward, f.MaxDistance)
			filter(func(r *noteResult) bool {
				e, ok := reach[r.note.ID]
				if !ok {
					return false
				}
				r.distance = e.dist
				r.snippets = e.snippets
				r.hasSnip = true
				return true
			})
			return nil
		}
		snips := map[int64][]string{}
		for _, l := range links {
			if l.TargetID == 0 {
				continue
			}
			if forward && idset[l.TargetID] {
				snips[l.SourceID] = append(snips[l.SourceID], highlightLinkSnippet(l))
			}
			if !forward && idset[l.SourceID] {
				snips[l.TargetID] = append(snips[l.TargetID], highlightLinkSnippet(l))
			}
		}
		filter(func(r *noteResult) bool {
			s, ok := snips[r.note.ID]
			if !ok {
				return false
			}
			r.snippets = s
			r.hasSnip = true
			r.distance = 1
			return true
		})
		return nil
	}
	if opts.LinkedBy != nil {
		if err := applyLinkFilter(opts.LinkedBy, false); err != nil {
			return nil, err
		}
	}
	if opts.LinkTo != nil {
		if err := applyLinkFilter(opts.LinkTo, true); err != nil {
			return nil, err
		}
	}

	if len(opts.Related) > 0 {
		ids, err := findIDs(opts.Related)
		if err != nil {
			return nil, err
		}
		idset := map[int64]bool{}
		for _, id := range ids {
			idset[id] = true
		}
		fw := transitive(links, idset, true, 2)
		bw := transitive(links, idset, false, 2)
		minDist := map[int64]int{}
		for id, e := range fw {
			minDist[id] = e.dist
		}
		for id, e := range bw {
			if d, ok := minDist[id]; !ok || e.dist < d {
				minDist[id] = e.dist
			}
		}
		filter(func(r *noteResult) bool {
			if idset[r.note.ID] {
				return false
			}
			d, ok := minDist[r.note.ID]
			return ok && d == 2
		})
	}

	if opts.Orphan {
		linked := map[int64]bool{}
		for _, l := range links {
			if l.TargetID != 0 {
				linked[l.TargetID] = true
			}
		}
		filter(func(r *noteResult) bool { return !linked[r.note.ID] })
	}
	if opts.Tagless {
		filter(func(r *noteResult) bool { return len(r.note.Tags) == 0 })
	}
	if opts.MissingBacklink {
		targets := map[int64]map[int64]bool{}
		for _, l := range links {
			if l.TargetID == 0 {
				continue
			}
			if targets[l.SourceID] == nil {
				targets[l.SourceID] = map[int64]bool{}
			}
			targets[l.SourceID][l.TargetID] = true
		}
		missing := map[int64]bool{}
		for _, l := range links {
			if l.TargetID == 0 {
				continue
			}
			if !targets[l.TargetID][l.SourceID] {
				missing[l.TargetID] = true
			}
		}
		filter(func(r *noteResult) bool { return missing[r.note.ID] })
	}

	inRange := func(t time.Time, start, end *time.Time) bool {
		if start != nil && t.Before(*start) {
			return false
		}
		if end != nil && !t.Before(*end) {
			return false
		}
		return true
	}
	if opts.CreatedStart != nil || opts.CreatedEnd != nil {
		filter(func(r *noteResult) bool { return inRange(r.note.Created, opts.CreatedStart, opts.CreatedEnd) })
	}
	if opts.ModifiedStart != nil || opts.ModifiedEnd != nil {
		filter(func(r *noteResult) bool { return inRange(r.note.Modified, opts.ModifiedStart, opts.ModifiedEnd) })
	}

	// sorting
	sorters := opts.Sorters
	recursive := (opts.LinkedBy != nil && opts.LinkedBy.Recursive && !opts.LinkedBy.Negate) || (opts.LinkTo != nil && opts.LinkTo.Recursive && !opts.LinkTo.Negate)
	matchRank := len(opts.Match) > 0 && (opts.MatchStrategy == "fts" || opts.MatchStrategy == "")
	sort.SliceStable(results, func(i, j int) bool { return results[i].note.ID < results[j].note.ID })
	var keys []func(a, b *noteResult) int
	for _, s := range sorters {
		s := s
		var cmp func(a, b *noteResult) int
		switch s.Field {
		case "created":
			cmp = func(a, b *noteResult) int { return cmpTime(a.note.Created, b.note.Created) }
		case "modified":
			cmp = func(a, b *noteResult) int { return cmpTime(a.note.Modified, b.note.Modified) }
		case "path":
			cmp = func(a, b *noteResult) int { return strings.Compare(sortablePath(a.note.Path), sortablePath(b.note.Path)) }
		case "title":
			cmp = func(a, b *noteResult) int { return strings.Compare(a.note.Title, b.note.Title) }
		case "word-count":
			cmp = func(a, b *noteResult) int { return a.note.WordCount - b.note.WordCount }
		case "random":
			rand.Seed(time.Now().UnixNano())
			rnd := map[int64]float64{}
			for _, r := range results {
				rnd[r.note.ID] = rand.Float64()
			}
			cmp = func(a, b *noteResult) int {
				if rnd[a.note.ID] < rnd[b.note.ID] {
					return -1
				} else if rnd[a.note.ID] > rnd[b.note.ID] {
					return 1
				}
				return 0
			}
		}
		if cmp == nil {
			continue
		}
		if !s.Ascending {
			c := cmp
			cmp = func(a, b *noteResult) int { return -c(a, b) }
		}
		keys = append(keys, cmp)
	}
	if len(keys) == 0 {
		if matchRank {
			keys = append(keys, func(a, b *noteResult) int {
				if a.rank < b.rank {
					return -1
				} else if a.rank > b.rank {
					return 1
				}
				return 0
			})
		} else if recursive {
			keys = append(keys, func(a, b *noteResult) int { return a.distance - b.distance })
			keys = append(keys, func(a, b *noteResult) int { return strings.Compare(a.note.Title, b.note.Title) })
		} else {
			keys = append(keys, func(a, b *noteResult) int { return strings.Compare(a.note.Title, b.note.Title) })
		}
	}
	sort.SliceStable(results, func(i, j int) bool {
		for _, k := range keys {
			c := k(results[i], results[j])
			if c != 0 {
				return c < 0
			}
		}
		return false
	})
	if opts.Limit > 0 && len(results) > opts.Limit {
		results = results[:opts.Limit]
	}
	for _, r := range results {
		if !r.hasSnip {
			if r.note.Lead != "" {
				r.snippets = []string{r.note.Lead}
			} else {
				r.snippets = []string{}
			}
		}
	}
	return results, nil
}

func cmpTime(a, b time.Time) int {
	if a.Before(b) {
		return -1
	}
	if a.After(b) {
		return 1
	}
	return 0
}

func parseSorters(strs []string) ([]Sorter, error) {
	var out []Sorter
	for i := len(strs) - 1; i >= 0; i-- {
		s, err := parseSorter(strs[i])
		if err != nil {
			return nil, err
		}
		out = append(out, s)
	}
	return out, nil
}

func parseSorter(s string) (Sorter, error) {
	orig := s
	ascending := true
	explicit := false
	if strings.HasSuffix(s, "+") {
		s = s[:len(s)-1]
		explicit = true
	} else if strings.HasSuffix(s, "-") {
		s = s[:len(s)-1]
		ascending = false
		explicit = true
	}
	var field string
	switch s {
	case "created", "c":
		field = "created"
		if !explicit {
			ascending = false
		}
	case "modified", "m":
		field = "modified"
		if !explicit {
			ascending = false
		}
	case "path", "p":
		field = "path"
	case "title", "t":
		field = "title"
	case "random", "r":
		field = "random"
	case "word-count", "wc":
		field = "word-count"
	default:
		return Sorter{}, fmt.Errorf("%s: unknown sorting term\ntry created, modified, path, title, random or word-count", orig)
	}
	return Sorter{Field: field, Ascending: ascending}, nil
}

func relPathFromWD(wd, abs string) string {
	rel, err := filepath.Rel(wd, abs)
	if err != nil {
		return abs
	}
	return rel
}
