package main

import (
	"strings"
	"unicode"
)

// convertFTSQuery transforms a Google-like query into a SQLite FTS5 one.
func convertFTSQuery(query string) string {
	var out strings.Builder
	var term strings.Builder
	termActive := false
	hadQuote := false
	inQuote := false

	commit := func(raw bool) {
		if !termActive {
			return
		}
		t := term.String()
		switch {
		case raw:
			out.WriteString(t)
		case !hadQuote && (t == "AND" || t == "OR" || t == "NOT"):
			out.WriteString(t)
		case !hadQuote && strings.HasSuffix(t, "*") && len(t) > 0:
			out.WriteString(`"` + strings.ReplaceAll(t[:len(t)-1], `"`, `""`) + `"*`)
		default:
			out.WriteString(`"` + strings.ReplaceAll(t, `"`, `""`) + `"`)
		}
		term.Reset()
		termActive = false
		hadQuote = false
	}

	for _, c := range query {
		if inQuote {
			if c == '"' {
				inQuote = false
				commit(false)
				continue
			}
			term.WriteRune(c)
			continue
		}
		switch {
		case c == '"':
			inQuote = true
			hadQuote = true
			termActive = true
		case unicode.IsSpace(c):
			commit(false)
			out.WriteRune(c)
		case c == '(' || c == ')':
			commit(false)
			out.WriteRune(c)
		case c == '|':
			commit(false)
			out.WriteString(" OR ")
		case c == ':':
			commit(true)
			out.WriteRune(c)
		case !termActive && c == '-':
			out.WriteString("NOT ")
		case !termActive && (c == '^' || c == '*'):
			out.WriteRune(c)
		default:
			term.WriteRune(c)
			termActive = true
		}
	}
	if inQuote {
		inQuote = false
	}
	commit(false)
	return out.String()
}
