type exitError struct {
	code int
}

func (e *exitError) Error() string { return "" }

func printError(err error) {
	msg := err.Error()
	lines := strings.Split(msg, "\n")
	fmt.Fprintf(os.Stderr, "zk: error: %s\n", strings.Join(lines, "\n           "))
}

func fatalIfError(err error) {
	if err == nil {
		return
	}
	var ee *exitError
	if errors.As(err, &ee) {
		os.Exit(ee.code)
	}
	printError(err)
	os.Exit(1)
}

// preParseDirs extracts --notebook-dir and --working-dir from args.
func preParseDirs(args []string) (nbDir string, wd string, wdSet bool, rest []string, err error) {
	rest = []string{}
	for i := 0; i < len(args); i++ {
		a := args[i]
		if a == "--" {
			rest = append(rest, args[i:]...)
			break
		}
		switch {
		case a == "--notebook-dir":
			if i+1 >= len(args) {
				return "", "", false, nil, fmt.Errorf("--notebook-dir requires a path argument")
			}
			nbDir = args[i+1]
