func (a *App) loadTemplate(src string) ([]*tNode, error) {
	nodes, err := parseTemplate(src)
	if err != nil {
		return nil, fmt.Errorf("load template failed: %v", err)
	}
	return nodes, nil
}

func encodePathSegments(p string) string {
	parts := strings.Split(p, "/")
	for i, s := range parts {
		parts[i] = urlPathEscape(s)
	}
	return strings.Join(parts, "/")
}

func urlPathEscape(s string) string {
	var b strings.Builder
	for i := 0; i < len(s); i++ {
		c := s[i]
		if (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '-' || c == '_' || c == '.' || c == '~' || c == '$' || c == '&' || c == '+' || c == ':' || c == '=' || c == '@' {
			b.WriteByte(c)
		} else {
			fmt.Fprintf(&b, "%%%02X", c)
		}
	}
	return b.String()
}

// noteLink formats a link to the note at path (relative to the working dir base).
func (a *App) noteLink(nb *Notebook, n *Note, relPath string, absP string) (string, error) {
	md := nb.Config.Markdown
	format := md.LinkFormat
	encode := format == "markdown"
	if format != "markdown" && format != "wiki" {
		encode = false
	}
	if md.LinkEncodePath != nil {
		encode = *md.LinkEncodePath
	}
	p := relPath
	filename := filepath.Base(n.Path)
	abs := absP
	if md.LinkDropExtension {
		ext := filepath.Ext(p)
		p = strings.TrimSuffix(p, ext)
		filename = strings.TrimSuffix(filename, ext)
		abs = strings.TrimSuffix(abs, ext)
	}
	if encode {
		p = encodePathSegments(p)
		filename = encodePathSegments(filename)
		abs = encodePathSegments(abs)
	}
	switch format {
	case "markdown":
		return "[" + n.Title + "](" + p + ")", nil
	case "wiki":
		return "[[" + p + "]]", nil
	}
	tpl, err := a.loadTemplate(format)
	if err != nil {
		return "", err
	}
	ctx := map[string]interface{}{
		"path": p, "title": n.Title, "filename": filename, "abs-path": abs, "rel-path": p, "metadata": n.Metadata,
	}
	return renderTemplate(tpl, ctx, zkHelpers(a.renderEnv(nb)))
}

func (a *App) noteContext(nb *Notebook, r *noteResult) (map[string]interface{}, error) {
	n := r.note
	absP := filepath.Join(nb.Path, n.Path)
	rel := relPathFromWD(a.WorkDir, absP)
	link, err := a.noteLink(nb, n, rel, absP)
	if err != nil {
		return nil, err
	}
	filename := filepath.Base(n.Path)
	stem := strings.TrimSuffix(filename, filepath.Ext(filename))
	snippets := r.snippets
	if snippets == nil {
		snippets = []string{}
	}
	tags := n.Tags
	if tags == nil {
		tags = []string{}
	}
	meta := n.Metadata
	if meta == nil {
		meta = map[string]interface{}{}
	}
	ctx := map[string]interface{}{
		"filename": filename, "filenameStem": stem, "filename-stem": stem,
		"path": rel, "absPath": absP, "abs-path": absP,
		"title": n.Title, "link": link, "lead": n.Lead, "body": n.Body,
		"snippets": snippets, "rawContent": n.Raw, "raw-content": n.Raw,
		"wordCount": n.WordCount, "word-count": n.WordCount,
		"tags": tags, "metadata": meta, "created": n.Created, "modified": n.Modified,
		"checksum": n.Checksum,
	}
	ctx["__json"] = noteJSON{
		Filename: filename, FilenameStem: stem, Path: rel, AbsPath: absP, Title: n.Title, Link: link,
		Lead: n.Lead, Body: n.Body, Snippets: stripMatchTags(snippets), RawContent: n.Raw, WordCount: n.WordCount,
		Tags: tags, Metadata: meta, Created: n.Created, Modified: n.Modified, Checksum: n.Checksum,
	}
	return ctx, nil
}

type noteJSON struct {
	Filename     string                 `json:"filename"`
	FilenameStem string                 `json:"filenameStem"`
	Path         string                 `json:"path"`
	AbsPath      string                 `json:"absPath"`
	Title        string                 `json:"title"`
	Link         string                 `json:"link"`
	Lead         string                 `json:"lead"`
	Body         string                 `json:"body"`
	Snippets     []string               `json:"snippets"`
	RawContent   string                 `json:"rawContent"`
	WordCount    int                    `json:"wordCount"`
	Tags         []string               `json:"tags"`
	Metadata     map[string]interface{} `json:"metadata"`
	Created      time.Time              `json:"created"`
	Modified     time.Time              `json:"modified"`
	Checksum     string                 `json:"checksum"`
}

func stripMatchTags(snips []string) []string {
	out := make([]string, len(snips))
	for i, s := range snips {
		s = strings.ReplaceAll(s, "<zk:match>", "")
		s = strings.ReplaceAll(s, "</zk:match>", "")
		out[i] = s
	}
	return out
}

func (a *App) highlightSnippets(snips []string) []string {
	out := make([]string, len(snips))
	for i, s := range snips {
		var b strings.Builder
		for {
			start := strings.Index(s, "<zk:match>")
			if start < 0 {
				b.WriteString(s)
				break
			}
			end := strings.Index(s[start:], "</zk:match>")
			if end < 0 {
				b.WriteString(strings.ReplaceAll(s, "<zk:match>", ""))
				break
			}
			b.WriteString(s[:start])
			term := s[start+len("<zk:match>") : start+end]
			b.WriteString(a.styler.Style(term, "term"))
			s = s[start+end+len("</zk:match>"):]
		}
		out[i] = b.String()
	}
	return out
}

func (a *App) indexIfNeeded(nb *Notebook) error {
	if nb.indexed {
		return nil
	}
	_, err := nb.Sync(false, nil)
	nb.indexed = true
	return err
}

func (a *App) buildFindOpts(nb *Notebook, p *Parsed) (*FindOpts, error) {
	if p.Bool("exact-match") {
		return nil, fmt.Errorf("incorrect criteria: the --exact-match (-e) option is deprecated, use --match-strategy=exact (-Me) instead")
	}
	opts := &FindOpts{}
	opts.Match = p.Slice("match")
	opts.MatchStrategy = p.Str("match-strategy")
	switch opts.MatchStrategy {
	case "fts", "re", "exact":
	default:
		return nil, fmt.Errorf("incorrect criteria: %s: unknown match strategy\ntry fts (full-text search), re (regular expression) or exact", opts.MatchStrategy)
	}
	rel := func(paths []string) []string {
		var out []string
		for _, s := range paths {
			abs := absPath(s, a.WorkDir)
			r, err := nb.RelPath(abs)
			if err != nil {
				r = abs
			}
			out = append(out, r)
		}
		return out
	}
	opts.IncludeHrefs = rel(p.Args)
	opts.ExcludeHrefs = rel(p.Slice("exclude"))
	opts.Tags = p.Slice("tag")
	opts.Mention = rel(p.Slice("mention"))
	opts.MentionedBy = rel(p.Slice("mentioned-by"))
	maxDist := int(p.Int("max-distance"))
	recursive := p.Bool("recursive")
	if v := p.Slice("link-to"); len(v) > 0 {
		opts.LinkTo = &LinkFilter{Hrefs: rel(v), Recursive: recursive, MaxDistance: maxDist}
	}
	if v := p.Slice("no-link-to"); len(v) > 0 {
		opts.LinkTo = &LinkFilter{Hrefs: rel(v), Negate: true}
	}
	if v := p.Slice("linked-by"); len(v) > 0 {
		opts.LinkedBy = &LinkFilter{Hrefs: rel(v), Recursive: recursive, MaxDistance: maxDist}
	}
	if v := p.Slice("no-linked-by"); len(v) > 0 {
		opts.LinkedBy = &LinkFilter{Hrefs: rel(v), Negate: true}
	}
	opts.Related = rel(p.Slice("related"))
	opts.Orphan = p.Bool("orphan")
	opts.Tagless = p.Bool("tagless")
	opts.MissingBacklink = p.Bool("missing-backlink")
	now := time.Now()
	if s := p.Str("created"); s != "" {
		start, end, err := parseDayRange(s, now)
		if err != nil {
			return nil, err
		}
		opts.CreatedStart, opts.CreatedEnd = &start, &end
	}
	if s := p.Str("created-before"); s != "" {
		t, err := parseNaturalDate(s, now)
		if err != nil {
			return nil, err
		}
		opts.CreatedEnd = &t
	}
	if s := p.Str("created-after"); s != "" {
		t, err := parseNaturalDate(s, now)
		if err != nil {
			return nil, err
		}
		opts.CreatedStart = &t
	}
	if s := p.Str("modified"); s != "" {
		start, end, err := parseDayRange(s, now)
		if err != nil {
			return nil, err
		}
		opts.ModifiedStart, opts.ModifiedEnd = &start, &end
	}
	if s := p.Str("modified-before"); s != "" {
		t, err := parseNaturalDate(s, now)
		if err != nil {
			return nil, err
		}
		opts.ModifiedEnd = &t
	}
	if s := p.Str("modified-after"); s != "" {
		t, err := parseNaturalDate(s, now)
		if err != nil {
			return nil, err
		}
		opts.ModifiedStart = &t
	}
	sorters, err := parseSorters(p.Slice("sort"))
	if err != nil {
		return nil, err
	}
	opts.Sorters = sorters
	opts.Limit = int(p.Int("limit"))
	return opts, nil
}

func (a *App) findNotes(nb *Notebook, p *Parsed) ([]*noteResult, error) {
	if err := a.indexIfNeeded(nb); err != nil {
		return nil, err
	}
	opts, err := a.buildFindOpts(nb, p)
	if err != nil {
		if strings.HasPrefix(err.Error(), "incorrect criteria") {
			return nil, err
		}
		return nil, fmt.Errorf("incorrect criteria: %v", err)
	}
	res, err := nb.Find(opts)
	if err != nil {
		return nil, err
	}
	return res, nil
}

func (a *App) cmdList(p *Parsed) error {
	nb, err := a.requireNotebook()
	if err != nil {
		return err
	}
	format := p.Str("format")
	isJSON := format == "json" || format == "jsonl"
	if isJSON {
		if p.Set["header"] {
			return fmt.Errorf("--header can't be used with JSON format")
		}
		if p.Set["footer"] || p.Bool("delimiter0") {
			return fmt.Errorf("--footer can't be used with JSON format")
		}
		if p.Set["delimiter"] {
			return fmt.Errorf("--delimiter can't be used with JSON format")
		}
	}
	delimiter := p.Str("delimiter")
	footer := p.Str("footer")
	if p.Bool("delimiter0") {
		if p.Set["delimiter"] {
			return fmt.Errorf("--delimiter and --delimiter0 can't be used together")
		}
		if p.Set["footer"] {
			return fmt.Errorf("--footer and --delimiter0 can't be used together")
		}
		delimiter = "\x00"
		footer = "\x00"
	}
	results, err := a.findNotes(nb, p)
	if err != nil {
		return err
	}
	var buf bytes.Buffer
	if len(results) > 0 {
		if isJSON {
			var items []string
			for _, r := range results {
				ctx, err := a.noteContext(nb, r)
				if err != nil {
					return err
				}
				b, _ := json.Marshal(ctx["__json"])
				items = append(items, string(b))
			}
			if format == "json" {
				buf.WriteString("[" + strings.Join(items, ",") + "]\n")
			} else {
				for _, it := range items {
					buf.WriteString(it + "\n")
				}
			}
		} else {
			tplSrc := format
			if tplSrc == "" {
				tplSrc = "short"
			}
			if f, ok := noteFormats[tplSrc]; ok {
				tplSrc = f
			} else {
				tplSrc = unescapeFlag(tplSrc)
			}
			tpl, err := a.loadTemplate(tplSrc)
			if err != nil {
				return err
			}
			helpers := zkHelpers(a.renderEnv(nb))
			buf.WriteString(unescapeFlag(p.Str("header")))
			for i, r := range results {
				ctx, err := a.noteContext(nb, r)
				if err != nil {
					return err
				}
				ctx["snippets"] = a.highlightSnippets(r.snippets)
				out, err := renderTemplate(tpl, ctx, helpers)
				if err != nil {
					return fmt.Errorf("render template failed: %v", err)
				}
				if i > 0 {
					buf.WriteString(unescapeFlag(delimiter))
				}
				buf.WriteString(out)
			}
			buf.WriteString(unescapeFlag(footer))
		}
	}
	a.paginate(nb, p.Bool("no-pager"), buf.Bytes())
	if !p.Bool("quiet") {
		fmt.Fprintf(os.Stderr, "\nFound %d %s\n", len(results), pluralNote(len(results)))
	}
	return nil
}

func (a *App) paginate(nb *Notebook, noPager bool, data []byte) {
	if noPager || !a.stdoutTTY || len(data) == 0 {
		os.Stdout.Write(data)
		return
	}
	pager := ""
	if nb != nil && nb.Config.Tool.Pager != nil {
		pager = *nb.Config.Tool.Pager
	} else if s := os.Getenv("ZK_PAGER"); s != "" {
		pager = s
	} else if s := os.Getenv("PAGER"); s != "" {
		pager = s
	} else {
		pager = "less -FIRX"
	}
	if pager == "" {
		os.Stdout.Write(data)
		return
	}
	cmd := exec.Command(userShell(), "-c", pager)
	cmd.Stdin = bytes.NewReader(data)
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	if err := cmd.Run(); err != nil {
		io.Copy(os.Stdout, bytes.NewReader(data))
	}
}
