package main

import (
	"fmt"
	"regexp"
	"strconv"
	"strings"
	"time"
)

func startOfDay(t time.Time) time.Time {
	y, m, d := t.Date()
	return time.Date(y, m, d, 0, 0, 0, 0, t.Location())
}

func parseDayRange(s string, now time.Time) (time.Time, time.Time, error) {
	t, err := parseNaturalDate(s, now)
	if err != nil {
		return time.Time{}, time.Time{}, err
	}
	start := startOfDay(t)
	return start, start.AddDate(0, 0, 1), nil
}

var numberWords = map[string]int{
	"one": 1, "two": 2, "three": 3, "four": 4, "five": 5, "six": 6, "seven": 7, "eight": 8, "nine": 9, "ten": 10, "eleven": 11, "twelve": 12,
}

var weekdays = map[string]time.Weekday{
	"sunday": time.Sunday, "monday": time.Monday, "tuesday": time.Tuesday, "wednesday": time.Wednesday,
	"thursday": time.Thursday, "friday": time.Friday, "saturday": time.Saturday,
}

var monthsByName = map[string]time.Month{
	"january": 1, "february": 2, "march": 3, "april": 4, "may": 5, "june": 6, "july": 7, "august": 8,
	"september": 9, "october": 10, "november": 11, "december": 12,
	"jan": 1, "feb": 2, "mar": 3, "apr": 4, "jun": 6, "jul": 7, "aug": 8, "sep": 9, "sept": 9, "oct": 10, "nov": 11, "dec": 12,
}

var reISODate = regexp.MustCompile(`^(\d{4})-(\d{1,2})-(\d{1,2})$`)
var reISODateTime = regexp.MustCompile(`^(\d{4})-(\d{2})-(\d{2})t(\d{2}):(\d{2})(?::(\d{2}))?(z|[+-]\d{2}:?\d{2})?$`)
var reClock = regexp.MustCompile(`^(\d{1,2})(?::(\d{2}))?(?::(\d{2}))?\s*(am|pm)?$`)

func unitDuration(unit string) (string, bool) {
	unit = strings.TrimSuffix(unit, "s")
	switch unit {
	case "second", "sec":
		return "second", true
	case "minute", "min":
		return "minute", true
	case "hour":
		return "hour", true
	case "day":
		return "day", true
	case "week":
		return "week", true
	case "month":
		return "month", true
	case "year":
		return "year", true
	}
	return "", false
}

func applyOffset(now time.Time, unit string, n int, past bool) time.Time {
	sign := 1
	if past {
		sign = -1
	}
	switch unit {
	case "second":
		return now.Add(time.Duration(sign*n) * time.Second)
	case "minute":
		return now.Add(time.Duration(sign*n) * time.Minute)
	case "hour":
		return now.Add(time.Duration(sign*n) * time.Hour)
	case "day":
		t := now.AddDate(0, 0, sign*n)
		if past {
			return startOfDay(t)
		}
		return t
	case "week":
		t := now.AddDate(0, 0, sign*7*n)
		if past {
			return startOfDay(t)
		}
		return t
	case "month":
		return now.AddDate(0, sign*n, 0)
	case "year":
		return now.AddDate(sign*n, 0, 0)
	}
	return now
}

func parseCount(s string) (int, bool) {
	if n, err := strconv.Atoi(s); err == nil {
		return n, true
	}
	if n, ok := numberWords[s]; ok {
		return n, true
	}
	return 0, false
}

func applyClock(day time.Time, s string) (time.Time, bool) {
	m := reClock.FindStringSubmatch(s)
	if m == nil {
		return day, false
	}
	h, _ := strconv.Atoi(m[1])
	min, sec := 0, 0
	if m[2] != "" {
		min, _ = strconv.Atoi(m[2])
	}
	if m[3] != "" {
		sec, _ = strconv.Atoi(m[3])
	}
	if m[4] == "pm" && h < 12 {
		h += 12
	} else if m[4] == "am" && h == 12 {
		h = 0
	}
	if h > 23 || min > 59 || sec > 59 {
		return day, false
	}
	y, mo, d := day.Date()
	return time.Date(y, mo, d, h, min, sec, 0, day.Location()), true
}

func pegError(tok string, start, end int) error {
	return fmt.Errorf("\nparse error near PegText (line 1 symbol %d - line 1 symbol %d):\n%q\n", start, end, tok)
}

func parseNaturalDate(input string, now time.Time) (time.Time, error) {
	s := strings.ToLower(strings.TrimSpace(input))
	if s == "" || s == "now" {
		return now, nil
