		return time.Time{}, pegError(m[1], 1, 1+len(m[1]))
	}
	words := strings.Fields(s)
	// split "at" time suffix
	var clock string
	for i, w := range words {
		if w == "at" && i+1 < len(words) {
			clock = strings.Join(words[i+1:], " ")
			words = words[:i]
			break
		}
	}
	base, ok := parseDayWords(words, now)
	if !ok {
		// try "yesterday 10am" style
		if len(words) >= 2 {
			if b, ok2 := parseDayWords(words[:1], now); ok2 {
				if t, ok3 := applyClock(b, strings.Join(words[1:], " ")); ok3 {
					return t, nil
				}
			}
		}
		if t, ok := applyClock(startOfDay(now), s); ok {
			return t, nil
		}
		return now, nil
	}
