		}
	}
	return base, nil
}

func parseDayWords(words []string, now time.Time) (time.Time, bool) {
	if len(words) == 0 {
		return now, false
	}
	switch len(words) {
	case 1:
		switch words[0] {
		case "today":
			return startOfDay(now), true
		case "yesterday":
			return startOfDay(now.AddDate(0, 0, -1)), true
		case "tomorrow":
			return startOfDay(now.AddDate(0, 0, 1)), true
		case "now":
			return now, true
		}
