				return nextWeekday(now, wd), true
			}
			if u, ok := unitDuration(words[1]); ok {
				return applyOffset(now, u, 1, false), true
			}
		}
		if n, ok := parseCount(words[0]); ok {
			if u, ok := unitDuration(words[1]); ok {
				return applyOffset(now, u, n, true), true
			}
		}
	case 3:
		if words[2] == "ago" {
