				if u, ok := unitDuration(words[1]); ok {
					return applyOffset(now, u, n, false), true
				}
			}
		}
	}
	return now, false
}

func lastWeekday(now time.Time, wd time.Weekday) time.Time {
	d := startOfDay(now)
	for i := 1; i <= 7; i++ {
		c := d.AddDate(0, 0, -i)
		if c.Weekday() == wd {
