var reISODateTime = regexp.MustCompile(`^(\d{4})-(\d{2})-(\d{2})t(\d{2}):(\d{2})(?::(\d{2}))?(z|[+-]\d{2}:?\d{2})?$`)
var reClock = regexp.MustCompile(`^(\d{1,2})(?::(\d{2}))?(?::(\d{2}))?\s*(am|pm)?$`)

func unitDuration(unit string) (string, bool) {
	unit = strings.TrimSuffix(unit, "s")
	switch unit {
	case "second", "sec":
		return "second", true
	case "minute", "min":
		return "minute", true
	case "hour":
		return "hour", true
	case "day":
		return "day", true
	case "week":
		return "week", true
	case "month":
		return "month", true
	case "year":
		return "year", true
	}
	return "", false
