func (a *App) cmdInit(p *Parsed) error {
	dir := a.WorkDir
	if len(p.Args) > 0 {
		dir = absPath(p.Args[0], a.WorkDir)
	}
	wiki, hashtags, colon, multiword := true, true, false, false
