		return fmt.Errorf("init: a notebook already exists in %s", root)
	}
	if err := os.MkdirAll(filepath.Join(dir, ".zk", "templates"), 0755); err != nil {
		return fmt.Errorf("init: %v", err)
	}
	if err := os.WriteFile(filepath.Join(dir, ".zk", "config.toml"), []byte(renderInitConfig(wiki, hashtags, colon, multiword)), 0644); err != nil {
		return fmt.Errorf("init: %v", err)
	}
	if err := os.WriteFile(filepath.Join(dir, ".zk", "templates", "default.md"), []byte("# {{title}}\n\n{{content}}\n"), 0644); err != nil {
		return fmt.Errorf("init: %v", err)
	}
	ix, err := openIndex(filepath.Join(dir, ".zk", "notebook.db"))
