}

func (a *App) initPrompts() (bool, bool, bool, bool, error) {
	r := bufio.NewReader(os.Stdin)
	fmt.Print("? Do you prefer [[WikiLinks]] over regular Markdown links? (y/N) ")
	line, err := r.ReadString('\n')
	if err != nil && line == "" {
		return false, false, false, false, fmt.Errorf("EOF")
	}
	ans := strings.ToLower(strings.TrimSpace(line))
	wiki := ans == "y" || ans == "yes"
	fmt.Print("? Choose your favorite inline tag syntaxes (comma-separated: hashtag, multiword, colon): ")
	line, _ = r.ReadString('\n')
	hashtags, colon, multi := false, false, false
	for _, t := range strings.Split(line, ",") {
		switch strings.TrimSpace(strings.ToLower(t)) {
		case "hashtag", "#hashtag":
			hashtags = true
		case "multiword", "multi-word":
			multi = true
		case "colon", ":colon:tag:":
			colon = true
		}
	}
	return wiki, hashtags, colon, multi, nil
