}

// ---- tag list

type tagRow struct {
	ID    int64  `json:"id"`
	Kind  string `json:"kind"`
	Name  string `json:"name"`
	Count int    `json:"noteCount"`
}

func (a *App) cmdTagList(p *Parsed) error {
	nb, err := a.requireNotebook()
	if err != nil {
		return err
	}
	format := p.Str("format")
	isJSON := format == "json" || format == "jsonl"
	if isJSON {
		if p.Set["header"] {
			return fmt.Errorf("--header can't be used with JSON format")
		}
		if p.Set["footer"] || p.Bool("delimiter0") {
			return fmt.Errorf("--footer can't be used with JSON format")
		}
		if p.Set["delimiter"] {
			return fmt.Errorf("--delimiter can't be used with JSON format")
		}
	}
	delimiter := p.Str("delimiter")
	footer := p.Str("footer")
	if p.Bool("delimiter0") {
		if p.Set["delimiter"] {
			return fmt.Errorf("--delimiter and --delimiter0 can't be used together")
		}
		if p.Set["footer"] {
			return fmt.Errorf("--footer and --delimiter0 can't be used together")
		}
		delimiter = "\x00"
		footer = "\x00"
	}
	// sorters
	type tsorter struct {
		field string
		asc   bool
	}
	var sorters []tsorter
	strs := p.Slice("sort")
	for i := len(strs) - 1; i >= 0; i-- {
		s := strs[i]
		orig := s
		asc := true
		explicit := false
		if strings.HasSuffix(s, "+") {
			s = s[:len(s)-1]
			explicit = true
		} else if strings.HasSuffix(s, "-") {
			s = s[:len(s)-1]
			asc = false
			explicit = true
		}
		switch s {
		case "name", "n":
			sorters = append(sorters, tsorter{"name", asc})
		case "note-count", "nc":
			if !explicit {
				asc = false
			}
			sorters = append(sorters, tsorter{"count", asc})
		default:
			return fmt.Errorf("%s: unknown sorting term\ntry name or note-count", orig)
		}
	}
	if err := a.indexIfNeeded(nb); err != nil {
		return err
	}
	ix, err := nb.Index()
	if err != nil {
		return err
	}
	var tags []*tagRow
	ix.db.Query(`SELECT c.id, c.kind, c.name, COUNT(nc.id) FROM collections c JOIN notes_collections nc ON nc.collection_id = c.id WHERE c.kind = 'tag' GROUP BY c.id ORDER BY c.id`, nil, func(s *Stmt) error {
		tags = append(tags, &tagRow{ID: s.Int(0), Kind: s.Text(1), Name: s.Text(2), Count: int(s.Int(3))})
		return nil
	})
	if len(sorters) == 0 {
		sorters = []tsorter{{"name", true}}
	}
	sorters = append(sorters, tsorter{"name", true})
	sort.SliceStable(tags, func(i, j int) bool {
		for _, s := range sorters {
			var c int
			if s.field == "name" {
				c = strings.Compare(tags[i].Name, tags[j].Name)
			} else {
				c = tags[i].Count - tags[j].Count
			}
			if !s.asc {
				c = -c
			}
			if c != 0 {
				return c < 0
			}
		}
		return false
	})
	var buf strings.Builder
	if len(tags) > 0 {
		if isJSON {
			var items []string
			for _, t := range tags {
				b, _ := json.Marshal(t)
				items = append(items, string(b))
			}
			if format == "json" {
				buf.WriteString("[" + strings.Join(items, ",") + "]\n")
			} else {
				for _, it := range items {
					buf.WriteString(it + "\n")
				}
			}
		} else {
			src := format
			switch src {
			case "", "full":
				src = "{{name}} ({{note-count}})"
			case "name":
				src = "{{name}}"
			default:
				src = unescapeFlag(src)
			}
			tpl, err := a.loadTemplate(src)
			if err != nil {
				return err
			}
			helpers := zkHelpers(a.renderEnv(nb))
			buf.WriteString(unescapeFlag(p.Str("header")))
			for i, t := range tags {
				ctx := map[string]interface{}{
					"id": t.ID, "kind": t.Kind, "name": t.Name, "note-count": t.Count, "noteCount": t.Count,
					"__json": t,
				}
				out, err := renderTemplate(tpl, ctx, helpers)
				if err != nil {
					return fmt.Errorf("render template failed: %v", err)
				}
				if i > 0 {
					buf.WriteString(unescapeFlag(delimiter))
				}
				buf.WriteString(out)
			}
			buf.WriteString(unescapeFlag(footer))
		}
	}
	a.paginate(nb, p.Bool("no-pager"), []byte(buf.String()))
	if !p.Bool("quiet") {
		w := "tag"
		if len(tags) > 1 {
			w = "tags"
		}
		fmt.Fprintf(os.Stderr, "\nFound %d %s\n", len(tags), w)
	}
	return nil
}

