type linkJSON struct {
	Title        string   `json:"title"`
	Href         string   `json:"href"`
	Type         string   `json:"type"`
	IsExternal   bool     `json:"isExternal"`
	Rels         []string `json:"rels"`
	Snippet      string   `json:"snippet"`
	SnippetStart int      `json:"snippetStart"`
	SnippetEnd   int      `json:"snippetEnd"`
	SourceID     int64    `json:"sourceId"`
	SourcePath   string   `json:"sourcePath"`
	TargetID     int64    `json:"targetId"`
	TargetPath   string   `json:"targetPath"`
}

func (a *App) cmdGraph(p *Parsed) error {
	nb, err := a.requireNotebook()
	if err != nil {
		return err
	}
	results, err := a.findNotes(nb, p)
	if err != nil {
		return err
	}
	ix, _ := nb.Index()
	links := ix.loadLinks()
	ids := map[int64]bool{}
	var b strings.Builder
	b.WriteString("{\n  \"notes\": [\n")
	for i, r := range results {
		ids[r.note.ID] = true
		ctx, err := a.noteContext(nb, r)
		if err != nil {
			return err
		}
		j, _ := json.Marshal(ctx["__json"])
		b.WriteString("    " + string(j))
		if i < len(results)-1 {
			b.WriteString(",")
		}
		b.WriteString("\n")
	}
	if len(results) == 0 {
		b.WriteString("\n")
	}
	b.WriteString("  ],\n  \"links\": [\n")
	var items []string
	for _, l := range links {
		if l.TargetID == 0 || !ids[l.SourceID] || !ids[l.TargetID] {
			continue
		}
		rels := l.Rels
		if rels == nil {
			rels = []string{}
		}
		j, _ := json.Marshal(linkJSON{Title: l.Title, Href: l.Href, Type: l.Type, IsExternal: l.External, Rels: rels,
			Snippet: l.Snippet, SnippetStart: l.SnippetStart, SnippetEnd: l.SnippetEnd, SourceID: l.SourceID,
			SourcePath: l.SourcePath, TargetID: l.TargetID, TargetPath: l.TargetPath})
		items = append(items, "    "+string(j))
	}
	if len(items) == 0 {
		b.WriteString("\n")
	} else {
		b.WriteString(strings.Join(items, ",\n") + "\n")
	}
	b.WriteString("  ]\n}\n")
	os.Stdout.WriteString(b.String())
	if !p.Bool("quiet") {
		fmt.Fprintf(os.Stderr, "\n\nFound %d %s\n", len(results), pluralNote(len(results)))
	}
	return nil
}

// ---- editor

func shellQuote(s string) string {
	if s == "" {
		return "''"
	}
	safe := true
	for _, c := range s {
		if !((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || strings.ContainsRune("-_./=,:@%+", c)) {
			safe = false
			break
		}
	}
	if safe {
		return s
	}
	return "'" + strings.ReplaceAll(s, "'", `'"'"'`) + "'"
}

func (a *App) editorCommand(nb *Notebook) string {
	if nb != nil && nb.Config.Tool.Editor != nil && *nb.Config.Tool.Editor != "" {
		return *nb.Config.Tool.Editor
	}
	if s := os.Getenv("ZK_EDITOR"); s != "" {
		return s
	}
	if s := os.Getenv("VISUAL"); s != "" {
		return s
	}
	if s := os.Getenv("EDITOR"); s != "" {
		return s
	}
	return ""
}

func (a *App) openEditor(nb *Notebook, paths []string) error {
	editor := a.editorCommand(nb)
	if editor == "" {
		return fmt.Errorf("no editor set in config")
	}
	var quoted []string
	for _, p := range paths {
		quoted = append(quoted, shellQuote(p))
	}
	cmdline := editor + " " + strings.Join(quoted, " ") + " </dev/tty"
	cmd := exec.Command(userShell(), "-c", cmdline, "--")
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	if err := cmd.Run(); err != nil {
		return fmt.Errorf("operation aborted by editor: %s %s: %v", editor, strings.Join(paths, " "), err)
	}
	return nil
}

func (a *App) cmdEdit(p *Parsed) error {
	nb, err := a.requireNotebook()
	if err != nil {
		return err
	}
	results, err := a.findNotes(nb, p)
	if err != nil {
		return err
	}
	if len(results) == 0 {
		fmt.Fprintln(os.Stderr, "Found 0 notes.")
		return nil
	}
	if len(results) > 5 && !p.Bool("force") {
		if a.NoInput || !a.stdinTTY {
			return fmt.Errorf("too many notes to be opened in the editor, aborting…")
		}
		fmt.Printf("? Are you sure you want to open %d notes in the editor? (y/N) ", len(results))
		line, _ := bufio.NewReader(os.Stdin).ReadString('\n')
		ans := strings.ToLower(strings.TrimSpace(line))
		if ans != "y" && ans != "yes" {
			return nil
		}
	}
	var paths []string
	for _, r := range results {
		paths = append(paths, filepath.Join(nb.Path, r.note.Path))
	}
	err = a.openEditor(nb, paths)
	nb.Sync(false, nil)
	return err
}

// ---- new

func randomID(charset string, length int, idCase string) string {
	var chars string
	switch charset {
	case "letters":
		chars = "abcdefghijklmnopqrstuvwxyz"
	case "numbers":
		chars = "0123456789"
	case "alphanum", "":
		chars = "0123456789abcdefghijklmnopqrstuvwxyz"
	case "hex":
		chars = "0123456789abcdef"
	default:
		chars = charset
	}
	switch idCase {
	case "upper":
		chars = strings.ToUpper(chars)
	case "mixed":
		if charset == "letters" || charset == "alphanum" || charset == "" || charset == "hex" {
			chars = chars + strings.ToUpper(strings.TrimLeft(chars, "0123456789"))
		}
	}
	runes := []rune(chars)
	if length <= 0 {
		length = 4
	}
	r := rand.New(rand.NewSource(time.Now().UnixNano()))
	out := make([]rune, length)
	for i := range out {
		out[i] = runes[r.Intn(len(runes))]
	}
	return string(out)
}

type newNoteCtx struct {
	ID           string            `json:"ID"`
	Title        string            `json:"Title"`
	Content      string            `json:"Content"`
	Dir          string            `json:"Dir"`
	Filename     string            `json:"Filename"`
	FilenameStem string            `json:"FilenameStem"`
	Extra        map[string]string `json:"Extra"`
	Now          time.Time         `json:"Now"`
	Env          map[string]string `json:"Env"`
}

func (c *newNoteCtx) toMap() map[string]interface{} {
	extra := map[string]interface{}{}
	for k, v := range c.Extra {
		extra[k] = v
	}
	env := map[string]interface{}{}
	for k, v := range c.Env {
		env[k] = v
	}
	return map[string]interface{}{
		"id": c.ID, "title": c.Title, "content": c.Content, "dir": c.Dir, "filename": c.Filename,
		"filename-stem": c.FilenameStem, "extra": extra, "now": c.Now, "env": env, "__json": c,
	}
}

func envMap() map[string]string {
	m := map[string]string{}
	for _, kv := range os.Environ() {
		if i := strings.IndexByte(kv, '='); i >= 0 {
			m[kv[:i]] = kv[i+1:]
		}
	}
	return m
}

func (a *App) cmdNew(p *Parsed) error {
	nb, err := a.requireNotebook()
	if err != nil {
		return err
	}
	dirArg := ""
	if len(p.Args) > 0 {
		dirArg = p.Args[0]
	}
	absDir := a.WorkDir
	if dirArg != "" {
		absDir = absPath(dirArg, a.WorkDir)
	}
	relDir, err := nb.RelPath(absDir)
	if err != nil {
		return fmt.Errorf("new note: %v", err)
	}
	if info, err := os.Stat(absDir); err != nil || !info.IsDir() {
		name := dirArg
		if name == "" {
			name = absDir
		}
		return fmt.Errorf("new note: %s: directory not found", name)
	}
	var group GroupConfig
	if g := p.Str("group"); g != "" {
		gc, ok := nb.Config.Groups[g]
		if !ok {
			return fmt.Errorf("new note: no group named `%s` found in the config", g)
		}
		group = gc
	} else {
		group = nb.groupConfigForDir(relDir)
	}
	content := ""
	if p.Bool("interactive") {
		b, _ := io.ReadAll(os.Stdin)
		content = string(b)
	}
	title := p.Str("title")
	if title == "" {
		title = group.Note.DefaultTitle
	}
	now := time.Now()
	if d := p.Str("date"); d != "" {
		t, err := parseNaturalDate(d, now)
		if err != nil {
			return fmt.Errorf("new note: %v", err)
		}
		now = t
	}
	extra := map[string]string{}
	for k, v := range group.Extra {
		extra[k] = v
	}
	for _, kv := range p.Map("extra") {
		extra[kv[0]] = kv[1]
	}
	if os.Getenv("ZK_SHELL") == "" {
		os.Setenv("ZK_SHELL", "")
	}
	env := envMap()
	helpers := zkHelpers(a.renderEnv(nb))
	ctx := &newNoteCtx{Title: title, Content: content, Dir: relDir, Extra: extra, Now: now, Env: env}

	var absNote string
	for attempt := 0; attempt < 50; attempt++ {
		id := p.Str("id")
		if id == "" {
			id = randomID(group.Note.IDCharset, group.Note.IDLength, group.Note.IDCase)
		}
		ctx.ID = id
		ftpl, err := a.loadTemplate(group.Note.FilenameTpl)
		if err != nil {
			return fmt.Errorf("new note: %v", err)
		}
		fname, err := renderTemplate(ftpl, ctx.toMap(), helpers)
		if err != nil {
			return fmt.Errorf("new note: render template failed: %v", err)
		}
		fname = fname + "." + group.Note.Extension
		absNote = filepath.Join(absDir, fname)
		if _, err := os.Stat(absNote); err == nil && p.Str("id") == "" && attempt < 49 {
			continue
		}
		ctx.Filename = filepath.Base(fname)
		ctx.FilenameStem = strings.TrimSuffix(ctx.Filename, filepath.Ext(ctx.Filename))
		break
	}
	exists := false
	if _, err := os.Stat(absNote); err == nil {
		exists = true
	}

	body := ""
	tplName := group.Note.BodyTemplate
	if p.Str("template") != "" {
		tplName = p.Str("template")
	}
	if tplName != "" {
		tplPath := tplName
		if strings.HasPrefix(tplPath, "~/") {
			home, _ := os.UserHomeDir()
			tplPath = filepath.Join(home, tplPath[2:])
		} else if !filepath.IsAbs(tplPath) {
			tplPath = filepath.Join(nb.Path, ".zk", "templates", tplPath)
		}
		src, err := os.ReadFile(tplPath)
		if err != nil {
			return fmt.Errorf("new note: cannot find template at %s", tplPath)
		}
		btpl, err := a.loadTemplate(string(src))
		if err != nil {
			return fmt.Errorf("new note: %v", err)
		}
		body, err = renderTemplate(btpl, ctx.toMap(), helpers)
		if err != nil {
			return fmt.Errorf("new note: render template failed: %v", err)
		}
	}

	if p.Bool("dry-run") {
		os.Stdout.WriteString(body)
		fmt.Fprintln(os.Stderr, absNote)
		return nil
	}
	if !exists {
		if err := os.MkdirAll(filepath.Dir(absNote), 0755); err != nil {
			return fmt.Errorf("new note: %v", err)
		}
		if err := os.WriteFile(absNote, []byte(body), 0644); err != nil {
			return fmt.Errorf("new note: %v", err)
		}
	}
	nb.Sync(false, nil)
	if p.Bool("print-path") {
		fmt.Println(absNote)
		return nil
	}
	err = a.openEditor(nb, []string{absNote})
	nb.Sync(false, nil)
	return err
}

