package main

import (
	"bufio"
	"io"
	"os"
	"strconv"
	"strings"
)

// runLSP implements a minimal LSP server loop (initialize/shutdown/exit).
func runLSP(a *App) error {
	r := bufio.NewReader(os.Stdin)
	for {
		length := -1
		for {
			line, err := r.ReadString('\n')
			if err != nil {
				return nil
			}
			line = strings.TrimRight(line, "\r\n")
			if line == "" {
				break
			}
			if strings.HasPrefix(strings.ToLower(line), "content-length:") {
				n, _ := strconv.Atoi(strings.TrimSpace(line[len("content-length:"):]))
				length = n
			}
		}
		if length < 0 {
			continue
		}
		buf := make([]byte, length)
		if _, err := io.ReadFull(r, buf); err != nil {
			return nil
		}
		msg := string(buf)
		if strings.Contains(msg, `"method":"exit"`) {
			return nil
		}
	}
}
