func (a *App) cmdIndex(p *Parsed) error {
	nb, err := a.requireNotebook()
	if err != nil {
		return err
	}
	if p.Bool("verbose") && p.Bool("quiet") {
		return fmt.Errorf("--verbose and --quiet can't be used together")
