// shellSplit splits a string into words like a POSIX shell (without expansion).
func shellSplit(s string) ([]string, error) {
	var words []string
	var cur strings.Builder
	inWord := false
	i := 0
	for i < len(s) {
		c := s[i]
		switch {
		case c == '\\':
			if i+1 < len(s) {
				cur.WriteByte(s[i+1])
				i += 2
				inWord = true
				continue
			}
			i++
		case c == '\'':
			j := strings.IndexByte(s[i+1:], '\'')
			if j < 0 {
				return nil, fmt.Errorf("invalid command line string")
			}
			cur.WriteString(s[i+1 : i+1+j])
			i += j + 2
			inWord = true
		case c == '"':
			i++
			for i < len(s) && s[i] != '"' {
				if s[i] == '\\' && i+1 < len(s) && strings.IndexByte("\"\\$`", s[i+1]) >= 0 {
					cur.WriteByte(s[i+1])
					i += 2
					continue
				}
				cur.WriteByte(s[i])
				i++
			}
			if i >= len(s) {
				return nil, fmt.Errorf("invalid command line string")
			}
			i++
			inWord = true
		case c == ' ' || c == '\t' || c == '\n':
			if inWord {
				words = append(words, cur.String())
				cur.Reset()
				inWord = false
			}
			i++
		default:
			cur.WriteByte(c)
			inWord = true
			i++
		}
	}
	if inWord {
		words = append(words, cur.String())
	}
	return words, nil
}

// expandNamedFilters merges named filters found in positional args.
func expandNamedFilters(app *CmdDef, p *Parsed, filters map[string]string, expanded map[string]bool) (*Parsed, error) {
	if len(filters) == 0 {
		return p, nil
	}
	var actual []string
	var merged []*Parsed
	for _, arg := range p.Args {
		f, ok := filters[arg]
		if !ok || expanded[arg] {
			actual = append(actual, arg)
			continue
		}
		words, err := shellSplit(f)
		if err != nil {
			return nil, err
		}
		fp, err := parseArgs(app, append(append([]string{}, p.Path...), words...))
		if err != nil {
			return nil, err
		}
		exp := map[string]bool{}
		for k := range expanded {
			exp[k] = true
		}
		exp[arg] = true
		fp, err = expandNamedFilters(app, fp, filters, exp)
		if err != nil {
			return nil, err
		}
		merged = append(merged, fp)
	}
	if len(merged) == 0 {
		return p, nil
	}
	out := &Parsed{Path: p.Path, Flags: map[string]interface{}{}, Set: map[string]bool{}, Help: p.Help, Version: p.Version, node: p.node, chain: p.chain}
	for k, v := range p.Flags {
		out.Flags[k] = v
	}
	for k, v := range p.Set {
		out.Set[k] = v
	}
	for _, fp := range merged {
		actual = append(actual, fp.Args...)
		for name := range fp.Set {
			fv := fp.Flags[name]
			switch v := fv.(type) {
			case []string:
				cur, _ := out.Flags[name].([]string)
				if p.Set[name] {
					out.Flags[name] = append(append([]string{}, v...), cur...)
				} else {
					out.Flags[name] = append(append([]string{}, cur...), v...)
				}
			case [][2]string:
				cur, _ := out.Flags[name].([][2]string)
				out.Flags[name] = append(append([][2]string{}, v...), cur...)
			default:
				if !p.Set[name] {
					out.Flags[name] = fv
				}
			}
			out.Set[name] = true
		}
	}
	out.Args = actual
	return out, nil
}
