package main

import (
	"fmt"
	"os"
	"strings"
	"syscall"
	"unsafe"
)

type termState struct {
	fd    uintptr
	saved syscall.Termios
}

func makeRaw(fd uintptr) (*termState, error) {
	var t syscall.Termios
	if _, _, e := syscall.Syscall(syscall.SYS_IOCTL, fd, syscall.TCGETS, uintptr(unsafe.Pointer(&t))); e != 0 {
		return nil, e
	}
	st := &termState{fd: fd, saved: t}
	raw := t
	raw.Iflag &^= syscall.IGNBRK | syscall.BRKINT | syscall.PARMRK | syscall.ISTRIP | syscall.INLCR | syscall.IGNCR | syscall.ICRNL | syscall.IXON
	raw.Lflag &^= syscall.ECHO | syscall.ECHONL | syscall.ICANON | syscall.ISIG | syscall.IEXTEN
	raw.Cflag &^= syscall.CSIZE | syscall.PARENB
	raw.Cflag |= syscall.CS8
	raw.Cc[syscall.VMIN] = 1
	raw.Cc[syscall.VTIME] = 0
	if _, _, e := syscall.Syscall(syscall.SYS_IOCTL, fd, syscall.TCSETS, uintptr(unsafe.Pointer(&raw))); e != 0 {
		return nil, e
	}
	return st, nil
}

func (s *termState) restore() {
	syscall.Syscall(syscall.SYS_IOCTL, s.fd, syscall.TCSETS, uintptr(unsafe.Pointer(&s.saved)))
}

func termWidth() int {
	var ws struct{ Row, Col, X, Y uint16 }
	if _, _, e := syscall.Syscall(syscall.SYS_IOCTL, os.Stdout.Fd(), syscall.TIOCGWINSZ, uintptr(unsafe.Pointer(&ws))); e == 0 && ws.Col > 0 {
		return int(ws.Col)
	}
	return 80
}

type keyReader struct {
	buf []byte
}

const (
	keyUp = iota + 1000
	keyDown
	keyLeft
	keyRight
	keyEnter
	keyBackspace
	keyCtrlC
	keySpace
	keyOther
)

func (k *keyReader) read() (int, rune) {
	b := make([]byte, 16)
	if len(k.buf) == 0 {
		n, err := os.Stdin.Read(b)
		if err != nil || n == 0 {
			return keyCtrlC, 0
		}
		k.buf = append(k.buf, b[:n]...)
	}
	c := k.buf[0]
	k.buf = k.buf[1:]
	switch c {
	case 3:
		return keyCtrlC, 0
	case '\r', '\n':
		return keyEnter, 0
	case 127, 8:
		return keyBackspace, 0
	case ' ':
		return keySpace, ' '
	case 27:
		if len(k.buf) == 0 {
			n, _ := os.Stdin.Read(b)
			k.buf = append(k.buf, b[:n]...)
		}
		if len(k.buf) >= 2 && k.buf[0] == '[' {
			code := k.buf[1]
			k.buf = k.buf[2:]
			switch code {
			case 'A':
				return keyUp, 0
			case 'B':
				return keyDown, 0
			case 'C':
				return keyRight, 0
			case 'D':
				return keyLeft, 0
			}
			return keyOther, 0
		}
		return keyOther, 0
	}
	return keyOther, rune(c)
}

func visualLines(s string, width int) int {
	n := 0
	for _, l := range strings.Split(s, "\n") {
		w := len([]rune(stripANSI(l)))
		if w == 0 {
			n++
		} else {
			n += (w + width - 1) / width
		}
	}
	return n
}

func stripANSI(s string) string {
	var b strings.Builder
	for i := 0; i < len(s); i++ {
		if s[i] == 0x1b && i+1 < len(s) && s[i+1] == '[' {
			j := i + 2
			for j < len(s) && !((s[j] >= 'a' && s[j] <= 'z') || (s[j] >= 'A' && s[j] <= 'Z')) {
				j++
			}
			i = j
			continue
		}
		b.WriteByte(s[i])
	}
	return b.String()
}

const (
	cQ     = "\x1b[0;1;92m? \x1b[0m"
	cMsgOn = "\x1b[0;1;99m"
	cReset = "\x1b[0m"
	cHelp  = "\x1b[0;36m"
	cAns   = "\x1b[0;36m"
)

func surveyConfirm(msg string, def bool) (bool, error) {
	st, err := makeRaw(os.Stdin.Fd())
	if err != nil {
		return false, err
	}
	defer st.restore()
	out := os.Stdout
	hint := "(y/N) "
	if def {
		hint = "(Y/n) "
	}
	input := ""
	render := func() {
		fmt.Fprintf(out, "\r\x1b[2K%s%s%s %s\x1b[0;37m%s%s%s", cQ, cMsgOn, msg, cReset, hint, cReset, input)
	}
	render()
	kr := &keyReader{}
	for {
		k, r := kr.read()
		switch k {
		case keyCtrlC:
			fmt.Fprint(out, "\r\n")
			return false, fmt.Errorf("interrupt")
		case keyEnter:
			ans := strings.ToLower(strings.TrimSpace(input))
			var val bool
			switch ans {
			case "":
				val = def
			case "y", "yes":
				val = true
			case "n", "no":
				val = false
			default:
				input = ""
				render()
				continue
			}
			word := "No"
			if val {
				word = "Yes"
			}
			fmt.Fprintf(out, "\r\x1b[2K%s%s%s %s%s%s%s\r\n", cQ, cMsgOn, msg, cReset, cAns, word, cReset)
			return val, nil
		case keyBackspace:
			if len(input) > 0 {
				input = input[:len(input)-1]
			}
			render()
		default:
			if r != 0 {
				input += string(r)
				render()
			}
		}
	}
}

func surveyMultiSelect(msg string, options []string) ([]bool, error) {
	st, err := makeRaw(os.Stdin.Fd())
	if err != nil {
		return nil, err
	}
	defer st.restore()
	out := os.Stdout
	selected := make([]bool, len(options))
	cursor := 0
	width := termWidth()
	prevLines := 0
	fmt.Fprint(out, "\x1b[?25l")
	defer fmt.Fprint(out, "\x1b[?25h")
	render := func() {
		if prevLines > 0 {
			fmt.Fprintf(out, "\r\x1b[%dA", prevLines-1)
